def _ivas_cf_attach(session, force=False, on_status=None):
    """Pasang cf_clearance + UA milik MESIN INI ke session.

    cf_clearance terikat ke IP + User-Agent. Cookie cf_clearance yang dikirim user
    (dari HP/PC mereka) selalu ditolak Cloudflare di sini karena IP-nya beda, jadi
    kita buang dan ganti dengan clearance hasil challenge dari mesin ini sendiri.
    Return True kalau clearance berhasil dipasang.
    """
    if not IVAS_CF_OK:
        return False
    try:
        # Buang cf_clearance milik user (IP beda -> 403)
        try:
            session.cookies.clear(name='cf_clearance')
        except Exception:
            for c in list(session.cookies):
                if c.name == 'cf_clearance':
                    try:
                        session.cookies.clear(c.domain, c.path, c.name)
                    except Exception:
                        pass
        return ivas_cf.apply_clearance(session, force=force, on_status=on_status)
    except Exception as e:
        print(f"[CF] attach gagal: {e}")
        return False


def _ivas_cf_retry_403(session, response, on_status=None):
    """Kalau kena challenge Cloudflare (403 + cf-mitigated), ambil clearance baru.

    Return True kalau clearance sudah di-refresh dan request layak diulang.
    """
    if not IVAS_CF_OK or response is None:
        return False
    if response.status_code != 403:
        return False
    if not (response.headers.get('cf-mitigated') or 'Just a moment' in (response.text or '')[:3000]):
        return False
    print("[CF] 403 challenge terdeteksi — refresh cf_clearance")
    try:
        ivas_cf.clear_clearance_cache()
    except Exception:
        pass
    return _ivas_cf_attach(session, force=True, on_status=on_status)


def _ivas_session(cookies_dict, user_agent=None):
    """Buat requests.Session dengan cookie + UA konsisten (penting untuk Cloudflare)."""
    session = requests.Session()
    try:
        apply_proxy_to_session(session)
    except Exception:
        pass
    if cookies_dict:
        for key, value in cookies_dict.items():
            if value:
                session.cookies.set(key, value)
    ua = user_agent or DEFAULT_IVAS_UA
    session.headers.update({
        'User-Agent': ua,
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Connection': 'keep-alive',
    })
    # cf_clearance + UA lokal (menimpa UA di atas — memang harus sepasang)
    if _ivas_cf_attach(session):
        ua = session.headers.get('User-Agent', ua)
    return session, ua


