def ensure_csrf_fresh(session, csrf):
    """Refresh CSRF dari halaman SMS Received atau cookie XSRF-TOKEN."""
    try:
        from urllib.parse import unquote
        xsrf = session.cookies.get('XSRF-TOKEN')
        if xsrf:
            decoded = unquote(xsrf)
            if decoded:
                return decoded
    except Exception:
        pass
    try:
        resp = session.get(
            f"{BASE_URL}/portal/sms/received",
            timeout=15,
            headers={
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
                'Referer': f"{BASE_URL}/portal",
            },
        )
        if resp.status_code == 200:
            new_csrf = extract_csrf_from_page(resp.text)
            if new_csrf:
                return new_csrf
    except Exception as e:
        print(f"[NOTIF] ensure_csrf_fresh error: {e}")
    return csrf

try:

    import os
    os.environ['SSL_CERT_FILE'] = certifi.where()
    os.environ['REQUESTS_CA_BUNDLE'] = certifi.where()


    original_create_default_context = ssl.create_default_context

    def patched_create_default_context(*args, **kwargs):
        context = original_create_default_context(*args, **kwargs)
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        return context

    ssl.create_default_context = patched_create_default_context

    print(" SSL Certificate fix applied")

    import requests
    import urllib3
    urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

    # Patch requests to always use verify=False + auto-attach cf_clearance untuk ivasms.
    _old_request = requests.Session.request

    def _new_request(self, method, url, **kwargs):
        kwargs.setdefault('verify', False)
        is_ivas = isinstance(url, str) and 'ivasms.com' in url
        if is_ivas and not getattr(self, '_ivas_cf_ready', False):
            # Semua request ke ivasms wajib bawa cf_clearance + UA yang cocok.
            try:
                if _ivas_cf_attach(self):
                    self._ivas_cf_ready = True
            except Exception:
                pass
        resp = _old_request(self, method, url, **kwargs)
        if is_ivas:
            try:
                if _ivas_cf_retry_403(self, resp):
                    self._ivas_cf_ready = True
                    resp = _old_request(self, method, url, **kwargs)
            except Exception:
                pass
        return resp

    requests.Session.request = _new_request

    # Patch Session.__init__ untuk SELALU pasang browser User-Agent + header standar.
    # Cookie cf_clearance Cloudflare TERIKAT ke User-Agent — kalau UA beda dari saat
    # cookie didapat, Cloudflare langsung 403. Banyak callsite di file ini bikin
    # requests.Session() tanpa set UA, jadi kita inject sekali di sini.
    _old_session_init = requests.Session.__init__
    def _new_session_init(self, *args, **kwargs):
        _old_session_init(self, *args, **kwargs)
        try:
            # Kalau clearance lokal sudah ada, pakai UA-nya (harus sepasang).
            ua = None
            if IVAS_CF_OK:
                try:
                    ua = ivas_cf.get_ivas_ua()
                except Exception:
                    ua = None
            self.headers.update({
                'User-Agent': ua or get_random_user_agent(),
                'Accept-Language': 'en-US,en;q=0.9',
                'Sec-Ch-Ua-Mobile': '?0' if ua else '?1',
                'Sec-Ch-Ua-Platform': '"Windows"' if ua else '"Android"',
            })
        except Exception:
            pass
    requests.Session.__init__ = _new_session_init
    print(" Browser User-Agent patch applied to requests.Session")

except Exception as e:
    print(f" SSL fix error: {e}")
