# Global Monkeypatch to ignore CallbackQuery answer timeouts/errors
original_answer = CallbackQuery.answer
async def patched_answer(self, *args, **kwargs):
    try:
        return await original_answer(self, *args, **kwargs)
    except Exception as e:
        print(f"[DEBUG] CallbackQuery.answer ignored timeout/error: {e}")
        return None
CallbackQuery.answer = patched_answer

# Ignore "Message is not modified" — user double-tap / edit dengan isi sama.
# Tanpa ini traceback BadRequest bocor ke logs (mis. tombol RESET OTP diklik 2x).
from telegram import Message as _TgMessage
_original_edit_text = _TgMessage.edit_text
async def _patched_edit_text(self, *args, **kwargs):
    try:
        return await _original_edit_text(self, *args, **kwargs)
    except BadRequest as e:
        if "not modified" in str(e).lower():
            return self
        raise
_TgMessage.edit_text = _patched_edit_text
