def safe_markdown(text: str) -> str:
    """Escape karakter khusus untuk Markdown"""
    if not text:
        return text
    import re
    text = text.replace('_', '\\_')

    text = text.replace('*', '\\*')

    text = text.replace('', '\\')
    return text





