# email → {'until': float, 'reason': str}. Selama masih dalam masa ini,
# permintaan add via socket ditolak lebih awal tanpa buka koneksi.
_socket_blocked = {}
_socket_blocked_lock = threading.Lock()
SOCKET_BLOCK_TTL = int(os.getenv("IVAS_SOCKET_BLOCK_TTL", "900"))   # 15 menit


def is_socket_blocked_text(text) -> bool:
    """True kalau isi pesan hub menandakan akun/fitur add via socket diblokir."""
    if not text:
        return False
    low = str(text).lower()
    return any(k in low for k in SOCKET_BLOCKED_KEYWORDS)


def mark_socket_blocked(email, reason, ttl=None):
    """Tandai email ini tidak boleh pakai socket sampai beberapa waktu ke depan."""
    if not email:
        return
    with _socket_blocked_lock:
        _socket_blocked[email] = {
            'until': time.time() + (SOCKET_BLOCK_TTL if ttl is None else ttl),
            'reason': (str(reason) or 'diblokir server')[:120],
        }
    print(f"[SOCKET-BLOCK] {email} dihentikan: {str(reason)[:80]}")


def socket_blocked_reason(email):
    """Alasan blokir yang masih berlaku untuk email ini, atau None."""
    if not email:
        return None
    with _socket_blocked_lock:
        info = _socket_blocked.get(email)
        if not info:
            return None
        if info['until'] <= time.time():
            _socket_blocked.pop(email, None)
            return None
        return info['reason']


def clear_socket_blocked(email=None):
    """Buang tanda blokir socket (dipakai saat user login ulang / ganti akun)."""
    with _socket_blocked_lock:
        if email:
            _socket_blocked.pop(email, None)
        else:
            _socket_blocked.clear()



class ThreadLocalConnectionProxy:
    def __init__(self):
        self._local = threading.local()

    def _get_conn(self):
        if not hasattr(self._local, "conn"):
            # Create connection for this thread with busy timeout = 30 seconds
            self._local.conn = sqlite3.connect('ivas_bot.db', timeout=30, check_same_thread=False)
            self._local.cur = self._local.conn.cursor()
        return self._local.conn

    def _get_cur(self):
        self._get_conn()
        return self._local.cur

    def commit(self):
        self._get_conn().commit()

    def rollback(self):
        self._get_conn().rollback()

    def cursor(self):
        return self

    def execute(self, *args, **kwargs):
        return self._get_cur().execute(*args, **kwargs)

    def executemany(self, *args, **kwargs):
        return self._get_cur().executemany(*args, **kwargs)

    def fetchone(self, *args, **kwargs):
        return self._get_cur().fetchone(*args, **kwargs)

    def fetchall(self, *args, **kwargs):
        return self._get_cur().fetchall(*args, **kwargs)

    @property
    def description(self):
        return self._get_cur().description

    @property
    def rowcount(self):
        # Tanpa ini, akses cur.rowcount melempar AttributeError → banyak
        # blok "if cur.rowcount == 0" gagal diam-diam (mis. klaim invoice
        # paid & spend token). Teruskan ke cursor thread-local sebenarnya.
        return self._get_cur().rowcount

    @property
    def lastrowid(self):
        return self._get_cur().lastrowid

    def close(self):
        if hasattr(self._local, "conn"):
            try:
                self._local.conn.close()
            except:
                pass
            del self._local.conn
            if hasattr(self._local, "cur"):
                del self._local.cur

db_proxy = ThreadLocalConnectionProxy()
conn = db_proxy
cur = db_proxy

# ── PREMIUM DATABASE (premium_bot.db) — terpisah dari ivas_bot.db ──
# Database khusus untuk premium/token. Bisa di-download dari web dashboard.
class PremiumDBProxy:
    def __init__(self):
        self._local = threading.local()
        self._db_path = 'premium_bot.db'

    def _get_conn(self):
        if not hasattr(self._local, "conn"):
            self._local.conn = sqlite3.connect(
                self._db_path, timeout=30, check_same_thread=False
            )
            self._local.cur = self._local.conn.cursor()
        return self._local.conn

    def _get_cur(self):
        self._get_conn()
        return self._local.cur

    def commit(self):
        self._get_conn().commit()

    def rollback(self):
        self._get_conn().rollback()

    def cursor(self):
        return self

    def execute(self, *args, **kwargs):
        return self._get_cur().execute(*args, **kwargs)

    def executemany(self, *args, **kwargs):
        return self._get_cur().executemany(*args, **kwargs)

    def fetchone(self, *args, **kwargs):
        return self._get_cur().fetchone(*args, **kwargs)

    def fetchall(self, *args, **kwargs):
        return self._get_cur().fetchall(*args, **kwargs)

    @property
    def description(self):
        return self._get_cur().description

    @property
    def rowcount(self):
        return self._get_cur().rowcount

    @property
    def lastrowid(self):
        return self._get_cur().lastrowid

    def close(self):
        if hasattr(self._local, "conn"):
            try:
                self._local.conn.close()
            except:
                pass
            del self._local.conn
            if hasattr(self._local, "cur"):
                del self._local.cur

    def init_tables(self):
        """Create premium tables if not exist."""
        self.execute('''CREATE TABLE IF NOT EXISTS premium_access (
            user_id INTEGER PRIMARY KEY,
            expired_at TEXT NOT NULL,
            package TEXT,
            days INTEGER DEFAULT 0,
            invoice_id TEXT,
            granted_by INTEGER,
            total_paid INTEGER DEFAULT 0,
            buy_count INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        self.execute('''CREATE TABLE IF NOT EXISTS premium_invoices (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            invoice_id TEXT UNIQUE,
            package TEXT,
            days INTEGER,
            amount INTEGER,
            fee INTEGER,
            total INTEGER,
            status TEXT NOT NULL DEFAULT 'pending',
            qris_image TEXT,
            payment_link TEXT,
            expired_at TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            paid_at TIMESTAMP
        )''')
        self.execute('''CREATE INDEX IF NOT EXISTS idx_premium_inv_user
                       ON premium_invoices(user_id, created_at DESC)''')
        self.execute('''CREATE INDEX IF NOT EXISTS idx_premium_inv_status
                       ON premium_invoices(status)''')
        self.execute('''CREATE TABLE IF NOT EXISTS premium_tokens (
            user_id INTEGER PRIMARY KEY,
            balance INTEGER NOT NULL DEFAULT 0,
            total_bought INTEGER NOT NULL DEFAULT 0,
            total_spent INTEGER NOT NULL DEFAULT 0,
            total_refund INTEGER NOT NULL DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        self.execute('''CREATE TABLE IF NOT EXISTS token_ledger (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            delta INTEGER NOT NULL,
            balance_after INTEGER NOT NULL,
            kind TEXT NOT NULL,
            ref TEXT,
            note TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )''')
        self.execute('''CREATE INDEX IF NOT EXISTS idx_token_ledger_user
                       ON token_ledger(user_id, id DESC)''')
        self.execute('''CREATE INDEX IF NOT EXISTS idx_token_ledger_ref
                       ON token_ledger(ref)''')
        self.execute('''CREATE TABLE IF NOT EXISTS resetotp_trial (
            user_id INTEGER PRIMARY KEY,
            used INTEGER NOT NULL DEFAULT 0,
            first_used_at TIMESTAMP,
            last_used_at TIMESTAMP
        )''')
        self.commit()

        # Migration: kolom baru di premium_invoices
        try:
            self.execute("PRAGMA table_info(premium_invoices)")
            _inv_cols = {row[1] for row in self.fetchall()}
            if 'kind' not in _inv_cols:
                self.execute("ALTER TABLE premium_invoices ADD COLUMN kind TEXT DEFAULT 'days'")
            if 'tokens' not in _inv_cols:
                self.execute("ALTER TABLE premium_invoices ADD COLUMN tokens INTEGER DEFAULT 0")
            self.commit()
        except Exception as _e:
            print(f"[PREMIUM_DB] migrate warn: {_e}")

