# Garis pemisah premium (gradasi blok) — lebih keren dari ━━━.
_BAR = "▰▰▰▰▰▰▰▰▰▰▰▰▰▰▰▰▰▰"
_BAR_THIN = "▱▱▱▱▱▱▱▱▱▱▱▱▱▱▱▱▱▱"
# Penanda baris tanpa emoji (dipakai di dashboard & profil /start).
_DOT = "⌁"

# ── Batas & ritme ADD RANGE (fitur iVASMS) ────────────────────────────────
# Socket: 1 range butuh ±61 detik, jadi dibatasi 3 range dan dikerjakan
#         berurutan dengan jeda ±61 detik antar range.
# HTTP  : 2 range dikerjakan bersamaan, lalu jeda 1 menit, lanjut 2 lagi.
# MIX   : gabungan — per gelombang 2 range lewat HTTP + 1 range lewat socket
#         jalan bersamaan, lalu jeda ±61 detik (mengikuti ritme socket).
_SOCK_RANGE_MAX = 3
_HTTP_RANGE_MAX = 6
_SOCK_RANGE_DELAY = 61      # detik antar range (socket)
_HTTP_CHUNK_SIZE = 2        # range per gelombang (http)
_HTTP_CHUNK_DELAY = 60      # detik jeda antar gelombang (http)
_MIX_HTTP_PER_WAVE = 2      # range HTTP per gelombang (mode gabungan)
_MIX_SOCK_PER_WAVE = 1      # range socket per gelombang (mode gabungan)
_MIX_WAVE = _MIX_HTTP_PER_WAVE + _MIX_SOCK_PER_WAVE       # 3 range / gelombang
_MIX_WAVE_DELAY = _SOCK_RANGE_DELAY                        # jeda antar gelombang
# Maksimal = jatah socket + jatah HTTP (3 gelombang × 3 range).
_MIX_RANGE_MAX = _SOCK_RANGE_MAX * _MIX_WAVE

# user_id → True saat user menekan BATAL pada batch add range.
_batch_cancel = {}


def _mini_dots(done: int, total: int, cap: int = 10) -> str:
    """Progres gaya klasik: ●●○○ — pengganti bar panjang ████░░░░."""
    if total <= 0:
        return ""
    if total <= cap:
        done = max(0, min(done, total))
        return "●" * done + "○" * (total - done)
    filled = int(round(done / total * cap))
    return "●" * filled + "○" * (cap - filled)


def _quote(body: str, expandable: bool = False) -> str:
    """Bungkus teks dalam Telegram blockquote (format quote yg LO mau)."""
    tag = "blockquote expandable" if expandable else "blockquote"
    return f"<{tag}>{body}</blockquote>"


def _header(title: str, breadcrumb: str = "") -> str:
    bc = f"\n<i>{breadcrumb}</i>\n" if breadcrumb else "\n"
    return f"{em(E5,'🏴‍☠️')} <b>{_fancy_bold(title)}</b>{bc}{_BAR}"

def _footer() -> str:
    return f"{_BAR}\n{em(E4,'🎧')} <i>{_fancy_italic('Powered by')} </i><b>{_fancy_bold('DikZz')}</b>"

def _row(icon: str, label: str, value: str) -> str:
    return f"  {icon} <b>{label}:</b>  {value}"

def _screen(title: str, body: str, breadcrumb: str = "") -> str:
    """Layar HTML konsisten — SEMUA dibungkus blockquote (format quote)."""
    inner = f"{_header(title, breadcrumb)}\n{body}\n\n{_footer()}"
    return _quote(inner)


# ── Layar khusus fitur iVASMS ────────────────────────────────────────
# Semua pesan iVAS (login/cookies, live SMS, hapus semua, export, logout,
# monitor, top negara, all platform) dirender lewat helper di bawah supaya
# tampilannya seragam: blockquote + header "🏴‍☠️ JUDUL / breadcrumb / ▰▰▰".
def _ivas_screen(title: str, body: str, breadcrumb: str = "Home › iVASMS") -> str:
    return _screen(title, body, breadcrumb)


def _ivas_need_login(breadcrumb: str = "Home › iVASMS") -> str:
    """Layar standar 'belum login' untuk semua fitur iVAS."""
    return _ivas_screen(
        'BELUM LOGIN',
        f"  {em(E2,'⭐')} Kamu belum login ke <b>iVASMS</b>.\n"
        f"  {em(CE_LOGIN,'🍪')} Gunakan <code>/cookies</code> untuk masuk.",
        breadcrumb,
    )


def _ivas_session_expired(breadcrumb: str = "Home › iVASMS", user_id=None) -> str:
    """Layar standar 'session expired' untuk semua fitur iVAS.

    Kalau `user_id` diberikan, session yang sudah mati LANGSUNG dihapus dari
    database (tidak perlu /logout manual) — kalau user punya akun lain, salah
    satunya otomatis diaktifkan dan layar memberi tahu akun pengganti itu.
    """
    extra = ""
    if user_id is not None:
        try:
            deleted, next_email = purge_expired_session(user_id)
        except Exception:
            deleted, next_email = None, None
        if deleted:
            extra = f"\n  {_DOT} Session <code>{html.escape(str(deleted))}</code> dihapus dari database."
            if next_email:
                extra += (f"\n  {_DOT} Pindah otomatis ke "
                          f"<code>{html.escape(str(next_email))}</code>.")
    return _ivas_screen(
        'SESSION EXPIRED',
        f"  {em(E2,'⭐')} Sesi iVASMS sudah tidak valid.\n"
        f"  {em(CE_LOGIN,'🍪')} Login ulang dengan <code>/cookies</code>."
        + extra,
        breadcrumb,
    )


def _ivas_ok(title: str, body: str, breadcrumb: str = "Home › iVASMS") -> str:
    return _ivas_screen(title, f"  {em(E1,'⭐')} <b>BERHASIL</b>\n\n{body}", breadcrumb)


def _ivas_fail(title: str, body: str, breadcrumb: str = "Home › iVASMS") -> str:
    return _ivas_screen(title, f"  {em(E2,'⭐')} <b>GAGAL</b>\n\n{body}", breadcrumb)

