def _home_nav_row(user_id, page):
    """Baris geser halaman menu utama (pola sama dgn pagination /listdomain)."""
    row = []
    if page > 1:
        row.append(InlineKeyboardButton(
            f"{HOME_PAGE_LABEL[page-1].upper()}",
            callback_data=f"menu_page{page-1}_{user_id}",
            style="primary"))
    row.append(InlineKeyboardButton(
        f"{page}/{HOME_PAGES}",
        callback_data=f"menu_page{page}_{user_id}", style="success"))
    if page < HOME_PAGES:
        row.append(InlineKeyboardButton(
            f"{HOME_PAGE_LABEL[page+1].upper()}",
            callback_data=f"menu_page{page+1}_{user_id}",
            style="primary"))
    return row


