def _parse_iso(s):
    if not s:
        return None
    txt = str(s).strip().replace("T", " ").replace("Z", "")
    if "." in txt:
        txt = txt.split(".", 1)[0]
    txt = txt.split("+", 1)[0].strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            return datetime.strptime(txt, fmt)
        except Exception:
            continue
    return None


def _fmt_wib(dt) -> str:
    d = _parse_iso(dt) if not isinstance(dt, datetime) else dt
    if not d:
        return "-"
    return (d + timedelta(hours=7)).strftime("%d %b %Y %H:%M") + " WIB"


def _human_left(delta: timedelta) -> str:
    total = int(delta.total_seconds())
    if total <= 0:
        return "habis"
    d, rem = divmod(total, 86400)
    h, rem = divmod(rem, 3600)
    m = rem // 60
    if d:
        return f"{d} hari {h} jam" if h else f"{d} hari"
    if h:
        return f"{h} jam {m} menit" if m else f"{h} jam"
    return f"{m} menit" if m else "< 1 menit"


def _premium_from_row(user_id, row: dict):
    """Bentuk dict premium standar dari 1 baris premium_access."""
    exp = _parse_iso(row.get("expired_at"))
    return {
        "user_id": user_id, "expired_at": exp, "package": row.get("package"),
        "days": int(row.get("days") or 0), "invoice_id": row.get("invoice_id"),
        "granted_by": row.get("granted_by"),
        "total_paid": int(row.get("total_paid") or 0),
        "buy_count": int(row.get("buy_count") or 0),
        "active": bool(exp and exp > _now_utc()),
        "left": (exp - _now_utc()) if exp else None,
    }


def _get_premium_local(user_id):
    """Baca premium dari premium_bot.db."""
    try:
        _premium_db.execute(
            "SELECT expired_at, package, days, invoice_id, granted_by, "
            "total_paid, buy_count, updated_at FROM premium_access WHERE user_id = ?",
            (user_id,))
        row = _premium_db.fetchone()
    except Exception:
        return None
    if not row:
        return None
    result = _premium_from_row(user_id, {
        "expired_at": row[0], "package": row[1], "days": row[2],
        "invoice_id": row[3], "granted_by": row[4],
        "total_paid": row[5], "buy_count": row[6]})
    result["updated_at"] = row[7]
    return result


def get_premium(user_id):
    """Status premium user. LOKAL-FIRST — baca dari premium_bot.db saja.

    Bot tidak baca dari D1 lagi (mencegah rate limit issue dan conflict
    dual-bot). Data tetap di-push ke D1 supaya website bisa display.
    """
    return _get_premium_local(user_id)


def has_premium(user_id) -> bool:
    if is_owner(user_id):
        return True
    p = get_premium(user_id)
    return bool(p and p["active"])


def grant_premium(user_id, days: int, granted_by: int = None, invoice_id: str = None, amount: int = 0):
    """Kasih/perpanjang akses premium. Kalau masih aktif, tambah di atas sisa.

    Ditulis di remote D1 (atomik, penambahan hari dihitung di sana), lalu
    hasilnya di-mirror ke cache lokal. Kalau remote mati, tulis lokal saja
    dan push biasa — nanti tersusul full-sync berkala.
    """
    pkg = next((k for k, v in PREMIUM_PACKAGES.items() if v[2] == days), f"{days}d")
    res = _web_write("grant_premium", {
        "user_id": user_id, "days": int(days), "package": pkg,
        "granted_by": granted_by, "invoice_id": invoice_id,
        "amount": int(amount or 0)})
    if res is not None and res.get("ok"):
        row = res.get("row") or {}
        if row:
            _cache_local("premium_access", row)
        return _parse_iso(res.get("expired_at")) or _now_utc() + timedelta(days=days)

    # Fallback: remote tidak terjangkau → tulis ke premium_bot.db + push fire-and-forget.
    now = _now_utc()
    p = _get_premium_local(user_id)
    base = p["expired_at"] if (p and p["active"]) else now
    new_exp = base + timedelta(days=days)
    try:
        _premium_db.execute("""
            INSERT INTO premium_access (user_id, expired_at, package, days, invoice_id, granted_by, total_paid, buy_count, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                expired_at = excluded.expired_at,
                package = excluded.package,
                days = excluded.days,
                invoice_id = COALESCE(excluded.invoice_id, premium_access.invoice_id),
                granted_by = excluded.granted_by,
                total_paid = premium_access.total_paid + excluded.total_paid,
                buy_count = premium_access.buy_count + 1,
                updated_at = excluded.updated_at
        """, (user_id, _iso(new_exp), pkg, days, invoice_id, granted_by, amount, _iso(now)))
        _premium_db.commit()
    except Exception as e:
        logging.warning("[PREMIUM] grant err: %s", e)
    # Push ke D1 HANYA kalau dari invoice (amount > 0) — manual grant tidak push.
    if amount > 0 and invoice_id:
        _web_push_premium(user_id)
    return new_exp


# ── SALDO TOKEN ─────────────────────────────────────────────────
# Token dipakai user yang tidak mau langganan harian: 1x jalan RESET OTP
# memotong RESETOTP_TOKEN_COST token, dan token dikembalikan otomatis
# kalau prosesnya gagal (pool sender kosong, pipeline error, dsb).

def _get_token_row_local(user_id):
    """Baca baris token dari premium_bot.db. Return dict standar."""
    try:
        _premium_db.execute("SELECT balance, total_bought, total_spent, total_refund "
                    "FROM premium_tokens WHERE user_id = ?", (user_id,))
        row = _premium_db.fetchone()
    except Exception:
        row = None
    if not row:
        return {"balance": 0, "bought": 0, "spent": 0, "refund": 0}
    return {"balance": int(row[0] or 0), "bought": int(row[1] or 0),
            "spent": int(row[2] or 0), "refund": int(row[3] or 0)}


def get_token_stats(user_id):
    """Ringkasan token: saldo + total beli/pakai/refund. LOKAL-FIRST."""
    return _get_token_row_local(user_id)


def get_tokens(user_id) -> int:
    """Saldo token user. 0 kalau belum pernah beli."""
    return get_token_stats(user_id)["balance"]


def _token_log(user_id, delta: int, balance_after: int, kind: str,
               ref: str = None, note: str = None):
    """Catat mutasi token ke ledger di premium_bot.db."""
    try:
        _premium_db.execute(
            "INSERT INTO token_ledger (user_id, delta, balance_after, kind, ref, note) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (user_id, int(delta), int(balance_after), kind, ref, note))
        _premium_db.commit()
        _rid = _premium_db.lastrowid
    except Exception as e:
        logging.warning("[TOKEN] ledger err: %s", e)
        return
    # Dorong ledger + saldo terbaru ke dashboard (non-blocking).
    _web_push_ledger(_rid)
    _web_push_tokens(user_id)


def add_tokens(user_id, amount: int = 0, kind: str = "buy",
               ref: str = None, note: str = None) -> int:
    """Tambah token. Return saldo baru. LOKAL-FIRST: tulis di premium_bot.db,
    lalu push snapshot ke D1 (fire-and-forget) supaya website ikut ter-update.
    """
    amount = int(amount or 0)
    if amount <= 0:
        return get_tokens(user_id)
    now = _iso(_now_utc())
    try:
        _premium_db.execute("""
            INSERT INTO premium_tokens (user_id, balance, total_bought, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                balance = premium_tokens.balance + excluded.balance,
                total_bought = premium_tokens.total_bought + excluded.total_bought,
                updated_at = excluded.updated_at
        """, (user_id, amount, amount if kind in ("buy", "grant") else 0, now))
        _premium_db.commit()
    except Exception as e:
        logging.warning("[TOKEN] add err: %s", e)
        return _get_token_row_local(user_id)["balance"]
    bal = _get_token_row_local(user_id)["balance"]
    _token_log(user_id, amount, bal, kind, ref, note)
    _web_push_tokens(user_id)
    return bal


def spend_tokens(user_id, amount: int = None, ref: str = None,
                 note: str = None) -> bool:
    """Potong token secara atomik. False kalau saldo tidak cukup.

    Owner tidak pernah dipotong (unlimited). LOKAL-FIRST: potong di
    premium_bot.db dengan guard `balance >= amount`, lalu push snapshot
    ke D1 (fire-and-forget).
    """
    if is_owner(user_id):
        return True
    amount = int(RESETOTP_TOKEN_COST if amount is None else amount)
    if amount <= 0:
        return True
    try:
        _premium_db.execute(
            "UPDATE premium_tokens SET balance = balance - ?, "
            "total_spent = total_spent + ?, updated_at = ? "
            "WHERE user_id = ? AND balance >= ?",
            (amount, amount, _iso(_now_utc()), user_id, amount))
        _premium_db.commit()
        if _premium_db.rowcount == 0:
            return False
    except Exception as e:
        logging.warning("[TOKEN] spend err: %s", e)
        return False
    bal = _get_token_row_local(user_id)["balance"]
    _token_log(user_id, -amount, bal, "spend", ref, note)
    _web_push_tokens(user_id)
    return True


def refund_tokens(user_id, amount: int = None, ref: str = None,
                  note: str = None) -> int:
    """Kembalikan token yang sudah dipotong (proses gagal). Return saldo baru.

    Idempoten per `ref` — dicek di ledger lokal, jadi ref yang sama
    tidak pernah dikembalikan dua kali. LOKAL-FIRST + push snapshot.
    """
    if is_owner(user_id):
        return get_tokens(user_id)
    amount = int(RESETOTP_TOKEN_COST if amount is None else amount)
    if amount <= 0:
        return get_tokens(user_id)

    if ref:
        try:
            _premium_db.execute("SELECT 1 FROM token_ledger WHERE ref = ? AND kind = 'refund' "
                        "LIMIT 1", (ref,))
            if _premium_db.fetchone():
                logging.info("[TOKEN] refund %s sudah pernah diproses, dilewati", ref)
                return _get_token_row_local(user_id)["balance"]
        except Exception:
            pass
    now = _iso(_now_utc())
    try:
        _premium_db.execute("""
            INSERT INTO premium_tokens (user_id, balance, total_refund, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                balance = premium_tokens.balance + excluded.balance,
                total_refund = premium_tokens.total_refund + excluded.total_refund,
                updated_at = excluded.updated_at
        """, (user_id, amount, amount, now))
        _premium_db.commit()
    except Exception as e:
        logging.warning("[TOKEN] refund err: %s", e)
        return _get_token_row_local(user_id)["balance"]
    bal = _get_token_row_local(user_id)["balance"]
    _token_log(user_id, amount, bal, "refund", ref, note)
    logging.info("[TOKEN] refund %s token ke user %s (%s)", amount, user_id, note or ref)
    _web_push_tokens(user_id)
    return bal


def _trial_reset_if_needed(user_id, used: int, last_used_at: str | None) -> tuple[int, str | None]:
    """Reset counter trial kalau last_used_at > RESETOTP_TRIAL_RESET_HOURS jam lalu.

    Return (new_used, last_used_at) — counter di-reset ke 0 kalau sudah lewat 24 jam.
    """
    if not last_used_at or used <= 0:
        return used, last_used_at
    last = _parse_iso(last_used_at)
    if not last:
        return used, last_used_at
    elapsed = (_now_utc() - last).total_seconds()
    if elapsed >= RESETOTP_TRIAL_RESET_HOURS * 3600:
        # Reset counter — user dapat jatah baru
        try:
            _premium_db.execute(
                "UPDATE resetotp_trial SET used = 0 WHERE user_id = ?", (user_id,))
            _premium_db.commit()
        except Exception:
            pass
        return 0, last_used_at
    return used, last_used_at


def _get_trial_local(user_id) -> dict:
    """Status trial dari cache lokal (dengan auto-reset harian)."""
    try:
        _premium_db.execute(
            "SELECT used, last_used_at FROM resetotp_trial WHERE user_id = ?",
            (user_id,))
        row = _premium_db.fetchone()
        used = int((row[0] if row else 0) or 0)
        last_at = row[1] if row else None
    except Exception:
        used, last_at = 0, None
    used, last_at = _trial_reset_if_needed(user_id, used, last_at)
    return {"used": used, "left": max(0, RESETOTP_TRIAL_LIMIT - used),
            "last_used_at": last_at}


def _trial_from_row(row: dict) -> dict:
    used = int((row or {}).get("used") or 0)
    last_at = (row or {}).get("last_used_at")
    return {"used": used, "left": max(0, RESETOTP_TRIAL_LIMIT - used),
            "last_used_at": last_at}


def get_trial(user_id) -> dict:
    """Status trial gratis RESET OTP. {'used': n, 'left': sisa}. LOKAL-FIRST."""
    return _get_trial_local(user_id)


def trial_reset_time(user_id) -> str | None:
    """Waktu reset trial berikutnya (ISO string) kalau trial sedang habis.

    Return None kalau trial masih ada / belum pernah dipakai.
    """
    t = get_trial(user_id)
    if t["left"] > 0:
        return None
    last = _parse_iso(t.get("last_used_at"))
    if not last:
        return None
    reset_at = last + timedelta(hours=RESETOTP_TRIAL_RESET_HOURS)
    return _iso(reset_at)


def trial_left(user_id) -> int:
    """Sisa jatah trial. Owner dianggap tak terbatas (tapi tidak kena trial)."""
    if is_owner(user_id):
        return RESETOTP_TRIAL_LIMIT
    return get_trial(user_id)["left"]


def consume_trial(user_id) -> int:
    """Pakai 1 jatah trial (dipanggil HANYA saat proses berhasil).

    Return sisa trial setelah dipotong. Owner tidak dipotong.
    LOKAL-FIRST: tulis di premium_bot.db, push snapshot ke D1.
    """
    if is_owner(user_id):
        return RESETOTP_TRIAL_LIMIT
    now = _iso(_now_utc())
    try:
        _premium_db.execute("""
            INSERT INTO resetotp_trial (user_id, used, first_used_at, last_used_at)
            VALUES (?, 1, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                used = resetotp_trial.used + 1,
                last_used_at = excluded.last_used_at
        """, (user_id, now, now))
        _premium_db.commit()
    except Exception as e:
        logging.warning("[TRIAL] consume err: %s", e)
    _web_push_trial(user_id)
    return _get_trial_local(user_id)["left"]


def try_reserve_trial(user_id) -> bool:
    """Pesan 1 jatah trial SECARA ATOMIK di AWAL run (sebelum proses jalan).

    Return True kalau jatah berhasil dipesan — dijamin `used` TIDAK pernah
    melewati RESETOTP_TRIAL_LIMIT walau ada beberapa run paralel, karena
    guard `UPDATE ... WHERE used < LIMIT` dijalankan di remote D1 (atau di
    SQLite lokal saat remote tidak terjangkau). False kalau jatah sudah
    habis / kalah balapan.

    Kalau prosesnya gagal, panggil refund_trial() untuk mengembalikan jatah.
    Owner tak terbatas → selalu True tanpa menulis DB.
    """
    if is_owner(user_id):
        return True
    # Reset counter dulu kalau sudah lewat 24 jam (daily trial).
    _get_trial_local(user_id)
    now = _iso(_now_utc())
    try:
        _premium_db.execute(
            "INSERT OR IGNORE INTO resetotp_trial (user_id, used, first_used_at, last_used_at) "
            "VALUES (?, 0, ?, ?)", (user_id, now, now))
        _premium_db.execute(
            "UPDATE resetotp_trial SET used = used + 1, "
            "first_used_at = COALESCE(first_used_at, ?), last_used_at = ? "
            "WHERE user_id = ? AND used < ?",
            (now, now, user_id, RESETOTP_TRIAL_LIMIT))
        _premium_db.commit()
        reserved = (_premium_db.rowcount == 1)
    except Exception as e:
        logging.warning("[TRIAL] reserve err: %s", e)
        return False
    if reserved:
        _web_push_trial(user_id)
    return reserved


def refund_trial(user_id) -> int:
    """Kembalikan 1 jatah trial yang tadi dipesan (proses gagal total).

    Return sisa trial setelah dikembalikan. Tidak pernah turun di bawah 0.
    Owner tidak terpengaruh. LOKAL-FIRST + push snapshot.
    """
    if is_owner(user_id):
        return RESETOTP_TRIAL_LIMIT
    now = _iso(_now_utc())
    try:
        _premium_db.execute(
            "UPDATE resetotp_trial SET used = MAX(0, used - 1), last_used_at = ? "
            "WHERE user_id = ? AND used > 0", (now, user_id))
        _premium_db.commit()
    except Exception as e:
        logging.warning("[TRIAL] refund err: %s", e)
    _web_push_trial(user_id)
    return _get_trial_local(user_id)["left"]


def _has_paid_history(user_id) -> bool:
    """True kalau user PERNAH punya token/premium (beli atau di-grant).

    Dipakai untuk mematikan trial: trial HANYA untuk user yang benar-benar
    baru (belum pernah punya token/premium). Sekali punya → trial mati,
    langsung token (kepotong) atau harus bayar.

    Dibaca lewat get_premium/get_token_stats supaya ikut remote D1 —
    kalau tidak, user yang datanya cuma ada di remote bisa dapat trial ulang.
    """
    if is_owner(user_id):
        return True
    if get_premium(user_id) is not None:
        return True
    st = get_token_stats(user_id)
    return bool(st["balance"] > 0 or st["bought"] > 0)


def can_use_resetotp(user_id) -> bool:
    """Boleh pakai RESET OTP? Langganan aktif ATAU token cukup ATAU
    (khusus user baru yang belum pernah punya token/premium) sisa trial."""
    if has_premium(user_id):
        return True
    if get_tokens(user_id) >= RESETOTP_TOKEN_COST:
        return True
    # Trial hanya untuk user yang belum pernah punya token/premium.
    if _has_paid_history(user_id):
        return False
    return trial_left(user_id) > 0


def resetotp_access_mode(user_id) -> str:
    """Cara akses yang akan dipakai user untuk run berikutnya.

    'premium' (langganan/owner) | 'token' | 'trial' | 'none'.
    Urutan prioritas: langganan → token → trial. Langganan didahulukan
    supaya token/trial user tidak terpotong selama masih ada langganan.

    Trial HANYA untuk user baru yang belum pernah punya token/premium.
    Begitu user pernah punya (walau habis), trial tidak berlaku lagi —
    langsung token (kepotong) atau harus bayar.
    """
    if has_premium(user_id):
        return "premium"
    if get_tokens(user_id) >= RESETOTP_TOKEN_COST:
        return "token"
    if not _has_paid_history(user_id) and trial_left(user_id) > 0:
        return "trial"
    return "none"


def _mgpay_create_invoice(amount: int):
    """Buat invoice QRIS via api.buatqris.site. Return dict gateway atau None kalau gagal."""
    payload = {
        "action": "api_create_qris",
        "account_id": BUATQRIS_ACCOUNT_ID,
        "secret_token": BUATQRIS_SECRET_TOKEN,
        "amount": str(amount),
        "qris_method": "qris_two",
    }
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
    }
    try:
        r = requests.post(BUATQRIS_URL, headers=headers, data=payload, timeout=BUATQRIS_TIMEOUT)
        data = r.json()
        if data.get("success") and data.get("data"):
            d = data["data"]
            return {
                "success": True,
                "invoice_id": d.get("transaction_id"),
                "amount": d.get("amount", amount),
                "fee": d.get("admin_fee", 0),
                "total": d.get("total_amount", amount),
                "qris_image": d.get("qris_image") or d.get("qr_url"),
                "payment_link": d.get("payment_url"),
                "expired_at": d.get("expired_at"),
                "raw": d,
            }
        logging.warning("[BUATQRIS] create invoice ditolak: %s", data)
    except Exception as e:
        logging.warning("[BUATQRIS] create invoice error: %s", e)
    return None


