def _qris_photo_payload(photo_val: str):
    """Convert base64 data URL atau URL biasa ke object yang valid untuk send_photo."""
    if not photo_val:
        return None
    s = str(photo_val).strip()
    if s.startswith("data:image/"):
        try:
            import base64, io
            _, b64data = s.split(",", 1)
            raw_bytes = base64.b64decode(b64data)
            bio = io.BytesIO(raw_bytes)
            bio.name = "qris.png"
            bio.seek(0)
            return bio
        except Exception as ex:
            logging.warning("[PREMIUM] decode base64 qris err: %s", ex)
            return None
    return s


