def premium_status_line(user_id) -> str:
    """Satu baris status RESET OTP untuk layar /fix."""
    if is_owner(user_id):
        return f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E1,'✅')} Unlimited (Owner)"
    p = get_premium(user_id)
    tok = get_tokens(user_id)
    if p and p["active"]:
        left = _human_left(p["left"])
        extra = f" · {tok} token" if tok else ""
        return f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E1,'✅')} Langganan aktif (sisa {left}){extra}"
    if tok >= RESETOTP_TOKEN_COST:
        pakai = tok // RESETOTP_TOKEN_COST
        return (f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E1,'✅')} "
                f"{tok} token (~{pakai}x pakai)")
    if tok > 0:
        return (f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E2,'❌')} "
                f"{tok} token (kurang, butuh {RESETOTP_TOKEN_COST})")
    tl = trial_left(user_id)
    if tl > 0 and not _has_paid_history(user_id):
        return (f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E3,'🎁')} "
                f"Trial gratis {tl}/{RESETOTP_TRIAL_LIMIT} (reset tiap 24 jam)")
    # Trial habis — tunjukkan kapan reset
    reset_at = trial_reset_time(user_id)
    if reset_at:
        reset_dt = _parse_iso(reset_at)
        if reset_dt:
            remaining = reset_dt - _now_utc()
            hours = int(remaining.total_seconds() // 3600)
            mins = int((remaining.total_seconds() % 3600) // 60)
            time_str = f"{hours}j {mins}m" if hours > 0 else f"{mins} menit"
            return (f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E2,'❌')} Trial habis"
                    f" — reset dalam <b>{time_str}</b>")
    return f"  {em(E5,'🔑')} <b>Reset OTP:</b> {em(E2,'❌')} Tidak aktif"


