def _ban_user_from_bot(target_id, reason="", banned_by=None, username=None):
    """Blacklist user dari SEMUA fitur bot (dipakai /ban & auto-ban report).

    - Insert ke banned_users, hapus dari allowed_users + admins.
    - Logout session & stop semua monitoring.
    Return (ok: bool, msg: str). Owner (USER_ID) tidak akan pernah di-ban.
    """
    try:
        target_id = int(target_id)
    except (TypeError, ValueError):
        return False, "target id invalid"
    if target_id == USER_ID:
        return False, "owner kebal"
    if is_banned(target_id):
        return True, "sudah banned"
    try:
        cur.execute(
            "INSERT OR REPLACE INTO banned_users (user_id, username, banned_by, reason) VALUES (?, ?, ?, ?)",
            (target_id, username, banned_by if banned_by is not None else USER_ID, reason or ""),
        )
        cur.execute("DELETE FROM allowed_users WHERE user_id = ?", (target_id,))
        cur.execute("DELETE FROM admins WHERE user_id = ?", (target_id,))
        conn.commit()

        try:
            logout_user(target_id)
        except Exception:
            pass

        if target_id in active_notif_monitor:
            active_notif_monitor.remove(target_id)
            notif_start_time.pop(target_id, None)
            notif_sms_count.pop(target_id, None)
            notif_seen_sms.pop(target_id, None)

        sms_aktif_users.discard(target_id)
        sms_aktif_seen.pop(target_id, None)
        sms_aktif_start_time.pop(target_id, None)
        sms_aktif_count.pop(target_id, None)
        return True, "ok"
    except Exception as e:
        return False, str(e)


def _unban_user_from_bot(target_id, actor_id=None, username=None):
    """Lepas user dari blacklist bot (dipakai /unban semua mode).

    Hapus dari banned_users + re-add ke allowed_users.
    Return (was_banned: bool, ok: bool, msg: str).
    """
    try:
        target_id = int(target_id)
    except (TypeError, ValueError):
        return False, False, "target id invalid"
    was = is_banned(target_id)
    try:
        cur.execute("DELETE FROM banned_users WHERE user_id = ?", (target_id,))
        uname_db = username or f"User_{target_id}"
        cur.execute(
            "INSERT OR IGNORE INTO allowed_users (user_id, username, added_by) VALUES (?, ?, ?)",
            (target_id, uname_db, actor_id if actor_id is not None else USER_ID),
        )
        conn.commit()
        return was, True, "ok"
    except Exception as e:
        return was, False, str(e)


async def ban_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Command /ban - Blacklist user dari semua fitur bot (owner/admin only)
    Support: /ban (reply), /ban user_id, /ban @username
    """
    user_id = update.effective_user.id
    if not (is_owner(user_id) or is_admin(user_id)):
        return

    target_id = None
    target_username = None

    # ── Mode 1: Reply ke pesan di grup ──
    if update.message.reply_to_message and not context.args:
        replied_user = update.message.reply_to_message.from_user
        if replied_user:
            target_id = replied_user.id
            target_username = replied_user.username
    # ── Mode 2: Pakai args (ID atau @username) ──
    elif context.args:
        target_input = context.args[0].strip()

        if target_input.startswith('@'):
            username = target_input[1:]
            target_username = username
            try:
                chat = await context.bot.get_chat(target_input)
                if chat:
                    target_id = chat.id
                    target_username = chat.username or username
            except Exception as e:
                print(f"[BAN] get_chat({target_input}) fail: {e}")

            if not target_id:
                try:
                    cur.execute(
                        "SELECT user_id, username FROM allowed_users WHERE username = ? COLLATE NOCASE",
                        (username,),
                    )
                    r = cur.fetchone()
                    if r:
                        target_id = r[0]
                        target_username = r[1] or username
                except:
                    pass

            if not target_id:
                await update.message.reply_text(
                    _screen('GAGAL', (
                        f"{em(E2, '⛔')} Username <code>{target_input}</code> tidak ditemukan.\n"
                        f"User belum pernah /start ke bot."
                    )),
                    parse_mode=ParseMode.HTML
                )
                return
        else:
            try:
                target_id = int(target_input)
            except ValueError:
                await update.message.reply_text(
                    _screen('FORMAT SALAH', f"{em(E2, '⛔')} Gunakan User ID (angka) atau @username."),
                    parse_mode=ParseMode.HTML
                )
                return
    else:
        # Gak ada args dan gak reply
        await update.message.reply_text(
            _screen('BAN USER', (
                f"{em(E2, '⛔')} Gunakan:\n"
                f"  • <code>/ban</code> (reply pesan di grup)\n"
                f"  • <code>/ban 123456789</code> (User ID)\n"
                f"  • <code>/ban @username</code>\n\n"
                f"User yang di-ban tidak bisa pakai semua fitur bot."
            )),
            parse_mode=ParseMode.HTML
        )
        return

    if target_id == USER_ID:
        await update.message.reply_text(_screen('BAN', f"{em(E2, '⛔')} Tidak bisa memblokir Owner!"), parse_mode=ParseMode.HTML)
        return

    # Cek apakah sudah banned
    if is_banned(target_id):
        await update.message.reply_text(
            _screen('BAN', f"{em(E2, '⛔')} User <code>{target_id}</code> sudah di-blacklist."),
            parse_mode=ParseMode.HTML
        )
        return

    try:
        ok, msg = _ban_user_from_bot(
            target_id, reason="", banned_by=user_id, username=target_username
        )
        if not ok:
            await update.message.reply_text(
                _screen('BAN', f"{em(E2,'⭐')} Gagal memblokir user: {msg}"),
                parse_mode=ParseMode.HTML,
            )
            return

        uname_text = f" (@{target_username})" if target_username else ""
        await update.message.reply_text(
            _screen('USER BLACKLISTED', (
                f"{em(E2, '⛔')} <b>Berhasil di-ban!</b>\n\n"
                f"  {em(CE_PROFILE, '👤')} User: <code>{target_id}</code>{uname_text}\n"
                f"  {em(E1, '✅')} Ditambahkan ke blacklist\n"
                f"  {em(E1, '✅')} Dihapus dari allowed_users\n"
                f"  {em(E1, '✅')} Dihapus dari admins\n"
                f"  {em(E1, '✅')} Session di-logout\n"
                f"  {em(E1, '✅')} Monitoring dihentikan\n\n"
                f"<i>User tidak bisa pakai semua fitur bot. /unban untuk membuka.</i>"
            )),
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        await update.message.reply_text(_screen('BAN', f"{em(E2,'⭐')} Gagal memblokir user: {e}"), parse_mode=ParseMode.HTML)

async def unban_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Command /unban — Dual purpose:
    1. /unban {user_id / @username}  atau reply pesan → lepas blokir user dari BOT (owner/admin)
    2. /unban wa {nomor_wa}          → kirim WA unban request via 5 sender (OWNER ONLY)

    Catatan: WA-unban HARUS pakai prefix 'wa' biar ID Telegram (angka) tidak
    salah dianggap nomor WA. Tanpa 'wa', semua angka = User ID Telegram → unban BOT.
    """
    user_id = update.effective_user.id
    args = list(context.args or [])

    # ── Jalur WA UNBAN — eksplisit: /unban wa <nomor> (owner only, 5 sender) ──
    if args and args[0].strip().lower() in ("wa", "whatsapp"):
        raw = " ".join(args[1:])
        numbers = _parse_fix_numbers(raw) if raw else []
        if not is_owner(user_id):
            await update.message.reply_text(
                _screen('UNBAN WHATSAPP',
                        f"{em(E2,'❌')} <b>Fitur ini hanya untuk owner.</b>"),
                parse_mode=ParseMode.HTML,
            )
            return
        if not numbers:
            await update.message.reply_text(
                _screen('UNBAN WHATSAPP', (
                    f"{em(E2,'❌')} Nomor tidak valid.\n"
                    f"Gunakan: <code>/unban wa 6285757411154</code>\n"
                    f"atau <code>/unban wa 628xxx, 628yyy</code>"
                )),
                parse_mode=ParseMode.HTML,
            )
            return

        # Tampilkan konfirmasi dulu dengan inline buttons
        num_list = "\n".join(
            f"  {em(CE_NOMOR,'📞')} <code>+{n}</code>" for n in numbers
        )
        text = _screen('UNBAN WHATSAPP', (
            f"{em(CE_WHATSAPP,'❤️')} <b>Unban WhatsApp — 5× Sender</b>\n\n"
            f"{em(E6,'🚀')} <b>Nomor yang akan diproses ({len(numbers)}):</b>\n"
            f"{num_list}\n\n"
            f"  {em(CE_WHATSAPP,'❤️')} Sender per nomor: <b>5</b>\n"
            f"  {em(CE_EMAIL,'📩')} Total email: <b>{len(numbers) * UNBAN_SENDERS_PER_NOMOR}</b>\n"
            f"  {em(CE_WAKTU,'⏲')} Estimasi: <b>~{len(numbers) * 2} menit</b>\n\n"
            f"<i>Setiap nomor akan dikirim dari 5 sender berbeda ke WhatsApp support.</i>"
        ))

        # Simpan data nomor untuk callback
        unban_data_key = f"unban_numbers_{user_id}"
        context.user_data[unban_data_key] = numbers

        keyboard = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("KIRIM SEKARANG",
                    callback_data=f"unban_send_{user_id}",
                    style="primary",
                ),
            ],
            [
                InlineKeyboardButton("BATAL",
                    callback_data=f"unban_cancel_{user_id}",
                    style="danger",
                ),
            ],
        ])
        await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=keyboard)
        return

    # ── Jalur BOT UNBAN: reply / @username / ID Telegram (owner/admin) ──
    if not (is_owner(user_id) or is_admin(user_id)):
        return

    target_id = None
    target_username = None

    # Mode 1: Reply ke pesan di grup (tanpa args)
    if getattr(update.message, "reply_to_message", None) and not args:
        replied_user = update.message.reply_to_message.from_user
        if replied_user:
            target_id = replied_user.id
            target_username = replied_user.username
        else:
            await update.message.reply_text(
                _screen('UNBAN', f"{em(E2, '⭐')} Tidak bisa membaca user dari pesan itu."),
                parse_mode=ParseMode.HTML,
            )
            return
    # Mode 2: Pakai args (@username / username / ID Telegram)
    elif args:
        target_input = args[0].strip()
        if target_input.startswith('@'):
            target_id, target_username, err = await resolve_username_to_id_async(target_input, context)
            if not target_id:
                await update.message.reply_text(
                    _screen('GAGAL', f"{em(E2, '⭐')} {err}"),
                    parse_mode=ParseMode.HTML
                )
                return
        elif re.fullmatch(r"-?\d+", target_input):
            target_id = int(target_input)
        else:
            # username tanpa '@'
            target_id, target_username, err = await resolve_username_to_id_async("@" + target_input, context)
            if not target_id:
                await update.message.reply_text(
                    _screen('GAGAL', f"{em(E2, '⭐')} {err}"),
                    parse_mode=ParseMode.HTML
                )
                return
    else:
        await update.message.reply_text(
            _screen('UNBAN', (
                f"{em(E1, '✅')} <b>Buka blokir user dari bot:</b>\n"
                f"  • <code>/unban</code> (reply pesan user di grup)\n"
                f"  • <code>/unban @username</code>\n"
                f"  • <code>/unban 123456789</code> (User ID Telegram)\n\n"
                f"<b>Unban WhatsApp (owner only):</b>\n"
                f"  • <code>/unban wa 6285757411154</code>\n"
                f"  • <code>/unban wa 628xxx, 628yyy</code>\n"
                f"  → kirim 5 sender otomatis ke WA support"
            )),
            parse_mode=ParseMode.HTML
        )
        return

    if target_id == USER_ID:
        await update.message.reply_text(
            _screen('UNBAN', f"{em(E1, '✅')} Owner tidak pernah di-blacklist."),
            parse_mode=ParseMode.HTML,
        )
        return

    was_banned, ok, msg = _unban_user_from_bot(
        target_id, actor_id=user_id, username=target_username
    )
    if not ok:
        await update.message.reply_text(
            _screen('UNBAN', f"{em(E2,'⭐')} Gagal unban user: {msg}"),
            parse_mode=ParseMode.HTML,
        )
        return

    uname_text = f" (@{target_username})" if target_username else ""
    if not was_banned:
        await update.message.reply_text(
            _screen('UNBAN', (
                f"{em(CE_HELP, '💡')} User <code>{target_id}</code>{uname_text} "
                f"tidak sedang di-blacklist.\n"
                f"Aksesnya sudah dipastikan aktif."
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    await update.message.reply_text(
        _screen('USER UNBANNED', (
            f"{em(E1, '✅')} <b>Berhasil unban!</b>\n\n"
            f"  {em(CE_PROFILE, '👤')} User: <code>{target_id}</code>{uname_text}\n"
            f"  {em(E1, '✅')} Dihapus dari blacklist\n"
            f"  {em(E1, '✅')} Akses bot telah dipulihkan\n\n"
            f"<i>User bisa pakai semua fitur bot lagi.</i>"
        )),
        parse_mode=ParseMode.HTML
    )


