def _sitepro_ping() -> bool:
    """Quick TCP probe to site.pro:443 (2s timeout). False = unreachable."""
    import socket as _sock
    try:
        s = _sock.socket(_sock.AF_INET, _sock.SOCK_STREAM)
        s.settimeout(2)
        s.connect(("site.pro", 443))
        s.close()
        return True
    except Exception:
        return False


def _sitepro_refresh_daemon():
    """Daemon: tiap 10 menit refresh session semua akun Site.pro biar tidak mati.

    Circuit breaker: kalau site.pro unreachable, backoff eksponensial
    (10m → 20m → 40m, cap 60m). Reset begitu ping berhasil lagi.
    """
    time.sleep(60)
    _fail_streak = 0
    _MAX_BACKOFF = 3600
    while True:
        try:
            if not _sitepro_ping():
                _fail_streak += 1
                backoff = min(SENDER_REFRESH_SECS * (2 ** _fail_streak), _MAX_BACKOFF)
                print(f"[SITEPRO] site.pro unreachable — skip refresh, backoff {backoff}s (streak={_fail_streak})")
                time.sleep(backoff)
                continue
            _fail_streak = 0
            ok, total = refresh_all_sessions(cur, conn)
            if total:
                print(f"[SITEPRO] Refresh session: {ok}/{total} akun hidup")
        except Exception as e:
            print(f"[SITEPRO] Refresh daemon error: {e}")
        time.sleep(SENDER_REFRESH_SECS)


def _clean_wa_reply(text: str) -> str:
    """Hilangkan jejak email account & domain site.pro dari body balasan.

    - Hapus alamat email yang muncul.
    - Hapus baris yang menyebut 'site.pro' (case-insensitive).
    - Rapikan whitespace berlebih.
    """
    if not text:
        return ""
    try:
        import re as _re
        # Hilangkan alamat email apapun
        cleaned = _re.sub(r"[\w\.\-+]+@[\w\.\-]+\.[A-Za-z]{2,}", "", text)
        # Hilangkan baris yang menyebut site.pro
        lines = []
        for ln in cleaned.splitlines():
            if 'site.pro' in ln.lower():
                continue
            lines.append(ln)
        cleaned = "\n".join(lines)
        # Hilangkan kata 'site.pro' sisa (jika ada inline)
        cleaned = _re.sub(r"(?i)site\.pro", "", cleaned)
        # Rapikan baris kosong berlebih
        cleaned = _re.sub(r"\n{3,}", "\n\n", cleaned).strip()
        return cleaned
    except Exception:
        return text


