def _prem_buy_keyboard(user_id):
    """Keyboard pilih paket: langganan harian + token, dalam satu menu."""
    rows = []
    for pk in PREMIUM_ORDER:
        label, price, days = PREMIUM_PACKAGES[pk]
        rows.append([InlineKeyboardButton(
            f"{label} · {_rp(price)}",
            callback_data=f"prem_buy_{pk}_{user_id}", style="primary")])
    for pk in TOKEN_ORDER:
        label, price, tokens, bonus = TOKEN_PACKAGES[pk]
        bonus_txt = f" +{bonus} bonus" if bonus else ""
        rows.append([InlineKeyboardButton(
            f"{tokens}{('+'+str(bonus)) if bonus else ''} Token · {_rp(price)}",
            callback_data=f"prem_buy_{pk}_{user_id}", style="success")])
    rows.append([InlineKeyboardButton("TUTUP", callback_data=f"prem_close_{user_id}", style="danger")])
    return InlineKeyboardMarkup(rows)


def _prem_price_body() -> str:
    """Daftar harga langganan + token untuk teks menu."""
    lines = [f"{em(E5,'📅')} <b>Langganan (unlimited selama aktif):</b>"]
    for pk in PREMIUM_ORDER:
        label, price, days = PREMIUM_PACKAGES[pk]
        normal = PREMIUM_DAILY_BASE * days
        hemat = normal - price
        tag = f"  <i>(hemat {_rp(hemat)})</i>" if hemat > 0 else ""
        lines.append(f"  {_DOT} <b>{label}</b>  —  {_rp(price)}{tag}")
    lines.append("")
    lines.append(f"{em(E5,'🎟')} <b>Token (bayar per pakai, tanpa masa aktif):</b>")
    for pk in TOKEN_ORDER:
        label, price, tokens, bonus = TOKEN_PACKAGES[pk]
        total_tok = tokens + bonus
        bonus_txt = f" (+{bonus} bonus)" if bonus else ""
        lines.append(f"  {_DOT} <b>{total_tok} Token</b>{bonus_txt}  —  {_rp(price)}")
    lines.append("")
    lines.append(f"<i>1x RESET OTP = {RESETOTP_TOKEN_COST} token. "
                 f"Token dikembalikan otomatis kalau proses gagal.</i>")
    lines.append(f"<i>User baru dapat {RESETOTP_TRIAL_LIMIT}x TRIAL gratis "
                 f"(hanya terpotong kalau berhasil).</i>")
    return "\n".join(lines)


async def buyprem_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/buyprem — beli akses RESET OTP (semua user, termasuk /adduser)."""
    if not update.effective_user:
        return
    user_id = update.effective_user.id

    if is_owner(user_id):
        await update.message.reply_text(
            _screen('PREMIUM RESET OTP',
                    f"{em(E1,'✅')} <b>Kamu Owner</b> — akses RESET OTP unlimited.",
                    'Home › Premium'),
            parse_mode=ParseMode.HTML)
        return

    p, tok = await asyncio.get_running_loop().run_in_executor(
        None, lambda: (get_premium(user_id), get_tokens(user_id)))
    status_box = ""
    if p and p["active"]:
        status_box = (
            f"{em(E1,'✅')} <b>Langganan kamu masih AKTIF</b>\n"
            f"  {_DOT} <b>Sisa</b>  {_human_left(p['left'])}\n"
            f"  {_DOT} <b>Expired</b>  {_fmt_wib(p['expired_at'])}\n\n"
            f"<i>Beli lagi = durasi ditambah di atas sisa waktu.</i>\n\n"
        )
    elif p and p["expired_at"]:
        status_box = (
            f"{em(E2,'❌')} <b>Langganan kamu sudah HABIS</b>\n"
            f"  {_DOT} <b>Berakhir</b>  {_fmt_wib(p['expired_at'])}\n\n"
        )
    else:
        status_box = f"{em(E2,'❌')} <b>Belum punya langganan RESET OTP</b>\n\n"

    if tok:
        status_box += f"{em(E5,'🎟')} <b>Saldo token:</b> {tok} (~{tok // RESETOTP_TOKEN_COST}x pakai)\n\n"

    await update.message.reply_text(
        _screen('PREMIUM RESET OTP', (
            f"{status_box}"
            f"{_prem_price_body()}\n\n"
            f"<i>Bayar via QRIS. Aktif/token masuk otomatis setelah pembayaran terdeteksi.</i>"
        ), 'Home › Premium'),
        parse_mode=ParseMode.HTML,
        reply_markup=_prem_buy_keyboard(user_id))


async def addprem_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/addprem <user_id> <hari> — kasih akses premium manual (owner/admin)."""
    if not update.effective_user:
        return
    user_id = update.effective_user.id
    if not (is_owner(user_id) or is_admin(user_id)):
        return

    args = context.args or []
    if len(args) < 2:
        await update.message.reply_text(
            _screen('ADD PREMIUM', (
                f"{em(E2,'❌')} <b>Format salah.</b>\n\n"
                f"<b>Cara pakai:</b>\n"
                f"  <code>/addprem &lt;user_id&gt; &lt;jumlah&gt; [hari|token]</code>\n\n"
                f"<b>Contoh:</b>\n"
                f"  <code>/addprem 6446678808 2</code>  → akses 2 hari\n"
                f"  <code>/addprem 6446678808 30 hari</code>  → akses 30 hari\n"
                f"  <code>/addprem 12345678 123 token</code>  → +123 token\n\n"
                f"<i>Default = hari kalau tipe tidak ditulis. Langganan yang "
                f"masih aktif akan diperpanjang; token ditambah ke saldo.</i>"
            ), 'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    try:
        target = int(str(args[0]).replace("@", "").strip())
    except Exception:
        await update.message.reply_text(
            _screen('ADD PREMIUM',
                    f"{em(E2,'❌')} <b>User ID harus angka.</b>\n"
                    f"Contoh: <code>/addprem 6446678808 2</code>",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    try:
        amount = int(args[1])
    except Exception:
        await update.message.reply_text(
            _screen('ADD PREMIUM',
                    f"{em(E2,'❌')} <b>Jumlah harus angka.</b>",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    # Tipe: 'token' atau 'hari' (default hari). Terima variasi penulisan.
    kind_arg = (args[2].strip().lower() if len(args) >= 3 and args[2] else "hari")
    is_token = kind_arg in ("token", "tokens", "tok", "t")

    # ── Mode TOKEN ──
    if is_token:
        if amount < 1 or amount > 100000:
            await update.message.reply_text(
                _screen('ADD PREMIUM',
                        f"{em(E2,'❌')} <b>Jumlah token harus 1–100000.</b>",
                        'Home › Owner › Premium'),
                parse_mode=ParseMode.HTML)
            return
        new_bal = add_tokens(target, amount, kind='grant',
                             ref=f"addprem:{user_id}:{int(time.time())}",
                             note=f"grant by admin {user_id}")
        await update.message.reply_text(
            _screen('ADD PREMIUM', (
                f"{em(E1,'✅')} <b>Token ditambahkan.</b>\n\n"
                f"  {_DOT} <b>User ID</b>  <code>{target}</code>\n"
                f"  {_DOT} <b>Token masuk</b>  <b>+{amount}</b>\n"
                f"  {_DOT} <b>Saldo sekarang</b>  <b>{new_bal}</b>\n"
                f"  {_DOT} <i>1x RESET OTP = {RESETOTP_TOKEN_COST} token</i>"
            ), 'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        try:
            await context.bot.send_message(
                chat_id=target,
                text=_screen('TOKEN DITAMBAHKAN', (
                    f"{em(E1,'✅')} <b>Token RESET OTP kamu bertambah!</b>\n\n"
                    f"  {_DOT} <b>Token masuk</b>  <b>+{amount}</b>\n"
                    f"  {_DOT} <b>Saldo sekarang</b>  <b>{new_bal}</b>\n\n"
                    f"<i>1x RESET OTP = {RESETOTP_TOKEN_COST} token. "
                    f"Ketik /fix &lt;nomor&gt; lalu pilih RESET OTP.</i>"
                ), 'Home › Premium'),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    # ── Mode HARI (default) ──
    days = amount
    if days < 1 or days > 3650:
        await update.message.reply_text(
            _screen('ADD PREMIUM',
                    f"{em(E2,'❌')} <b>Hari harus 1–3650.</b>",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    before, new_exp = await asyncio.get_running_loop().run_in_executor(
        None, lambda: (get_premium(target),
                       grant_premium(target, days, granted_by=user_id)))

    extra = ""
    if before and before["active"]:
        extra = (f"  {_DOT} <b>Sebelumnya</b>  {_fmt_wib(before['expired_at'])}\n"
                 f"  {_DOT} <i>Diperpanjang +{days} hari</i>\n")

    await update.message.reply_text(
        _screen('ADD PREMIUM', (
            f"{em(E1,'✅')} <b>Akses RESET OTP diberikan.</b>\n\n"
            f"  {_DOT} <b>User ID</b>  <code>{target}</code>\n"
            f"  {_DOT} <b>Durasi</b>  {days} hari\n"
            f"{extra}"
            f"  {_DOT} <b>Aktif s/d</b>  <b>{_fmt_wib(new_exp)}</b>"
        ), 'Home › Owner › Premium'),
        parse_mode=ParseMode.HTML)

    # Kabari user-nya (kalau pernah start bot)
    try:
        await context.bot.send_message(
            chat_id=target,
            text=_screen('PREMIUM AKTIF', (
                f"{em(E1,'✅')} <b>Akses RESET OTP kamu aktif!</b>\n\n"
                f"  {_DOT} <b>Durasi</b>  {days} hari\n"
                f"  {_DOT} <b>Aktif s/d</b>  <b>{_fmt_wib(new_exp)}</b>\n\n"
                f"<i>Ketik /fix &lt;nomor&gt; lalu pilih RESET OTP.</i>"
            ), 'Home › Premium'),
            parse_mode=ParseMode.HTML)
    except Exception:
        pass


async def delprem_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/delprem <user_id> — cabut akses premium (owner/admin)."""
    if not update.effective_user:
        return
    user_id = update.effective_user.id
    if not (is_owner(user_id) or is_admin(user_id)):
        return

    args = context.args or []
    if not args:
        await update.message.reply_text(
            _screen('DEL PREMIUM',
                    f"{em(E2,'❌')} <b>Format:</b> <code>/delprem &lt;user_id&gt;</code>\n"
                    f"Contoh: <code>/delprem 6446678808</code>",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    try:
        target = int(str(args[0]).replace("@", "").strip())
    except Exception:
        await update.message.reply_text(
            _screen('DEL PREMIUM',
                    f"{em(E2,'❌')} <b>User ID harus angka.</b>",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    p = await asyncio.get_running_loop().run_in_executor(
        None, lambda: get_premium(target))
    if not p:
        await update.message.reply_text(
            _screen('DEL PREMIUM',
                    f"{em(E2,'❌')} User <code>{target}</code> tidak punya data premium.",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
        return

    try:
        _premium_db.execute("DELETE FROM premium_access WHERE user_id = ?", (target,))
        _premium_db.commit()
    except Exception as e:
        await update.message.reply_text(
            _screen('DEL PREMIUM',
                    f"{em(E2,'❌')} Gagal: {html.escape(str(e))}",
                    'Home › Owner › Premium'),
            parse_mode=ParseMode.HTML)
