def _prem_list_rows(limit: int = 50, active_only: bool = True):
    """Ambil daftar premium_access untuk owner console."""
    try:
        if active_only:
            _premium_db.execute(
                "SELECT user_id, expired_at, package, days, total_paid, buy_count "
                "FROM premium_access WHERE expired_at > ? "
                "ORDER BY expired_at DESC LIMIT ?", (_iso(_now_utc()), limit))
        else:
            _premium_db.execute(
                "SELECT user_id, expired_at, package, days, total_paid, buy_count "
                "FROM premium_access ORDER BY expired_at DESC LIMIT ?", (limit,))
        return _premium_db.fetchall() or []
    except Exception:
        return []


def _prem_revenue():
    """Total revenue dari invoice yang sudah paid + jumlah transaksi.

    Pakai `total` (harga + fee, yang benar-benar dibayar user), bukan `amount`.
    """
    try:
        _premium_db.execute("SELECT COALESCE(SUM(total),0), COUNT(*) "
                            "FROM premium_invoices WHERE status = 'paid'")
        row = _premium_db.fetchone()
        return (int(row[0] or 0), int(row[1] or 0))
    except Exception:
        return (0, 0)


def _prem_pending_count():
    try:
        _premium_db.execute("SELECT COUNT(*) FROM premium_invoices WHERE status = 'pending'")
        return int((_premium_db.fetchone() or [0])[0] or 0)
    except Exception:
        return 0


async def listprem_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/listprem — daftar user premium aktif + ringkasan revenue (owner/admin)."""
    if not update.effective_user:
        return
    user_id = update.effective_user.id
    if not (is_owner(user_id) or is_admin(user_id)):
        return

    rows = _prem_list_rows(active_only=True)
    total_rev, total_tx = _prem_revenue()
    pending = _prem_pending_count()

    if not rows:
        body = f"{em(E2,'📭')} <i>Belum ada user premium aktif.</i>\n\n"
    else:
        lines = []
        now = _now_utc()
        for uid, exp_s, pkg, days, paid, cnt in rows:
            exp = _parse_iso(exp_s)
            left = _human_left(exp - now) if exp else "-"
            lines.append(
                f"  {em(E1,'✅')} <code>{uid}</code> — sisa <b>{left}</b> "
                f"· {_rp(paid)} ({cnt}x)")
        body = (f"{em(CE_PROFILE,'👤')} <b>Premium Aktif ({len(rows)}):</b>\n"
                f"<blockquote expandable>" + "\n".join(lines) + "</blockquote>\n\n")

    await update.message.reply_text(
        _screen('LIST PREMIUM', (
            f"{body}"
            f"{em(E5,'💰')} <b>Ringkasan:</b>\n"
            f"  {_DOT} <b>Revenue</b>  {_rp(total_rev)}\n"
            f"  {_DOT} <b>Transaksi lunas</b>  {total_tx}x\n"
            f"  {_DOT} <b>Invoice pending</b>  {pending}"
        ), 'Home › Owner › Premium'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("BUKA MENU PREMIUM", callback_data="owner_prem_menu", style="primary")
        ]]))


