def _parse_fix_numbers(text):
    """Parse nomor dari input user. Support: comma-separated, newline, spasi."""
    if not text:
        return []
    # Split by comma, newline, or space
    parts = re.split(r'[,\n\s]+', text.strip())
    numbers = []
    for p in parts:
        p = p.strip().replace("+", "").replace("-", "")
        if p and p.isdigit() and len(p) >= 8:
            numbers.append(p)
    return numbers


# ── /limitin: kejar kode OTP via spam request v.whatsapp.net ──────────────────
_LIMITIN_METHOD_LABEL = {
    "wa_old": "Perangkat (wa_old)",
    "sms": "Sms",
    "voice": "Voice",
}


def _limitin_screen(state: dict) -> str:
    """Layar /limitin — gaya FIX RESET OTP, custom emoji + blockquote."""
    import html as _lh
    method = state.get("method", "wa_old")
    lines = [
        f"⌁ <b>{_lh.escape(state.get('stage', '...'))}</b>\n",
    ]
    d = state.get("last", {})
    if d:
        lines.append(
            f"  {em(CE_NOMOR,'📞')} Nomor: <code>+{_lh.escape(state.get('nomor',''))}</code>\n"
            f"  {em(CE_SETTINGS,'⚙️')} Method: <b>{_lh.escape(method)}</b>\n"
        )
        if d.get("ok"):
            rows = []
            if state.get("retry_fmt"):
                rows.append(f"  {em(CE_WAKTU,'⏱')} Retry: <b>{_lh.escape(state['retry_fmt'])}</b>")
            for key, eid in (("sms_fmt", CE_NOMOR), ("voice_fmt", CE_WHATSAPP)):
                if state.get(key):
                    label = "Sms" if key == "sms_fmt" else "Voice"
                    rows.append(f"  {em(eid, '📞' if key == 'sms_fmt' else '❤️')} {label}: <b>{_lh.escape(state[key])}</b>")
            if rows:
                lines.append("\n".join(rows) + "\n")
        else:
            lines.append(
                f"  {em(E2,'❌')} <i>{_lh.escape(str(d.get('error') or 'gak bisa ke-detect'))[:90]}</i>\n"
            )
    # counter
    cnt = state.get("count", 0)
    sent_cnt = state.get("sent_count", 0)
    verdict = state.get("verdict")
    v_lines = ""
    if verdict == "limit":
        # tujuan /limitin TERCAPAI: nomor udah kena limit
        v_lines = (
            f"\n<blockquote>{em(E1,'✅')} <b>NOMOR UDAH KENA LIMIT — request kode dibekukan.</b></blockquote>\n"
        )
    elif verdict == "timeout":
        v_lines = f"\n<blockquote>{em(CE_WAKTU,'⏱')} <b>Timeout 8 jam — berhenti (belum kena limit).</b></blockquote>\n"
    elif verdict == "blocked":
        v_lines = f"\n<blockquote>{em(E2,'🚫')} <b>Nomor blocked — berhenti.</b></blockquote>\n"
    body = (
        f"{''.join(lines)}\n"
        f"  {em(CE_LOADING,'🟠')} Percobaan: <b>{cnt}</b> · "
        f"Request diterima: <b>{sent_cnt}</b>\n"
        f"{v_lines}"
    )
    return _screen('LIMITIN WHATSAPP', body)


async def _limitin_run(message, nomor: str, method: str, user_id: int, context=None):
    """Loop /limitin: spam request kode biar nomor CEPAT KENA LIMIT.

    Bukan fitur kirim kode — tujuannya ngehabisin jatah request nomor sampai
    WhatsApp masang limit (too_many / wait besar). Setiap request yang
    diterima (status sent) = 1 poin limit terpakai → langsung spam lagi
    sesuai retry_after. Berhenti kalau:
      - kena limit beneran (reason=too_many + wait >= 8 jam) → BERHASIL
      - nomor blocked
      - 8 jam hard cap
      - user pencet STOP
    """
    import html as _lh
    state = {"stage": "Mendeteksi...", "nomor": nomor, "method": method,
             "last": None, "count": 0, "retry_fmt": None,
             "sms_fmt": None, "voice_fmt": None, "verdict": None,
             "sent_count": 0}
    deadline = time.time() + 8 * 3600  # hard cap 8 jam
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("STOP", callback_data=f"limitin_stop_{user_id}", style="danger")],
    ])

    async def _edit():
        try:
            await message.edit_text(_limitin_screen(state), parse_mode=ParseMode.HTML,
                                    reply_markup=kb if not state.get("verdict") else None)
        except Exception:
            pass

    while time.time() < deadline:
        state["stage"] = f"Spam request ({method})..."
        await _edit()
        d = await _detect_otp_wait(nomor, method)
        state["count"] += 1
        state["last"] = d
        state["sms_fmt"] = d.get("sms_wait_fmt") or "-"
        state["voice_fmt"] = d.get("voice_wait_fmt") or "-"
        if not d.get("ok"):
            reason = (d.get("data") or {}).get("reason") or "blocked"
            if reason == "blocked":
                state["stage"] = "Berhenti — nomor blocked"
                state["verdict"] = "blocked"
                await _edit()
                return
            # error lain (network dsb) — tunggu 30 dtk coba lagi
            state["stage"] = f"Error: {str(d.get('error'))[:60]} — coba lagi"
            await _edit()
            await asyncio.sleep(30)
            continue

        data = d.get("data") or {}
        # API balikin 'wa_status', node balikin 'status' — cek dua-duanya.
        status = str(data.get("wa_status") or data.get("status") or "")
        reason = str(data.get("reason") or "")
        if status == "sent":
            # request DITERIMA server (bukan kode dikirim ke user!) →
            # jatah limit nomor kepotong 1 → langsung gas spam lagi.
            state["sent_count"] = int(state.get("sent_count", 0)) + 1
            state["stage"] = "Request diterima — lanjut spam..."

        # ── Kena limit di method aktif? ──
        # Cooldown method aktif ({method}_wait) adalah sumber kebenaran —
        # retry_after bisa nilainya kecil (diambil dari method lain) walau
        # method kita udah kekunci besar. Tapi reason=too_many udah cukup
        # bukti limit kepasang (server nyatain tolak), walau cooldown
        # method = -1 (dinonaktifkan) atau 0.
        cd = data.get("cooldown") or {}
        method_wait = (cd.get(method) or {}).get("seconds")
        if method_wait is None:
            method_wait = data.get(f"{method}_wait")
        try:
            method_wait = int(method_wait)
        except (TypeError, ValueError):
            method_wait = 0
        # fallback: retry_after kalau cooldown method gak ada / <= 0
        raw_wait = method_wait
        if raw_wait <= 0:
            raw_wait = d.get("retry_after")
            try:
                raw_wait = int(raw_wait)
            except (TypeError, ValueError):
                raw_wait = 0
        method_limited = (
            reason == "too_many"
            or method_wait >= 28800
            or (raw_wait >= 28800)
        )
        if method_limited:
            # ── Method utama udah limit → pakai API sms 1x + voice 1x ──
            # biar method lain ikut kepotong jatahnya, baru selesai.
            state["stage"] = f"Method {method} udah limit — pakai Sms & Voice 1x..."
            state["retry_fmt"] = _fmt_otp_wait(method_wait if method_wait >= 28800 else raw_wait)
            await _edit()
            for extra_method in ("sms", "voice"):
                if extra_method == method:
                    continue
                try:
                    ed = await _detect_otp_wait(nomor, extra_method)
                    state["count"] += 1
                    if ed.get("ok"):
                        state["sms_fmt"] = ed.get("sms_wait_fmt") or state.get("sms_fmt")
                        state["voice_fmt"] = ed.get("voice_wait_fmt") or state.get("voice_fmt")
                        if str((ed.get("data") or {}).get("wa_status") or "") == "sent":
                            state["sent_count"] = int(state.get("sent_count", 0)) + 1
                except Exception:
                    pass
            # selesai — nomor beneran udah kena limit
            state["stage"] = "Selesai — nomor udah kena limit."
            state["verdict"] = "limit"
            await _edit()
            return

        # masih boleh request — tunggu sesuai cooldown (min 60, max 3600)
        wait = raw_wait if raw_wait > 0 else 60
        wait = max(60, min(wait, 3600))
        state["stage"] = f"Menunggu {wait} dtk sebelum spam lagi..."
        state["retry_fmt"] = _fmt_otp_wait(raw_wait if raw_wait else wait)
        await _edit()
        # sleep terpotong-ganti: cek tiap 5 dtk biar responsif (max = wait)
        target = time.time() + wait
        while time.time() < target:
            await asyncio.sleep(5)
            stopped = False
            try:
                stopped = bool(context.user_data.get(f"limitin_stop_{user_id}")) if context else False
            except Exception:
                stopped = False
            if stopped:
                try:
                    if context:
                        context.user_data.pop(f"limitin_stop_{user_id}", None)
                except Exception:
                    pass
                state["stage"] = "Dihentikan user."
                await _edit()
                return

    state["stage"] = "Timeout 8 jam — berhenti."
    state["verdict"] = "timeout"
    state["limit_fmt"] = "8 jam"
    await _edit()


async def limitin_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/limitin <nomor> — spam request kode biar nomor CEPAT KENA LIMIT.

    Bukan kirim kode — tujuannya ngabisin jatah request nomor sampai
    WhatsApp masang limit (too_many). Pilih method: wa_old/sms/voice.
    """
    if not update.effective_user or not update.message:
        return
    user_id = update.effective_user.id
    raw = " ".join(context.args or []).strip()
    if not raw:
        await update.message.reply_text(
            _screen('LIMITIN WHATSAPP', (
                f"{em(CE_WHATSAPP,'❤️')} <b>Limitin — spam nomor sampai kena limit</b>\n\n"
                f"<b>Cara pakai:</b>\n"
                f"  <code>/limitin +6285757411154</code>\n\n"
                f"Bot spam request kode sesuai retry_after sampai nomor\n"
                f"kena limit WhatsApp (maks <b>8 jam</b>, wa_old/sms/voice).\n"
                f"<i>Berhenti otomatis pas limit kepasang.</i>"
            )),
            parse_mode=ParseMode.HTML)
        return
    digits = re.sub(r"\D", "", raw.split()[0])
    if len(digits) < 8:
        await update.message.reply_text(
            _screen('LIMITIN WHATSAPP', f"{em(E2,'❌')} Nomor tidak valid."),
            parse_mode=ParseMode.HTML)
        return

    msg = await update.message.reply_text(
        _screen('LIMITIN WHATSAPP', f"{em(CE_LOADING,'🟠')} <b>Mendeteksi nomor +{digits}...</b>"),
        parse_mode=ParseMode.HTML)

    d = await _detect_otp_wait(digits, "wa_old")
    state = {"stage": "Pilih method", "nomor": digits, "method": "wa_old",
             "last": d, "count": 1, "retry_fmt": d.get("retry_after_fmt"),
             "sms_fmt": d.get("sms_wait_fmt"), "voice_fmt": d.get("voice_wait_fmt"),
             "verdict": None}
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("Perangkat (wa_old)", callback_data=f"limitin_run_{user_id}_wa_old", style="success")],
        [
            InlineKeyboardButton("Sms", callback_data=f"limitin_run_{user_id}_sms", style="primary"),
            InlineKeyboardButton("Voice", callback_data=f"limitin_run_{user_id}_voice", style="primary"),
        ],
        [InlineKeyboardButton("Batal", callback_data=f"limitin_cancel_{user_id}", style="danger")],
    ])
    try:
        rec = (d.get("data") or {}).get("recommended_method") or []
        rec_txt = ", ".join(str(x) for x in rec) if rec else "wa_old"
    except Exception:
        rec_txt = "wa_old"
    if d.get("ok"):
        detail = (
            f"  {em(CE_NOMOR,'📞')} Nomor: <code>+{digits}</code>\n"
            f"  {em(CE_WAKTU,'⏱')} Retry: <b>{d.get('retry_after_fmt') or '-'}</b>\n"
            f"  {em(CE_NOMOR,'📞')} Sms: <b>{d.get('sms_wait_fmt') or '-'}</b>\n"
            f"  {em(CE_WHATSAPP,'❤️')} Voice: <b>{d.get('voice_wait_fmt') or '-'}</b>\n\n"
            f"  {em(CE_SETTINGS,'⚙️')} Rekomendasi server: <b>{html.escape(rec_txt)}</b>\n\n"
            f"Pilih method buat mulai <b>limitin</b>:"
        )
    else:
        reason = (d.get("data") or {}).get("reason") or "blocked"
        detail = (
            f"  {em(CE_NOMOR,'📞')} Nomor: <code>+{digits}</code>\n"
            f"  {em(E2,'❌')} <i>Gak bisa ke-detect ({html.escape(str(reason))})."
            f" Tetap bisa coba paksain method.</i>\n\n"
            f"Pilih method buat mulai <b>limitin</b>:"
        )
    try:
        await msg.edit_text(
            _screen('LIMITIN WHATSAPP', f"⌁ <b>Pilih method</b>\n\n{detail}"),
            parse_mode=ParseMode.HTML, reply_markup=kb)
    except Exception:
        pass
    context.user_data[f"limitin_nomor_{user_id}"] = digits


async def fix_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/fix <nomor> — kirim permintaan unban WhatsApp ke support.

    /fix terbuka untuk SEMUA user (tidak butuh /adduser).
    """
    if not update.effective_user:
        return
    user_id = update.effective_user.id

    if CAPTCHA_SOLVER != "browser" and not CAPTCHA_API_KEY:
        await update.message.reply_text(
            _screen('FIX WHATSAPP',
                    f"{em(E2,'❌')} <b>Konfigurasi captcha belum siap.</b>"),
            parse_mode=ParseMode.HTML,
        )
        return

    raw = " ".join(context.args) if context.args else ""

    # Opsi --lang xx (pilih template bahasa tertentu yang sudah di-/set)
    import re as _re_fix
    sel_lang = None
    m = _re_fix.search(r"--lang\s+([a-zA-Z]{2})\b", raw)
    if m:
        cand = m.group(1).lower()
        if cand in FIX_TEMPLATE_LANGS:
            sel_lang = cand
        raw = (raw[:m.start()] + raw[m.end():]).strip()
    context.user_data['fix_lang'] = sel_lang

    numbers = _parse_fix_numbers(raw)

    # Max 5 nomor per perintah (1 akun bisa kirim sampai 5x)
    is_owner_user = (user_id == USER_ID)
    max_per_cmd = 50 if is_owner_user else 5
    if len(numbers) > max_per_cmd:
        await update.message.reply_text(
            _screen('FIX WHATSAPP',
                    f"{em(E2,'❌')} <b>Maksimal {max_per_cmd} nomor per perintah.</b>\n"
                    f"Kamu memasukkan {len(numbers)} nomor."),
            parse_mode=ParseMode.HTML,
        )
        return

    if not numbers:
        await update.message.reply_text(
            _screen('FIX WHATSAPP', (
                f"{em(CE_WHATSAPP,'❤️')} <b>Fix Merah & Reset OTP WhatsApp</b>\n\n"
                f"<b>Cara pakai:</b>\n"
                f"  <code>/fix 6285757411154</code>\n"
                f"  <code>/fix 6281234567890, 6289876543210</code>\n\n"
                f"Bisa beberapa nomor sekaligus (maks <b>{max_per_cmd}</b>).\n"
                f"Satu perintah = satu permintaan, kirim ke setiap nomor."
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    num_list = "\n".join(
        f"  {em(CE_NOMOR,'📞')} <code>+{n}</code>" for n in numbers
    )

    fix_data_key = f"fix_numbers_{user_id}"
    context.user_data[fix_data_key] = numbers
    _capture_fix_origin(context, update.effective_chat)

    # Cek akses + status line dalam 1 executor — keduanya pakai blocking HTTP.
    def _check_access_and_status():
        status = premium_status_line(user_id)
        if has_premium(user_id) or get_tokens(user_id) >= RESETOTP_TOKEN_COST:
            label = "RESET OTP"
        elif not _has_paid_history(user_id) and trial_left(user_id) > 0:
            label = "RESET OTP (TRIAL)"
        else:
            label = "RESET OTP (BAYAR)"
        return status, label

    _status_line, _resetotp_label = await asyncio.get_running_loop().run_in_executor(
        None, _check_access_and_status)

    text = _screen('FIX WHATSAPP', (
        f"{em(CE_WHATSAPP,'❤️')} <b>Nomor yang akan diproses ({len(numbers)}):</b>\n"
        f"{num_list}\n\n"
        f"{_status_line}\n\n"
        f"Proses: kirim permintaan ke WhatsApp support, lalu cek balasan.\n"
        f"<i>SERVER 1/2 gratis · RESET OTP butuh akses premium.</i>"
    ))

    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("SERVER 1",
                callback_data=f"fix_srv1_{user_id}",
                style="primary",
            ),
            InlineKeyboardButton("SERVER 2",
                callback_data=f"fix_srv2_{user_id}",
                style="primary",
            ),
        ],
        [
            InlineKeyboardButton(
                _resetotp_label,
                callback_data=f"fix_resetotp_{user_id}",
                style="success",
            ),
        ],
        [
            InlineKeyboardButton("BATAL",
                callback_data=f"fix_cancel_{user_id}",
                style="danger",
            ),
        ],
    ])
    await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=keyboard)


async def _process_fix_api_background(numbers, user_id, message, context):
    """Background worker /fix SERVER 3: jalur AtomicMail API.

    1 akun AtomicMail dibuat (browser cuma untuk mint captcha sign-up),
    token disimpan ke DB, lalu kirim ke tiap nomor + cek balasan. Kalau
    timeout, buat alias baru (sampai 10) & kirim ulang. Alias/kirim coba
    tanpa captcha dulu (lazy), jadi browser minim dipakai.
    """
    import functools, html as _html
    try:
        from atomicmail_api import run_atomic_fix_pipeline_api, DEFAULT_MAX_ALIAS_PER_ACCOUNT
        from atomic_token_minter import TokenMinter
    except Exception as e:
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · SERVER 3 (API)',
                        f"{em(E2,'❌')} Modul API tidak tersedia: {_html.escape(str(e))}"),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    main_loop = asyncio.get_running_loop()
    state = {'stage': 'starting', 'msg': '', 'sent': 0, 'replied': 0,
             'alias': 0, 'account': ''}

    def _render():
        return _screen('FIX WHATSAPP · SERVER 3 (API)', (
            f"{em(CE_LOADING,'🟠')} <b>{state['stage']}</b>\n\n"
            f"  {em(CE_AKUN,'👤')} Akun: <b>{_html.escape(state['account'] or '-')}</b>\n"
            f"  {em(CE_WHATSAPP,'❤️')} Balasan WA: <b>{state['replied']}/{len(numbers)}</b>\n"
            f"  {em(E1,'📤')} Terkirim: <b>{state['sent']}</b>\n"
            f"  {em(E6,'🚀')} Alias dibuat: <b>{state['alias']}</b>"
            + (f"\n\n<i>{_html.escape(state['msg'])}</i>" if state['msg'] else "")
        ))

    async def _safe_edit():
        try:
            await message.edit_text(_render(), parse_mode=ParseMode.HTML)
        except Exception:
            pass

    def _push():
        try:
            main_loop.call_soon_threadsafe(lambda: asyncio.create_task(_safe_edit()))
        except Exception:
            pass

    def _cb(stage, data):
        state['stage'] = stage
        if stage == 'signup_start':
            state['msg'] = 'Daftar akun AtomicMail baru...'
        elif stage == 'signup_ok':
            state['account'] = data.get('address', '')
            state['msg'] = f"Akun siap: {data.get('address','')}"
        elif stage == 'send_start':
            state['msg'] = f"Kirim dari {data.get('from','?')} (coba {data.get('try','?')})"
        elif stage == 'send_ok':
            state['sent'] += 1
            state['msg'] = f"Terkirim id={data.get('resp',{}).get('id','?')}"
        elif stage == 'send_err':
            state['msg'] = f"❌ Send: {str(data.get('err',''))[:120]}"
        elif stage == 'wait_reply':
            state['msg'] = "Menunggu balasan support@support.whatsapp.com..."
        elif stage == 'reply':
            state['replied'] += 1
            state['msg'] = f"✅ Balasan diterima!"
        elif stage == 'alias_new':
            state['alias'] += 1
            state['msg'] = f"Alias baru: {data.get('alias','?')} ({data.get('used','?')}/{data.get('limit','?')})"
        elif stage == 'alias_limit':
            state['msg'] = f"Alias habis ({data.get('used','?')}/{data.get('limit','?')})."
        elif stage == 'alias_err':
            state['msg'] = f"❌ Alias: {str(data.get('err',''))[:120]}"
        _push()

    def _save_account(info):
        try:
            cur.execute(
                "INSERT INTO atomicmail_accounts "
                "(user_id, address, username, atomic_user_id, access_token, session_id, status) "
                "VALUES (?, ?, ?, ?, ?, ?, 'active')",
                (user_id, info.get('address'), info.get('username'),
                 info.get('user_id'), info.get('access_token'), info.get('session_id')),
            )
            conn.commit()
        except Exception as _e:
            print(f"[ATOMIC] save account err: {_e}")

    await _safe_edit()
    phones = [str(n) for n in numbers]

    # 1) Coba pakai akun/token existing dulu dari DB (hemat browser).
    existing_token = None
    existing_addr = None
    try:
        cur.execute(
            "SELECT access_token, address FROM atomicmail_accounts "
            "WHERE user_id=? AND status='active' AND access_token IS NOT NULL "
            "ORDER BY id DESC LIMIT 1",
            (user_id,),
        )
        row = cur.fetchone()
        if row:
            existing_token, existing_addr = row[0], row[1]
    except Exception as _e:
        print(f"[ATOMIC] load existing token err: {_e}")

    # 2) Jalankan pipeline. Kalau ada token existing, coba API-only dulu.
    minter = None
    try:
        if existing_token:
            state['msg'] = f"Pakai akun existing: {existing_addr}"
            _push()
            try:
                res = await main_loop.run_in_executor(
                    None,
                    functools.partial(
                        run_atomic_fix_pipeline_api,
                        phones,
                        reply_timeout=240,
                        max_alias_per_account=DEFAULT_MAX_ALIAS_PER_ACCOUNT,
                        progress_cb=_cb,
                        existing_access_token=existing_token,
                    ),
                )
            except Exception as e:
                print(f"[ATOMIC] existing token gagal, fallback signup browser: {e}")
                existing_token = None

        if not existing_token:
            minter = TokenMinter(headless=False)
            res = await main_loop.run_in_executor(
                None,
                functools.partial(
                    run_atomic_fix_pipeline_api,
                    phones,
                    reply_timeout=240,
                    max_alias_per_account=DEFAULT_MAX_ALIAS_PER_ACCOUNT,
                    progress_cb=_cb,
                    minter=minter,
                    on_account_saved=_save_account,
                ),
            )
    except Exception as e:
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · SERVER 3 (API)',
                        f"{em(E2,'❌')} Pipeline error: {_html.escape(str(e))[:300]}"),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return
    finally:
        if minter is not None:
            try:
                await main_loop.run_in_executor(None, minter.close)
            except Exception:
                pass

    ok = res.get('success_count', 0)
    fail = res.get('fail_count', 0)
    try:
        await message.edit_text(
            _screen('FIX WHATSAPP · SERVER 3 (API) — SELESAI', (
                f"{em(CE_AKUN,'👤')} <b>Akun:</b> {_html.escape(res.get('account',{}).get('address','-'))}\n"
                f"  {em(CE_WHATSAPP,'❤️')} Berhasil: <b>{ok}</b>\n"
                f"  {em(E2,'❌')} Gagal: <b>{fail}</b>\n"
                f"  {em(E6,'🚀')} Alias dipakai: <b>{res.get('aliases_used',0)}</b>\n\n"
                f"<i>Token akun disimpan. Pengiriman berikutnya bisa pakai token tanpa browser lagi.</i>"
            )),
            parse_mode=ParseMode.HTML)
    except Exception:
        pass


async def _process_fix_resetotp_background(numbers, user_id, message, context,
                                            mode: str = "hard", limit_hours: int = 24):
    """Background worker /fix RESET OTP: email banding + Form V1/V2/V3.

    mode: easy | hard — Form V3 selalu 2 kirim (Gmail SMTP + logs/foto).
    limit_hours: dipakai di teks banding ({jam}).
    """
    import functools, html as _html
    try:
        from faq_server import run_reset_otp_pipeline
    except Exception as e:
        # Modul tidak ada → token belum dipotong di titik ini, tapi jaga-jaga.
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · RESET OTP',
                        f"{em(E2,'❌')} Modul RESET OTP tidak tersedia: {_html.escape(str(e))}"),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    main_loop = asyncio.get_running_loop()
    mode = (mode or "hard").lower()
    limit_hours = int(limit_hours or 24)

    # ── Tentukan cara akses: langganan / token / trial ──
    # - premium: langganan/owner → gratis, tidak potong apa pun.
    # - token  : potong RESETOTP_TOKEN_COST di awal; refund otomatis kalau gagal.
    # - trial  : user gratis, pakai jatah trial. Jatah HANYA terpotong kalau
    #            proses berhasil (gagal = tidak mengurangi trial).
    # SEMUA cek akses jalan di executor — _web_read/_web_write pakai requests
    # (synchronous) yang bisa block event loop kalau D1 lambat.
    def _determine_access_and_charge():
        """Blocking: cek akses + potong token/trial. Dipanggil via executor."""
        _access = resetotp_access_mode(user_id)
        _token_charged = False
        _trial_reserved = False
        _token_ref = f"resetotp:{user_id}:{int(time.time()*1000)}"

        if _access == "token":
            if spend_tokens(user_id, RESETOTP_TOKEN_COST, ref=_token_ref,
                            note=f"RESET OTP {len(numbers)} nomor"):
                _token_charged = True
            else:
                _access = resetotp_access_mode(user_id)

        if _access == "trial":
            if try_reserve_trial(user_id):
                _trial_reserved = True
            else:
                _access = resetotp_access_mode(user_id)
                if _access == "token":
                    if spend_tokens(user_id, RESETOTP_TOKEN_COST, ref=_token_ref,
                                    note=f"RESET OTP {len(numbers)} nomor"):
                        _token_charged = True
                    else:
                        _access = "none"
                elif _access == "trial":
                    _access = "none"

        return _access, _token_charged, _trial_reserved, _token_ref

    access, token_charged, trial_reserved, token_ref = await main_loop.run_in_executor(
        None, _determine_access_and_charge
    )

    if access == "none":
        _tl_none, _tok_none = await main_loop.run_in_executor(
            None, lambda: (trial_left(user_id), get_tokens(user_id)))
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · RESET OTP',
                        f"{em(E2,'❌')} <b>Akses habis.</b>\n\n"
                        f"  {_DOT} Trial gratis: <b>{_tl_none}/{RESETOTP_TRIAL_LIMIT}</b> tersisa\n"
                        f"  {_DOT} Token: <b>{_tok_none}</b> "
                        f"(butuh {RESETOTP_TOKEN_COST})\n\n"
                        f"<i>Beli langganan/token dulu lewat /buyprem.</i>"),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return

    def _refund_tokens_if_charged(reason: str):
        """Kembalikan token yang dipotong (idempoten via token_ref)."""
        if token_charged:
            try:
                refund_tokens(user_id, RESETOTP_TOKEN_COST, ref=token_ref,
                              note=f"refund: {reason}")
            except Exception as e:
                logging.warning("[TOKEN] refund resetotp gagal: %s", e)

    def _refund_charge_if_failed(reason: str):
        """Balikin token DAN trial yang tadi dipesan (proses gagal total)."""
        _refund_tokens_if_charged(reason)
        nonlocal trial_reserved
        if trial_reserved:
            try:
                refund_trial(user_id)
            except Exception as e:
                logging.warning("[TRIAL] refund resetotp gagal: %s", e)
            trial_reserved = False

    state = {'stage': 'Memulai...', 'msg': '', 'sent': 0, 'replied': 0,
             'nomor': '', 'ua': '', 'carrier': '', 'email_sent': 0,
             'faq1_ok': 0, 'faq2_ok': 0, 'faq3_ok': 0, 'faq4_ok': 0, 'waiting': False,
             'mode': mode, 'limit': limit_hours,
             'banding_n': 0, 'faq1_n': 0, 'faq2_n': 0, 'faq3_n': 0, 'faq4_n': 0,
             'sms_map': {}}
    log_username, log_fullname = await _resolve_tg_profile(user_id)
    banding_map = {str(n): _new_fix_banding_id() for n in numbers}
    logged_events = set()
    chat_origin = "-"
    try:
        chat_origin = (context.user_data.get("fix_chat_origin") if context else None) or "-"
    except Exception:
        chat_origin = "-"

    # ── Auto-detect limit SMS tiap nomor (jalan apapun pilihan limit) ──
    # Hasil detect tombol [Detect] dipakai kalau ada; sisanya di-detect sekarang.
    _detect_cache = {}
    try:
        _detect_cache = context.user_data.get(f'resetotp_detect_{user_id}') or {}
    except Exception:
        _detect_cache = {}
    _detect_map = {}
    for n in numbers:
        key = str(n)
        d = _detect_cache.get(key)
        if not d:
            d = await _detect_otp_wait(key)
        if d.get('ok'):
            _detect_map[key] = d
    # Simpan sms_wait per nomor (awal) — dipakai render + monitor round-robin.
    for _key, _d in _detect_map.items():
        state['sms_map'][_key] = {
            'awal': _d.get('sms_wait'), 'awal_fmt': _d.get('sms_wait_fmt'),
            'voice_fmt': _d.get('voice_wait_fmt'),
            'akhir': None, 'akhir_fmt': None, 'jebol': None, 'note': None,
            'last_val': _d.get('sms_wait'), 'last_change': time.time(),
            'last_fail': None,
        }
    del _detect_cache

    def _schedule_fix_log(phone, status_key):
        phone_key = str(phone or "").strip()
        if not phone_key:
            return
        event_key = (phone_key, status_key)
        if event_key in logged_events:
            return
        logged_events.add(event_key)
        bid = banding_map.get(phone_key) or _new_fix_banding_id()
        try:
            main_loop.call_soon_threadsafe(
                lambda p=phone_key, s=status_key, b=bid: asyncio.create_task(
                    notify_fix_group_log(
                        user_id=user_id,
                        phone=p,
                        status=s,
                        banding_id=b,
                        server="resetotp",
                        source="bot",
                        username=log_username,
                        full_name=log_fullname,
                        chat_origin=chat_origin,
                        limit_hours=limit_hours,
                    )
                )
            )
        except Exception:
            pass

    def _render():
        notice = (
            f"⌁ Jika belum ada balasan itu <b>normal</b>.\n"
            f"   Tunggu 2-5 menit, lalu cek WhatsApp nomornya:\n"
            f"   sudah kejebol apa belum.\n"
        ) if state.get('waiting') else ""

        def _dots(ok, total):
            n = max(total, 1)
            filled = min(ok, n)
            return "●" * filled + "○" * (n - filled)

        bd_n = state['banding_n'] or 5
        progress = (
            f"  Banding  {_dots(state['email_sent'], bd_n)}  <b>{state['email_sent']}</b>\n"
            f"  Form V1  {_dots(state['faq1_ok'], state['faq1_n'] or 3)}  <b>{state['faq1_ok']}</b>\n"
            f"  Form V2  {_dots(state['faq2_ok'], state['faq2_n'] or 8)}  <b>{state['faq2_ok']}</b>\n"
            f"  Form V3  {_dots(state['faq3_ok'], state['faq3_n'] or 2)}  <b>{state['faq3_ok']}</b>\n"
            f"  Form V4  {_dots(state['faq4_ok'], state['faq4_n'] or 1)}  <b>{state['faq4_ok']}</b>\n"
            f"  ─────────────────\n"
            f"  Balasan WA  <b>{state['replied']}/{len(numbers)}</b>"
        )

        sms_map = state.get('sms_map') or {}
        sms_lines = ""

        def _wait_short(fmt):
            # buat baris multi-nomor: buang "(X detik)" biar muat
            return re.sub(r"\s*\(\d+ detik\)", "", fmt or "-")

        def _fmt_hms(seconds):
            # detik → "HH:MM:SS" (biar cocok bukti "Try again in HH:MM:SS")
            try:
                s = int(seconds)
                if s <= 0:
                    return ""
                h, rem = divmod(s, 3600)
                m, sc = divmod(rem, 60)
                return f"{h:02d}:{m:02d}:{sc:02d}"
            except Exception:
                return ""

        multi = len(numbers) > 1
        if sms_map and not multi:
            _num, _s = next(iter(sms_map.items()))
            if _s.get('awal_fmt'):
                _hms = _fmt_hms(_s.get('awal'))
                _suf = f"  <code>[{_hms}]</code>" if _hms else ""
                sms_lines += f"  Sms Awal : <b>{_html.escape(_s['awal_fmt'])}</b>{_suf}\n"
            if _s.get('akhir_fmt'):
                _hms2 = _fmt_hms(_s.get('akhir'))
                _suf2 = f"  <code>[{_hms2}]</code>" if _hms2 else ""
                sms_lines += f"  Sms Akhir: <b>{_html.escape(_s['akhir_fmt'])}</b>{_suf2}\n"
            if _s.get('jebol') is True:
                sms_lines += f"  {_DOT} {em(E1,'✅')} <b>JEBOLEH — sms_wait udah kereset</b>\n"
            elif _s.get('jebol') is False:
                note = f" ({_s['note']})" if _s.get('note') else ""
                sms_lines += f"  {_DOT} {em(E2,'❌')} <b>GAK JEBOL</b><i>{_html.escape(note)}</i>\n"
            elif _s.get('note'):
                sms_lines += f"  {_DOT} {em(CE_WAKTU,'⏱')} <i>{_html.escape(_s['note'])}</i>\n"
        elif multi:
            # multi-nomor: tampil list semua nomor, yg gak ke-detect ditandain
            rows = []
            for _n in numbers:
                _s = sms_map.get(str(_n))
                if not _s or not _s.get('awal_fmt'):
                    rows.append(
                        f"  {_DOT} <code>+{_html.escape(str(_n))}</code> — "
                        f"{em(E2,'❌')} <i>gak bisa ke-detect</i>")
                    continue
                v = ""
                if _s.get('jebol') is True:
                    v = f" {em(E1,'✅')} <b>JEBOLEH</b>"
                elif _s.get('jebol') is False:
                    v = f" {em(E2,'❌')} <b>GAK JEBOL</b>"
                elif _s.get('note'):
                    v = f" <i>{_html.escape(_s['note'])}</i>"
                cur = _wait_short(_s.get('akhir_fmt') or _s.get('awal_fmt'))
                rows.append(
                    f"  {_DOT} <code>+{_html.escape(str(_n))}</code> — "
                    f"<b>{_html.escape(cur)}</b>{v}")
            sms_lines += "  Sms:\n" + "\n".join(rows) + "\n"

        return _screen('FIX WHATSAPP · RESET OTP', (
            f"⌁ <b>{_html.escape(state['stage'])}</b>\n\n"
            f"{notice}"
            f"  Mode: <b>{state['mode'].upper()}</b> · Limit <b>{state['limit']} jam</b>\n"
            f"  Nomor: <code>+{_html.escape(state['nomor'] or '-')}</code>\n"
            f"  Device: <b>{_html.escape(state['ua'] or '-')}</b>\n"
            f"  Operator: <b>{_html.escape(state['carrier'] or '-')}</b>\n"
            f"{sms_lines}\n"
            f"{progress}"
            + (f"\n\n<i>{_html.escape(state['msg'])}</i>" if state['msg'] else "")
        ))

    async def _safe_edit():
        try:
            await message.edit_text(_render(), parse_mode=ParseMode.HTML)
        except Exception:
            pass

    def _push():
        try:
            main_loop.call_soon_threadsafe(lambda: asyncio.create_task(_safe_edit()))
        except Exception:
            pass

    def _cb(stage, data):
        data = data or {}
        if stage == 'start':
            state['banding_n'] = data.get('banding', 0)
            state['faq1_n'] = data.get('faq1', 0)
            state['faq2_n'] = data.get('faq2', 0)
            state['faq3_n'] = data.get('faq3', 0)
            state['faq4_n'] = data.get('faq4', 0)
        elif stage == 'reserve':
            state['nomor'] = str(data.get('nomor', ''))
            state['stage'] = 'Menyiapkan pengirim...'
        elif stage == 'device':
            state['nomor'] = str(data.get('nomor', '')) or state['nomor']
            state['ua'] = data.get('ua', '')
            state['carrier'] = data.get('carrier', '')
        elif stage == 'faq1':
            state['faq1_ok'] = data.get('count', 0)
            state['stage'] = 'Form V1 terkirim'
            state['msg'] = f"Form V1: {data.get('count', 0)}/{data.get('total', 0)}"
        elif stage == 'send_ok':
            state['sent'] += 1
            state['email_sent'] = len(data.get('sent_to', []))
            state['faq1_ok'] = data.get('faq1', state['faq1_ok'])
            state['faq2_ok'] = data.get('faq2', state['faq2_ok'])
            state['faq3_ok'] = data.get('faq3', state['faq3_ok'])
            state['faq4_ok'] = data.get('faq4', state['faq4_ok'])
            state['stage'] = 'Email banding terkirim'
            state['msg'] = f"Terkirim ke {len(data.get('sent_to', []))} alamat support"
            _schedule_fix_log(data.get('nomor') or state['nomor'], 'SENT')
        elif stage == 'faq2':
            cnt = data.get('count', 0)
            tot = data.get('total', 20)
            state['faq2_ok'] = cnt
            state['stage'] = 'Form verifikasi V2 terkirim'
            state['msg'] = f"Form V2: {cnt}/{tot}"
        elif stage == 'faq3':
            cnt = data.get('count', 0)
            tot = data.get('total', 2)
            state['faq3_ok'] = cnt
            state['stage'] = 'Form V3 terkirim'
            err = data.get('error') or ''
            state['msg'] = f"Form V3: {cnt}/{tot}" + (f" — {err}" if err and cnt == 0 else "")
        elif stage == 'faq4':
            cnt = data.get('count', 0)
            tot = data.get('total', 1)
            state['faq4_ok'] = cnt
            state['stage'] = 'Form V4 terkirim'
            err = data.get('error') or ''
            state['msg'] = f"Form V4: {cnt}/{tot}" + (f" — {err}" if err and cnt == 0 else "")
        elif stage == 'send_err':
            state['stage'] = 'Gagal kirim'
            state['msg'] = f"❌ {str(data.get('error',''))[:120]}"
        elif stage == 'wait_reply':
            state['stage'] = 'Menunggu balasan WhatsApp Support...'
            state['waiting'] = True
            state['msg'] = ''
        elif stage == 'reply':
            state['replied'] += 1
            state['stage'] = 'Balasan diterima!'
            _schedule_fix_log(data.get('nomor') or state['nomor'], 'SUCCESS')
        _push()

    async def _sms_monitor():
        """Round-robin cek sms_wait selama nunggu balasan.

        Pacing: tunggu 90 dtk pertama (biar gak tabrakan sama pipeline yang
        lagi kirim banding/form — request detect barengan bikin HTTP 400),
        lalu 1 nomor per 30 dtk (round-robin). Jeda antar-cek per nomor yang
        sama jadi 30 dtk × jumlah nomor.

        Sms Akhir cuma dicatet/dimunculin kalau nilai TURUN DRASTIS dari awal
        (>= 60% dari awal + hasil < 40 mnt, atau < 5 mnt). Turunan kecil
        (mis. 30 dtk) dianggap masih sama → gak dimunculin.

        Per nomor:
          Jebol     = turun drastis + hasil < 40 mnt → jebol=True.
          Belum     = turunan kecil → terus dipantau.
          Gak jebol = 10 mnt gak ada perubahan signifikan → jebol=False.
        Monitor selesai kalau semua nomor udah ada verdict atau balasan masuk.
        """
        sms_map = state.get('sms_map') or {}
        targets = [k for k, v in sms_map.items() if v.get('awal_fmt')]
        if not targets:
            return
        await asyncio.sleep(90)  # grace period: biar pipeline dulu jalan
        idx = 0
        while True:
            await asyncio.sleep(30)
            replied = state.get('replied') or 0
            active = [k for k in targets
                      if sms_map[k].get('jebol') is None]
            if not active or replied >= len(numbers):
                return
            # round-robin: satu nomor per tick (10 dtk) biar gak ngebomb API
            num = active[idx % len(active)]
            idx += 1
            s = sms_map[num]
            d = await _detect_otp_wait(num)
            now = time.time()
            if not d.get('ok'):
                s['last_fail'] = now
                # nomor gak bisa ke-detect beberapa lama → anggap gak jebol
                last_ok = s.get('last_change') or now
                if now - last_ok >= 600:
                    s['jebol'] = False
                    s['note'] = "nomor gak bisa ke-detect lagi"
                _push()
                continue
            val = d.get('sms_wait')
            awal = s.get('awal')
            s['last_fail'] = None
            s['last_val'] = val
            # ── Jebol = TURUN DRASTIS dari awal, bukan nilai mentah. ──
            # Kalau awalnya aja udah < 40 mnt (mis. 11 mnt), itu bukan jebol —
            # nomornya emang gak kena limit besar. Jebol = awal - akhir >= 60%
            # dari awal DAN akhir < 40 mnt, atau akhir < 5 mnt.
            turun = (awal - val) if (isinstance(awal, int) and isinstance(val, int)) else 0
            if isinstance(val, int) and (
                val < 300 or
                (val < 2400 and turun >= max(600, int(awal * 0.6)))
            ):
                # jebol beneran → catat akhir + verdict
                s['akhir'] = val
                s['akhir_fmt'] = d.get('sms_wait_fmt')
                s['jebol'] = True
                _push()
                continue
            if isinstance(val, int) and turun >= 3600:
                # turun >= 1 jam dari awal → signifikan, catat akhir (belum tentu jebol)
                s['akhir'] = val
                s['akhir_fmt'] = d.get('sms_wait_fmt')
                s['last_change'] = now
                _push()
                continue
            # nilai masih tinggi / turunan kecil → anggap belum berubah
            if not s.get('note') and now - s.get('last_change', now) >= 300:
                # 5 mnt stabil → belum kereset, masih dipantau
                s['note'] = "belum kereset — masih dipantau"
            if now - s.get('last_change', now) >= 600:
                # 10 mnt gak ada perubahan signifikan → gak jebol bosku
                s['jebol'] = False
            _push()

    monitor_task = asyncio.create_task(_sms_monitor())
    await _safe_edit()

    # Hitung countdown "HH:MM:SS" dari sms_wait detect terbesar — dipakai di
    # teks banding supaya cocok dengan bukti screenshot "Try again in HH:MM:SS".
    # Kalau gak ada nomor yang ke-detect, pipeline fallback pakai limit_hours.
    _sms_countdown = None
    try:
        _sms_map_now = state.get('sms_map') or {}
        _max_wait = 0
        for _s in _sms_map_now.values():
            _v = _s.get('awal')
            if isinstance(_v, int) and _v > _max_wait:
                _max_wait = _v
        if _max_wait > 0:
            _h, _rem = divmod(int(_max_wait), 3600)
            _m, _sc = divmod(_rem, 60)
            _sms_countdown = f"{_h:02d}:{_m:02d}:{_sc:02d}"
    except Exception:
        _sms_countdown = None

    try:
        res = await asyncio.wait_for(
            main_loop.run_in_executor(
                _SITEPRO_GLOBAL_POOL,
                functools.partial(
                    run_reset_otp_pipeline,
                    [str(n) for n in numbers],
                    db_cur=cur, db_conn=conn, progress_cb=_cb,
                    mode=mode, limit_hours=limit_hours,
                    sms_countdown=_sms_countdown,
                    reply_wait=60,
                ),
            ),
            timeout=480,  # 8 menit — pipeline dipercepat
        )
    except asyncio.TimeoutError:
        monitor_task.cancel()
        _refund_charge_if_failed("timeout pipeline")
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · RESET OTP',
                        f"{em(E2,'❌')} Proses timeout (15 menit)."
                        + (f"\n<i>{RESETOTP_TOKEN_COST} token dikembalikan.</i>" if token_charged else "")),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return
    except Exception as e:
        monitor_task.cancel()
        _refund_charge_if_failed("pipeline error")
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP · RESET OTP',
                        f"{em(E2,'❌')} Pipeline error: {_html.escape(str(e))[:300]}"
                        + (f"\n<i>{RESETOTP_TOKEN_COST} token dikembalikan.</i>" if token_charged else "")),
                parse_mode=ParseMode.HTML)
        except Exception:
            pass
        return
    finally:
        monitor_task.cancel()

    ok = res.get('success_count', 0)
    fail = res.get('fail_count', 0)
    total_reply = sum(1 for it in res.get('items', []) if it.get('newest_reply'))

    # ── Refund token / trial berdasar hasil ──
    # Token & trial sudah DIPESAN di awal run. Kalau tidak ada satu pun nomor
    # yang berhasil terkirim (mis. "Tidak ada sender siap"), keduanya
    # dikembalikan. Kalau minimal 1 terkirim: biaya tetap terpakai.
    refunded_note = ""
    trial_note = ""
    if ok <= 0:
        if token_charged:
            _refund_tokens_if_charged("tidak ada yang terkirim")
            refunded_note = f"\n<i>{RESETOTP_TOKEN_COST} token dikembalikan (gagal).</i>"
        if trial_reserved:
            refund_trial(user_id)
            trial_reserved = False
            trial_note = ("\n<i>Trial tidak terpotong karena proses gagal "
                          f"(sisa {trial_left(user_id)}/{RESETOTP_TRIAL_LIMIT}).</i>")
    else:
        if trial_reserved:
            trial_note = (f"\n<i>Ini pemakaian TRIAL gratis — sisa "
                          f"{trial_left(user_id)}/{RESETOTP_TRIAL_LIMIT}.</i>")

    for it in res.get('items', []):
        phone = it.get('nomor')
        if it.get('newest_reply'):
            event_key = (str(phone), 'SUCCESS')
            if event_key not in logged_events:
                logged_events.add(event_key)
                await notify_fix_group_log(
                    user_id=user_id,
                    phone=phone,
                    status='SUCCESS',
                    banding_id=banding_map.get(str(phone)),
                    server='resetotp',
                    source='bot',
                    username=log_username,
                    full_name=log_fullname,
                    chat_origin=chat_origin,
                    limit_hours=limit_hours,
                )
        elif it.get('ok'):
            event_key = (str(phone), 'SENT')
            if event_key not in logged_events:
                logged_events.add(event_key)
                await notify_fix_group_log(
                    user_id=user_id,
                    phone=phone,
                    status='SENT',
                    banding_id=banding_map.get(str(phone)),
                    server='resetotp',
                    source='bot',
                    username=log_username,
                    full_name=log_fullname,
                    chat_origin=chat_origin,
                    limit_hours=limit_hours,
                )

    lines = []
    for it in res.get('items', []):
        email_count = len(it.get('sent_to', []))
        faq1_c = it.get('faq1_ok') or sum(1 for r in it.get('faq1_results', []) if r.get('ok'))
        faq2_c = it.get('faq2_ok') or sum(1 for r in it.get('faq2_results', []) if r.get('ok'))
        faq3_c = it.get('faq3_ok') or sum(1 for r in it.get('faq3_results', []) if r.get('ok'))
        faq4_c = it.get('faq4_ok') or sum(1 for r in it.get('faq4_results', []) if r.get('ok'))
        if it.get('newest_reply'):
            icon = "✅"; tag = "balasan diterima"
        elif it.get('ok'):
            icon = "⌁"
            tag = f"terkirim (banding {email_count}, V1 {faq1_c}, V2 {faq2_c}, V3 {faq3_c}, V4 {faq4_c})"
        else:
            icon = "❌"; tag = _html.escape(str(it.get('error', ''))[:60]) or "gagal"
        lines.append(f"  {icon} <code>+{it.get('nomor')}</code> — {tag}")
    detail = "\n".join(lines) if lines else "  -"

    # Kartu balasan asli WA Support
    reply_card = ""
    newest = next((it.get('newest_reply') for it in res.get('items', [])
                   if it.get('newest_reply')), None)
    if newest:
        reply_card = (
            f"\n\n⌁ <b>Balasan dari WhatsApp Support</b>\n"
            f"  Dari: <code>{_html.escape(newest.get('from','') or 'support@support.whatsapp.com')}</code>\n"
        )

    # Hitung total email & form dari semua item
    total_emails = sum(len(it.get('sent_to', [])) for it in res.get('items', []))
    total_faq1 = sum(int(it.get('faq1_ok') or 0) for it in res.get('items', []))
    total_faq2 = sum(
        int(it.get('faq2_ok') or 0)
        or sum(1 for r in it.get('faq2_results', []) if r.get('ok'))
        for it in res.get('items', [])
    )
    total_faq3 = sum(int(it.get('faq3_ok') or 0) for it in res.get('items', []))
    total_faq4 = sum(int(it.get('faq4_ok') or 0) for it in res.get('items', []))
    mode_lbl = (res.get('mode') or mode or 'hard').upper()
    jam_lbl = res.get('limit_hours') or limit_hours or 24

    def _dots(ok, total):
        n = max(total, 1)
        filled = min(ok, n)
        return "●" * filled + "○" * (n - filled)

    bd_t = res.get('banding_n') or state.get('banding_n') or 5
    f1_t = res.get('faq1_n') or state.get('faq1_n') or 3
    f2_t = res.get('faq2_n') or state.get('faq2_n') or 8
    f3_t = res.get('faq3_n') or state.get('faq3_n') or 2
    f4_t = res.get('faq4_n') or state.get('faq4_n') or 1

    if total_reply > 0:
        title = 'FIX WHATSAPP · RESET OTP — BALASAN DITERIMA'
    elif ok > 0:
        title = 'FIX WHATSAPP · RESET OTP — TERKIRIM'
    else:
        title = 'FIX WHATSAPP · RESET OTP — GAGAL'

    # Blok Sms Awal/Akhir di layar final — Akhir cuma muncul kalau sempat
    # berubah signifikan (turun >= 1 jam / jebol) sebelum monitor selesai.
    final_sms = ""
    sms_map = state.get('sms_map') or {}
    if len(sms_map) == 1:
        _num, _s = next(iter(sms_map.items()))
        if _s.get('awal_fmt'):
            final_sms += f"  Sms Awal : <b>{_html.escape(_s['awal_fmt'])}</b>\n"
        if _s.get('akhir_fmt'):
            final_sms += f"  Sms Akhir: <b>{_html.escape(_s['akhir_fmt'])}</b>\n"
        if _s.get('jebol') is True:
            final_sms += f"  ⌁ {em(E1,'✅')} <b>JEBOLEH — sms_wait udah kereset</b>\n"
        elif _s.get('jebol') is False:
            note = f" ({_s['note']})" if _s.get('note') else ""
            final_sms += f"  ⌁ {em(E2,'❌')} <b>GAK JEBOL</b><i>{_html.escape(note)}</i>\n"
        if final_sms:
            final_sms += "\n"
    elif sms_map:
        rows = []
        for _n, _s in sms_map.items():
            v = ""
            if _s.get('jebol') is True:
                v = f" {em(E1,'✅')} <b>JEBOLEH</b>"
            elif _s.get('jebol') is False:
                v = f" {em(E2,'❌')} <b>GAK JEBOL</b>"
            akhir = _s.get('akhir_fmt') or "-"
            rows.append(
                f"  ⌁ <code>+{_html.escape(str(_n))}</code> — awal <b>{_html.escape(_s.get('awal_fmt') or '-')}</b>"
                f" · akhir <b>{_html.escape(akhir)}</b>{v}")
        final_sms = "  Sms Awal/Akhir:\n" + "\n".join(rows) + "\n\n"

    try:
        await message.edit_text(
            _screen(title, (
                f"  Mode: <b>{mode_lbl}</b> · Limit <b>{jam_lbl} jam</b>\n\n"
                f"{final_sms}"
                f"  Banding  {_dots(total_emails, bd_t)}  <b>{total_emails}</b>\n"
                f"  Form V1  {_dots(total_faq1, f1_t)}  <b>{total_faq1}</b>\n"
                f"  Form V2  {_dots(total_faq2, f2_t)}  <b>{total_faq2}</b>\n"
                f"  Form V3  {_dots(total_faq3, f3_t)}  <b>{total_faq3}</b>\n"
                f"  Form V4  {_dots(total_faq4, f4_t)}  <b>{total_faq4}</b>\n"
                f"  ─────────────────\n"
                f"  Gagal: <b>{fail}</b>  ·  "
                f"Balasan: <b>{total_reply}</b>\n\n"
                f"<blockquote>{detail}</blockquote>"
                f"{reply_card}\n"
                f"<i>Sender cooldown 1 jam</i>"
                f"{refunded_note}"
                f"{trial_note}"
            )),
            parse_mode=ParseMode.HTML)
    except Exception:
        pass



async def _process_fix_background(numbers, user_id, message, context):
    """Background worker /fix: 1 akun, kirim ke banyak nomor + cek balasan."""
    total = len(numbers)
    main_loop = asyncio.get_running_loop()
    fix_run_id = None
    try:
        cur.execute(
            "INSERT INTO fix_runs (user_id, total, status) VALUES (?, ?, 'running')",
            (user_id, total),
        )
        fix_run_id = cur._get_cur().lastrowid
        cur.executemany(
            "INSERT INTO fix_run_items (run_id, phone) VALUES (?, ?)",
            [(fix_run_id, n) for n in numbers],
        )
        conn.commit()
    except Exception as e:
        logging.warning("[FIX] Gagal membuat ledger status: %s", e)

    can_start, limit_msg = _sitepro_can_start(user_id)
    if not can_start:
        if fix_run_id:
            try:
                cur.execute(
                    """UPDATE fix_runs SET status = 'rejected', failed_count = total,
                       completed_at = CURRENT_TIMESTAMP WHERE id = ?""",
                    (fix_run_id,),
                )
                cur.execute(
                    """UPDATE fix_run_items SET status = 'rejected', detail = ?,
                       updated_at = CURRENT_TIMESTAMP WHERE run_id = ?""",
                    (str(limit_msg)[:300], fix_run_id),
                )
                conn.commit()
            except Exception:
                pass
        try:
            await message.edit_text(
                _screen('FIX WHATSAPP',
                        f"{em(E2,'❌')} {limit_msg}"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    # State untuk progress (di-update dari thread, dirender dari async)
    state = {
        'stage': 'starting',
        'sent_done': 0,
        'reply_done': 0,
    }
    _sel_lang = None
    _sel_server = None
    try:
        _sel_lang = context.user_data.get('fix_lang') if context else None
        custom_template = get_user_fix_template(user_id, _sel_lang)
    except Exception:
        custom_template = None
    try:
        _sel_server = int(context.user_data.get('fix_server') or 0) or None
    except Exception:
        _sel_server = None

    log_username, log_fullname = await _resolve_tg_profile(user_id)
    banding_map = {str(n): _new_fix_banding_id() for n in numbers}
    logged_events = set()
    chat_origin = "-"
    try:
        chat_origin = (context.user_data.get("fix_chat_origin") if context else None) or "-"
    except Exception:
        chat_origin = "-"

    def _schedule_fix_log(phone, status_key):
        phone_key = str(phone or "").strip()
        if not phone_key:
            return
        event_key = (phone_key, status_key)
        if event_key in logged_events:
            return
        logged_events.add(event_key)
        bid = banding_map.get(phone_key) or _new_fix_banding_id()
        try:
            main_loop.call_soon_threadsafe(
                lambda p=phone_key, s=status_key, b=bid: asyncio.create_task(
                    notify_fix_group_log(
                        user_id=user_id,
                        phone=p,
                        status=s,
                        banding_id=b,
                        server=_sel_server,
                        source="bot",
                        username=log_username,
                        full_name=log_fullname,
                        chat_origin=chat_origin,
                    )
                )
            )
        except Exception:
            pass

    def _render(stage_label):
        sent = state['sent_done']
        rep = state['reply_done']
        body = (
            f"{em(CE_LOADING,'🟠')} <b>{stage_label}</b>\n\n"
            f"  {em(CE_NOMOR,'📞')} Nomor: <b>{total}</b>\n"
            f"  {em(E6,'🚀')} Terkirim: <b>{sent}/{total}</b>\n"
            f"  {em(CE_WHATSAPP,'❤️')} Balasan: <b>{rep}</b>\n"
        )
        return _screen('FIX WHATSAPP', body)

    async def _safe_edit(text):
        try:
            await message.edit_text(text, parse_mode=ParseMode.HTML)
        except Exception:
            pass

    def _progress_cb(stage, data):
        # Dipanggil dari thread pipeline. Schedule update di main loop.
        data = data or {}
        if stage == 'account_ready':
            state['stage'] = 'kirim'
            reused = bool(data.get('reused'))
            label = "Akun siap (digunakan ulang)..." if reused else "Akun baru siap..."
        elif stage == 'sent':
            if data.get('ok'):
                state['sent_done'] += 1
                _schedule_fix_log(data.get('nomor'), 'SENT')
            label = "Mengirim permintaan ke WhatsApp support..."
        elif stage == 'reply':
            state['reply_done'] += 1
            _schedule_fix_log(data.get('matched') or data.get('nomor'), 'SUCCESS')
            label = "Balasan diterima dari WhatsApp!"
        else:
            label = "Memproses..."
        try:
            main_loop.call_soon_threadsafe(
                lambda: asyncio.create_task(_safe_edit(_render(label)))
            )
        except Exception:
            pass

    # Initial status
    await _safe_edit(_render("Menyiapkan akun..."))

    try:
        # Jalankan pipeline di thread (lewat global pool) agar event loop tidak ke-block,
        # dan tugas user lain BISA jalan paralel tanpa antri.
        import functools

        loop = asyncio.get_running_loop()
        result = await loop.run_in_executor(
            _SITEPRO_GLOBAL_POOL,
            functools.partial(
                run_fix_multi_pipeline,
                numbers,
                CAPTCHA_API_KEY,
                cur,
                conn,
                CAPTCHA_SOLVER,
                240,         # reply_wait (fix pipeline, 4 menit)
                _progress_cb,
                MAX_SENDS_PER_ACCOUNT,
                custom_template,  # message_template
                _sel_server,      # server (1=row_id<=150, 2=row_id>150)
            ),
        )

        # Build final report
        nomor_status = result.get('numbers', [])
        total_sent = result.get('total_sent', 0)
        total_reply = result.get('total_replied', 0)
        newest = result.get('newest_reply')

        # Fallback log grup bila progress callback terlewat
        for ns in nomor_status:
            phone = ns.get('nomor')
            if ns.get('replied'):
                event_key = (str(phone), 'SUCCESS')
                if event_key not in logged_events:
                    logged_events.add(event_key)
                    await notify_fix_group_log(
                        user_id=user_id,
                        phone=phone,
                        status='SUCCESS',
                        banding_id=banding_map.get(str(phone)),
                        server=_sel_server,
                        source='bot',
                        username=log_username,
                        full_name=log_fullname,
                        chat_origin=chat_origin,
                    )
            elif ns.get('sent'):
                event_key = (str(phone), 'SENT')
                if event_key not in logged_events:
                    logged_events.add(event_key)
                    await notify_fix_group_log(
                        user_id=user_id,
                        phone=phone,
                        status='SENT',
                        banding_id=banding_map.get(str(phone)),
                        server=_sel_server,
                        source='bot',
                        username=log_username,
                        full_name=log_fullname,
                        chat_origin=chat_origin,
                    )

        lines = []
        for ns in nomor_status:
            n = ns['nomor']
            if ns['replied']:
                icon = em(E1, '✅')
                tag = "balasan diterima"
            elif ns['sent']:
                icon = em(CE_LOADING, '🟠')
                tag = "terkirim, belum ada balasan"
            else:
                icon = em(E2, '❌')
                tag = "gagal kirim"
            lines.append(f"  {icon} <code>+{n}</code> — {tag}")

        if fix_run_id:
            try:
                failed_count = sum(1 for ns in nomor_status if not ns.get('sent'))
                for ns in nomor_status:
                    item_status = 'reply' if ns.get('replied') else ('sent' if ns.get('sent') else 'failed')
                    cur.execute(
                        """UPDATE fix_run_items
                           SET status = ?, detail = ?, updated_at = CURRENT_TIMESTAMP
                           WHERE run_id = ? AND phone = ?""",
                        (item_status, 'Balasan diterima' if ns.get('replied') else tag,
                         fix_run_id, ns.get('nomor')),
                    )
                cur.execute(
                    """UPDATE fix_runs
                       SET status = 'completed', sent_count = ?, reply_count = ?,
                           failed_count = ?, completed_at = CURRENT_TIMESTAMP
                       WHERE id = ?""",
                    (total_sent, total_reply, failed_count, fix_run_id),
                )
                conn.commit()
            except Exception as e:
                logging.warning("[FIX] Gagal memperbarui ledger status: %s", e)

        reused_tag = ""
        if result.get('account_reused'):
            reused_tag = f"  {em(CE_AKUN,'👤')} Akun: <i>digunakan ulang</i> (sisa {result.get('sends_left',0)} kirim)\n"
        else:
            reused_tag = f"  {em(CE_AKUN,'👤')} Akun: <i>baru dibuat</i> (sisa {result.get('sends_left',0)} kirim)\n"

        header = (
            f"{em(CE_WHATSAPP,'❤️')} <b>Hasil Fix Merah</b>\n\n"
            f"  {em(CE_NOMOR,'📞')} Total nomor: <b>{total}</b>\n"
            f"  {em(E6,'🚀')} Terkirim: <b>{total_sent}/{total}</b>\n"
            f"  {em(E1,'✅')} Mendapat balasan: <b>{total_reply}</b>\n"
            f"{reused_tag}"
        )

        body = header + "\n<b>Detail per nomor:</b>\n" + ("\n".join(lines) if lines else "  -")

        # ── Balasan WhatsApp Support (template card) ─────────────
        # Hanya tampilkan metadata: dari WhatsApp support + subject + nomor.
        # Body sengaja TIDAK ditampilkan (sesuai permintaan user) karena sering
        # memuat ekor "Dikirim dengan email Site.pro" + echo pesan yang kita
        # kirim, jadi tidak informatif untuk end-user.
        if newest:
            import html as _h
            reply_subject = _h.escape(newest.get('subject', '') or '')
            matched_n = newest.get('matched_nomor')
            matched_line = (
                f"  {em(CE_NOMOR,'📞')} <b>Untuk nomor:</b> <code>+{matched_n}</code>\n"
                if matched_n else ""
            )
            body += (
                f"\n\n{em(CE_WHATSAPP,'❤️')} <b>Balasan dari WhatsApp Support</b>\n"
                f"  {em(CE_EMAIL,'📩')} <b>Dari:</b> "
                f"<code>support@support.whatsapp.com</code>\n"
                f"  {em(CE_FILE,'📁')} <b>Subject:</b> <i>{reply_subject}</i>\n"
                f"{matched_line}"
            )

        if result.get('error') and total_sent == 0:
            body += f"\n\n{em(E2,'❌')} <i>{result['error']}</i>"

        # Pilih title sesuai hasil: ada balasan = SUKSES, ada kirim = TERKIRIM, gagal
        if total_reply > 0:
            title = 'FIX WHATSAPP — BALASAN DITERIMA'
        elif total_sent > 0:
            title = 'FIX WHATSAPP — TERKIRIM'
        else:
            title = 'FIX WHATSAPP — GAGAL'

        try:
            await message.edit_text(
                _screen(title, body),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass

    finally:
        _sitepro_release(user_id)


