async def bulk_confirm_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Callback konfirmasi hapus semua nomor"""
    query = update.callback_query
    user_id = update.effective_user.id
    BC = 'Home › Nomor › Hapus Semua'

    if user_id in active_bulk_locks:
        await query.answer("Hapus semua sedang berjalan, mohon tunggu...")
        return

    await query.answer()
    active_bulk_locks.add(user_id)

    def _back_menu():
        return InlineKeyboardMarkup([[
            InlineKeyboardButton("KEMBALI KE MENU", callback_data=f"menu_start_{user_id}", style="danger",
                                 icon_custom_emoji_id=CE_BACK)
        ]])

    try:
        _, _, _, _, cookies_dict, csrf, logged_in = get_user_session(user_id)

        if not logged_in or not cookies_dict or not csrf:
            await query.edit_message_text(
                _ivas_session_expired(BC, user_id),
                parse_mode=ParseMode.HTML,
                reply_markup=get_back_keyboard(user_id)
            )
            return

        session = requests.Session()
        for key, value in cookies_dict.items():
            session.cookies.set(key, value)

        await query.edit_message_text(
            _ivas_screen(
                'HAPUS SEMUA NOMOR',
                f"  {em(CE_HAPUS,'🗑')} <b>Sedang menghapus semua nomor...</b>\n"
                f"  {em(CE_LOADING,'🟠')} Mohon tunggu, proses ini butuh waktu.",
                BC,
            ),
            parse_mode=ParseMode.HTML
        )

        success, message = await bg.run(user_id, bulk_return_numbers, session, csrf)

        if success:
            safe_msg = html.escape(str(message))
            await query.edit_message_text(
                _ivas_ok(
                    'HAPUS SEMUA NOMOR',
                    f"  {_DOT} {safe_msg}\n"
                    f"  <i>Semua nomor telah dihapus dari akun kamu.</i>",
                    BC,
                ),
                parse_mode=ParseMode.HTML,
                reply_markup=_back_menu()
            )
        else:
            if "419" in str(message) or "CSRF" in str(message):
                await query.edit_message_text(
                    _ivas_screen(
                        'HAPUS SEMUA NOMOR',
                        f"  <i>CSRF token mismatch — mencoba refresh…</i>",
                        BC,
                    ),
                    parse_mode=ParseMode.HTML
                )

                new_csrf = await bg.run(user_id, refresh_csrf_token, session)

                if new_csrf:
                    success2, message2 = await bg.run(user_id, bulk_return_numbers, session, new_csrf)

                    if success2:
                        safe_msg2 = html.escape(str(message2))
                        await query.edit_message_text(
                            _ivas_ok(
                                'HAPUS SEMUA NOMOR',
                                f"  {_DOT} {safe_msg2}\n"
                                f"  <i>Semua nomor telah dihapus.</i>",
                                BC,
                            ),
                            parse_mode=ParseMode.HTML,
                            reply_markup=_back_menu()
                        )
                        return

                safe_msg = html.escape(str(message))
                await query.edit_message_text(
                    _ivas_fail(
                        'HAPUS SEMUA NOMOR',
                        f"  {_DOT} {safe_msg}\n"
                        f"  {_DOT} Coba lagi atau login ulang dengan <code>/cookies</code>.",
                        BC,
                    ),
                    parse_mode=ParseMode.HTML,
                    reply_markup=get_back_keyboard(user_id)
                )
            else:
                safe_msg = html.escape(str(message))
                await query.edit_message_text(
                    _ivas_fail('HAPUS SEMUA NOMOR', f"  {safe_msg}", BC),
                    parse_mode=ParseMode.HTML,
                    reply_markup=get_back_keyboard(user_id)
                )

    except Exception as e:
        logger.error(f"Error bulk_confirm: {e}")
        await query.edit_message_text(
            _ivas_fail('HAPUS SEMUA NOMOR', f"  <code>{html.escape(str(e)[:150])}</code>", BC),
            parse_mode=ParseMode.HTML,
            reply_markup=get_back_keyboard(user_id)
        )
    finally:
        active_bulk_locks.discard(user_id)

def refresh_csrf_token(session):
    """Refresh CSRF token dari halaman"""
    try:
        response = session.get(NUMBERS_PAGE_URL, timeout=15)
        if response.status_code == 200:

            match = re.search(r'<meta name="csrf-token" content="([^"]+)"', response.text)
            if match:
                return match.group(1)


            match = re.search(r'X-CSRF-TOKEN["\s:]+"([^"]+)"', response.text)
            if match:
                return match.group(1)
        return None
    except Exception as e:
        print(f"Error refresh CSRF: {e}")
        return None

