async def process_export_background(msg, user_id, format_type, context, session, csrf):
    """Background process untuk export"""

    BC = 'Home › Nomor › Export'
    try:
        success, filename, message = await bg.run(user_id, export_numbers, session, csrf, format_type)

        if success and filename:
            try:
                if os.path.getsize(filename) == 0:
                    await msg.edit_text(
                        _ivas_screen('EXPORT NOMOR',
                            f"  {em(E2,'⭐')} <b>TIDAK ADA NOMOR</b>\n"
                            f"  File hasil export kosong.", BC),
                        parse_mode=ParseMode.HTML,
                        reply_markup=get_back_keyboard(user_id)
                    )
                    try:
                        os.remove(filename)
                    except:
                        pass
                    return

                # Hitung statistik file untuk caption yang informatif
                file_size = os.path.getsize(filename)
                line_count = 0
                if format_type == 'txt':
                    try:
                        with open(filename, 'r', encoding='utf-8') as tf:
                            line_count = sum(1 for _ in tf)
                    except:
                        pass

                # Format ukuran file
                if file_size >= 1048576:
                    size_display = f"{file_size/1048576:.1f} MB"
                elif file_size >= 1024:
                    size_display = f"{file_size/1024:.1f} KB"
                else:
                    size_display = f"{file_size} B"

                now_str = datetime.now().strftime('%d/%m/%Y %H:%M')

                if format_type == 'txt' and line_count > 0:
                    caption = _ivas_screen('EXPORT SELESAI', (
                        f"  {em(CE_EXPORT,'⬆️')} <b>Format</b>  {format_type.upper()}\n"
                        f"  {em(CE_NOMOR,'📱')} <b>Total</b>  <code>{line_count:,} nomor</code>\n"
                        f"  {em(E2,'⭐')} <b>Ukuran</b>  <code>{size_display}</code>\n"
                        f"  {em(CE_WAKTU,'🕒')} <b>Waktu</b>  <code>{now_str}</code>"
                    ), BC)
                else:
                    caption = _ivas_screen('EXPORT SELESAI', (
                        f"  {em(CE_EXPORT,'⬆️')} <b>Format</b>  {format_type.upper()}\n"
                        f"  {em(E2,'⭐')} <b>Ukuran</b>  <code>{size_display}</code>\n"
                        f"  {em(CE_WAKTU,'🕒')} <b>Waktu</b>  <code>{now_str}</code>"
                    ), BC)

                with open(filename, 'rb') as f:
                    await context.bot.send_document(
                        chat_id=msg.chat_id,
                        document=f,
                        filename=os.path.basename(filename),
                        caption=caption,
                        parse_mode=ParseMode.HTML
                    )

                try:
                    os.remove(filename)
                except:
                    pass

                await msg.delete()

            except Exception as e:
                await msg.edit_text(
                    _ivas_fail('EXPORT NOMOR',
                        f"  Gagal mengirim file.\n"
                        f"  <code>{html.escape(str(e)[:150])}</code>", BC),
                    parse_mode=ParseMode.HTML,
                    reply_markup=get_back_keyboard(user_id)
                )
                try:
                    os.remove(filename)
                except:
                    pass
        else:
            error_msg = html.escape(str(message)) if message else "Tidak ada nomor"
            await msg.edit_text(
                _ivas_screen('EXPORT NOMOR',
                    f"  {em(E2,'⭐')} <b>TIDAK ADA NOMOR</b>\n"
                    f"  {error_msg}", BC),
                parse_mode=ParseMode.HTML,
                reply_markup=get_back_keyboard(user_id)
            )
    except Exception as e:
        logger.error(f"Error export: {e}")
        await msg.edit_text(
            _ivas_fail('EXPORT NOMOR', f"  <code>{html.escape(str(e)[:150])}</code>", BC),
            parse_mode=ParseMode.HTML,
            reply_markup=get_back_keyboard(user_id)
        )

async def process_top_refresh_background(msg, user_id):
    """Background process untuk top refresh"""

    BC = 'Home › SMS › Top Negara'
    try:
        success, result = await bg.run(user_id, fetch_top_countries)

        if not success:
            await msg.edit_text(
                _ivas_fail('TOP NEGARA', f"  {html.escape(str(result)[:200])}", BC),
                parse_mode=ParseMode.HTML,
                reply_markup=get_back_keyboard(user_id)
            )
            return

        total, countries = result


        max_count = countries[0]['count'] if countries else 1


        countries_text = ""
        for i, country in enumerate(countries[:30], 1):
            flag = get_country_flag(country['country'])
            country_name = html.escape(str(country['country']))
            count = country['count']
            bar = _mini_dots(count, max_count, 10)
            percentage = int((count / max_count) * 100)
            countries_text += (
                f"  <code>{i:02d}</code> {flag} <b>{country_name}</b>\n"
                f"      {_DOT} <code>{bar}</code> {count:>4} ({percentage:>3}%)\n"
            )

        now_str = (datetime.now() + timedelta(hours=8)).strftime('%d/%m %H:%M WITA')
        text = _ivas_screen('TOP NEGARA AKTIF', (
            f"  {_DOT} <b>Update</b>  <code>{now_str}</code>\n"
            f"  {_DOT} <b>Total</b>  <code>{total} negara</code>\n\n"
            f"{countries_text}"
        ), BC)

        await msg.edit_text(
            text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("REFRESH", callback_data=f"top_refresh_{user_id}", style="primary",
                                     icon_custom_emoji_id=CE_LOADING),
                InlineKeyboardButton("MENU", callback_data=f"menu_start_{user_id}", style="danger",
                                     icon_custom_emoji_id=CE_BACK)
            ]])
        )
    except Exception as e:
        logger.error(f"Error top refresh: {e}")
        await msg.edit_text(
            _ivas_fail('TOP NEGARA', f"  <code>{html.escape(str(e)[:150])}</code>", BC),
            parse_mode=ParseMode.HTML,
            reply_markup=get_back_keyboard(user_id)
        )


