async def add_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Command /add - Single add via WebSocket"""
    if not is_allowed_user(update.effective_user.id):
        return
    try:
        user_id = update.effective_user.id


        if not check_user_login(user_id):
            await update.message.reply_text(
                _ivas_need_login('Home › Nomor › Add'),
                parse_mode=ParseMode.HTML,
                reply_markup=get_back_keyboard(user_id)
            )
            return

        if not context.args:
            await update.message.reply_text(
                _ivas_screen('CARA PAKAI /add', (
                    f"  {_DOT} <b>Format</b>  <code>/add [RANGE]</code>\n\n"
                    f"  {_DOT} <b>Contoh</b>\n"
                    f"      {_DOT} <code>/add EGYPT 70</code>\n"
                    f"      {_DOT} <code>/add PERU 91</code>\n"
                    f"      {_DOT} <code>/add KAZAKHSTAN 13003</code>\n\n"
                    f"  {_DOT} Pakai <code>/top</code> untuk lihat negara aktif.\n"
                    f"  {_DOT} Proses lewat WebSocket biar cepat."
                ), 'Home › Nomor › Add'),
                parse_mode=ParseMode.HTML,
                reply_markup=get_back_keyboard(user_id)
            )
            return

        input_text = " ".join(context.args)


        email, _, _, _, _, _, _ = get_user_session(user_id)


        msg = await update.message.reply_text(
            _ivas_screen('ADD NUMBER', (
                f"  {_DOT} <b>Range</b>  <code>{html.escape(input_text)}</code>\n"
                f"  {_DOT} <b>Akun</b>  <code>{html.escape(str(email))}</code>\n"
                f"  {_DOT} Bersihkan nomor lama  <i>berjalan</i>\n"
                f"  {_DOT} Sambung socket  <i>menunggu</i>\n"
                f"  {_DOT} Tambah nomor  <i>menunggu</i>"
            ), 'Home › Nomor › Add'),
            parse_mode=ParseMode.HTML
        )


        task_id = f"add_{user_id}_{int(time.time())}"


        asyncio.create_task(process_add_background(
            msg, user_id, email, input_text, task_id, "add"
        ))

    except Exception as e:
        logger.error(f"Error add_command: {e}")
        await update.message.reply_text(
            _ivas_fail('ADD NUMBER', f"  <code>{html.escape(str(e)[:150])}</code>", 'Home › Nomor › Add'),
            parse_mode=ParseMode.HTML
        )


