async def owner_list_users_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Menampilkan list user yang diizinkan dengan opsi HAPUS"""
    user_id = update.effective_user.id
    if not is_owner(user_id):
        return

    query = update.callback_query
    if query:
        await query.answer()

    cur.execute("""
        SELECT user_id, username, added_by, added_at
        FROM allowed_users
        ORDER BY added_at DESC
    """)
    users = cur.fetchall()

    text = f"{em(CE_PROFILE, '👤')} <b>DAFTAR USER YANG DIIZINKAN</b>\n\n"

    keyboard = []

    if not users:
        text += "📭 <i>Belum ada user yang diizinkan selain owner.</i>\n"
    else:
        for uid, username, added_by, added_at in users:
            username_display = f"@{username}" if username else "no_username"
            tag = " (Owner)" if uid == USER_ID else ""
            text += f"  {em(E1, '⭐')} <code>{uid}</code> | <code>{username_display}</code>{tag}\n"

            # Jangan tampilkan tombol hapus untuk owner sendiri
            if uid != USER_ID:
                keyboard.append([
                    InlineKeyboardButton(f"HAPUS: {uid} ({username_display})", callback_data=f"owner_del_user_{uid}", style="danger")
                ])

    text += f"\nTotal: <b>{len(users)} user</b>"
    keyboard.append([InlineKeyboardButton("KEMBALI", callback_data="owner_menu", style="danger")])

    reply_markup = InlineKeyboardMarkup(keyboard)
    if query:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=reply_markup)
    else:
        await update.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=reply_markup)


# ════════════════════════════════════════════════════════════════
#  GATE KEPEMILIKAN TOMBOL INLINE
# ════════════════════════════════════════════════════════════════
# Semua callback_data di bot ini menyimpan ID pemilik tombol. Formatnya
# tidak seragam, jadi pemilik diambil per-pola:
#
#   1. OWNER-ONLY  → hanya USER_ID (owner console, switch akun).
#   2. BEBAS       → boleh ditekan siapa pun (noop).
#   3. POSISI KHUSUS → id ada di tengah, bukan di ujung.
#   4. DEFAULT     → segmen angka TERAKHIR = pemilik.

# Callback tanpa ID di dalamnya → hanya owner yang boleh.
_CB_OWNER_ONLY = (
    'owner_add_admin_prompt', 'owner_add_user_prompt', 'owner_ban_user_prompt',
    'owner_broadcast_prompt', 'owner_del_admin_prompt', 'owner_list_users',
    'owner_menu', 'owner_smsaktif_status', 'owner_stats', 'owner_switch_list',
    'owner_toggle_mt', 'owner_unban_user_prompt', 'owner_unswitch',
    'owner_prem_menu', 'owner_prem_list', 'owner_prem_add_prompt',
    'owner_prem_del_prompt', 'owner_prem_invoices', 'owner_prem_balance',
    'unswitch_acc',
)
_CB_OWNER_ONLY_PREFIX = (
    'owner_', 'switch_to_',
)
# Callback publik tanpa pemilik (aman ditekan siapa pun).
_CB_FREE = ('noop',)
# Pemilik ada di indeks segmen tertentu (setelah prefix di-strip).
#   prefix → indeks segmen (0-based) yang berisi user_id
_CB_OWNER_AT = {
    'change_pick_': 0, 'fav_ix_': 0, 'listele_monitor_': 0,
    'listele_pick_': 0, 'listele_prompt_': 0, 'nk_refresh_': 0,
    'sms_hist_': 0, 'smsaktif_setfilter_': 0, 'universal_batch_exec_': 0,
    # Add range batch: uhttp_go_{uid}_{jumlah} / usock_go_{uid}_{jumlah}
    # / umix_go_{uid}_{jumlah} (gabungan http+socket)
    # → pemilik ada di segmen pertama, BUKAN angka terakhir (itu jumlah range).
    'uhttp_go_': 0, 'usock_go_': 0, 'umix_go_': 0,
    'wa_accswitch_': 0, 'wa_addmem_': 0, 'wa_buatgrup_': 0,
    'wa_cekbio_setw_': 0, 'wa_citer_': 0, 'wa_citerstop_': 0,
    'wa_delakun_': 0, 'wa_grup_': 0,
    'tele_ex_dest_': 0, 'tele_multi_dest_': 0, 'tele_kick_dest_': 0,
    'tele_rep_one_': 0, 'tele_rep_monzosel_': 0, 'tele_rep_monzoprev_': 0,
    # Limitin: limitin_run_{uid}_{method} / limitin_stop_{uid} / limitin_cancel_{uid}
    # → pemilik = segmen pertama setelah prefix (method bisa mengandung '_').
    'limitin_run_': 0, 'limitin_stop_': 0, 'limitin_cancel_': 0,
}
_CB_DIGITS = re.compile(r"^-?\d+$")


def _cb_owner_of(data: str):
    """Ambil user_id pemilik tombol dari callback_data.

    Return int (pemilik), 'OWNER' (khusus owner), atau None (bebas/tak diketahui).
    """
    if not data or data in _CB_FREE:
        return None
    if data in _CB_OWNER_ONLY or data.startswith(_CB_OWNER_ONLY_PREFIX):
        return 'OWNER'

    for pref, idx in _CB_OWNER_AT.items():
        if data.startswith(pref):
            segs = data[len(pref):].split('_')
            if len(segs) > idx and _CB_DIGITS.match(segs[idx]):
                return int(segs[idx])
            break

    # Pola pilih-sender: ..._pick_{user_id}_{sender_id} / ..._pri_{user_id}_{id}
    # → pemilik = segmen angka kedua dari belakang.
    if '_pick_' in data or '_pri_' in data:
        segs = data.split('_')
        if len(segs) >= 2 and _CB_DIGITS.match(segs[-2]):
            return int(segs[-2])

    # Default: segmen angka terakhir = pemilik.
    for seg in reversed(data.split('_')):
        if _CB_DIGITS.match(seg):
            return int(seg)
    return None


def _cb_ownership_ok(data: str, presser_id: int) -> bool:
    """False kalau `presser_id` menekan tombol milik user lain."""
    owner = _cb_owner_of(data)
    if owner is None:
        return True
    if owner == 'OWNER':
        return presser_id == USER_ID
    # Cocok persis. Owner pun tidak boleh menekan tombol user lain, karena
    # state (job/session) di-index per penekan → bisa salah sasaran.
    return owner == presser_id


async def menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler untuk semua callback"""
    query = update.callback_query
    data = query.data or ""
    user_id = update.effective_user.id

    # Answer callback ASAP untuk path yang berat (pipeline/DB) supaya tidak
    # timeout. Callback ringan tetap di-answer nanti dengan pesan spesifik.
    _HEAVY_CB_PREFIXES = ('fixserver_', 'fix_', 'fxinput_', 'fxshow_', 'fxdel_',
                          'fxprev_', 'resetotp_', 'ubot_')
    if any(data.startswith(p) for p in _HEAVY_CB_PREFIXES):
        try:
            await asyncio.wait_for(query.answer(), timeout=5)
        except Exception:
            pass

    # ── GATE KEPEMILIKAN INLINE (berlaku untuk SEMUA callback) ──────────
    # Tiap tombol menyimpan ID pemiliknya di dalam callback_data. User lain
    # yang menekan tombol milik orang lain ditolak di sini, sebelum handler
    # apa pun jalan (termasuk /tele, WA, dan owner console).
    if not _cb_ownership_ok(data, user_id):
        try:
            await query.answer("Tombol ini bukan untukmu.", show_alert=True)
        except Exception:
            pass
        return

    if data.startswith('onb_') or data.startswith('lastotp_menu_'):
        # Kepemilikan sudah divalidasi gate global di atas; sisa cek ini hanya
        # memastikan ID-nya benar-benar ada di ujung callback_data.
        try:
            owner_id = int(data.rsplit('_', 1)[-1])
        except Exception:
            owner_id = None
        if owner_id != user_id:
            await query.answer("Tombol ini bukan untukmu.")
            return

    if data.startswith('lastotp_menu_'):
        await query.answer()
        try:
            cur.execute(
                """SELECT phone, range_name, sender, otp_code, message_excerpt, received_time, created_at
                   FROM otp_events WHERE user_id = ? ORDER BY id DESC LIMIT 1""",
                (user_id,),
            )
            row = cur.fetchone()
        except Exception:
            row = None
        if not row:
            await query.edit_message_text(
                _plain_screen("LAST OTP", "<b>BELUM ADA OTP TERSIMPAN</b>\n\nAktifkan monitor dan tunggu SMS baru.", "Home › SMS › Last OTP"),
                parse_mode=ParseMode.HTML,
                reply_markup=get_sub_sms_keyboard(user_id),
            )
            return
        phone, range_name, sender, otp_code, excerpt, received_time, created_at = row
        table = _plain_table([
            ('Nomor', '+' + (phone or '-')),
            ('Pengirim', sender or '-'),
            ('Range', range_name or '-'),
            ('Waktu SMS', received_time or created_at or '-'),
        ])
        body = (
            "<b>OTP TERAKHIR</b>\n\n"
            f"<pre>{html.escape(table)}</pre>\n\n"
            f"<b>Kode:</b> <code>{html.escape(otp_code or '-')}</code>\n"
            f"<blockquote>{html.escape((excerpt or '-')[:500])}</blockquote>"
        )
        kb = []
        if otp_code:
            kb.append([InlineKeyboardButton(
                "SALIN KODE", copy_text=CopyTextButton(text=otp_code),
                api_kwargs={"style": "success"},
            )])
        kb.append([InlineKeyboardButton("KEMBALI", callback_data=f"sub_sms_{user_id}", style="danger")])
        await query.edit_message_text(
            _plain_screen("LAST OTP", body, "Home › SMS › Last OTP"),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(kb),
        )
        return

    if data.startswith('onb_start_'):
        await query.answer()
        logged_in = check_user_login(user_id)
        table = _plain_table([
            ('Langkah', '1 dari 3'),
            ('Login iVASMS', 'Sudah aktif' if logged_in else 'Belum aktif'),
            ('Tujuan', 'Hubungkan akun penerima SMS'),
        ])
        await query.edit_message_text(
            _plain_screen("PANDUAN AWAL", (
                "<b>HUBUNGKAN AKUN IVASMS</b>\n\n"
                f"<pre>{html.escape(table)}</pre>\n\n"
                "Kirim <code>/cookies &lt;isi cookies&gt;</code> untuk login. "
                "Jika sudah login, lanjut ke pengaturan monitor."
            ), "Home › Panduan › Login"),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("LANJUT", callback_data=f"onb_monitor_{user_id}", style="success")],
                [InlineKeyboardButton("LEWATI PANDUAN", callback_data=f"onb_done_{user_id}", style="danger")],
            ]),
        )
        return

    if data.startswith('onb_monitor_'):
        await query.answer()
        table = _plain_table([
            ('Langkah', '2 dari 3'),
            ('Monitor', 'Aktif' if user_id in active_notif_monitor else 'Mati'),
            ('Filter', get_user_prefs(user_id).get('monitor_app_filter', 'all')),
        ])
        await query.edit_message_text(
            _plain_screen("PANDUAN AWAL", (
                "<b>ATUR MONITOR SMS</b>\n\n"
                f"<pre>{html.escape(table)}</pre>\n\n"
                "Gunakan menu SMS untuk mengaktifkan monitor dan memilih filter aplikasi."
            ), "Home › Panduan › Monitor"),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("BUKA MENU SMS", callback_data=f"sub_sms_{user_id}", style="primary")],
                [InlineKeyboardButton("LANJUT", callback_data=f"onb_forwarder_{user_id}", style="success")],
            ]),
        )
        return

    if data.startswith('onb_forwarder_'):
        await query.answer()
        bot_token, _, bot_active, _ = get_user_bot_token(user_id)
        table = _plain_table([
            ('Langkah', '3 dari 3'),
            ('Forwarder', 'Aktif' if bot_token and bot_active else 'Opsional'),
            ('Fungsi', 'Kirim OTP ke bot pribadi'),
        ])
        await query.edit_message_text(
            _plain_screen("PANDUAN AWAL", (
                "<b>FORWARDER PRIBADI</b>\n\n"
                f"<pre>{html.escape(table)}</pre>\n\n"
                "Forwarder bersifat opsional dan bisa diatur kapan saja dari menu SMS AKTIF."
            ), "Home › Panduan › Forwarder"),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("BUKA SMS AKTIF", callback_data=f"smsaktif_menu_{user_id}", style="primary")],
                [InlineKeyboardButton("SELESAI", callback_data=f"onb_done_{user_id}", style="success")],
            ]),
        )
        return

    if data.startswith('onb_done_'):
        set_user_pref(user_id, onboarded=True)
        await query.answer("Panduan selesai.")
        await start_command(update, context)
        return

    # Auto-update username Telegram di DB
    update_user_username(update.effective_user)

    # ── Callback PUBLIK (selalu boleh ditekan, samakan dengan /fix yang public) ─
    # Bypass gate `is_allowed_user`. Tetap dipastikan hanya inisiator yang boleh
    # menekan tombolnya (callback_data sudah berisi `_{user_id}` di belakang).
    _public_prefixes = (
        'fix_confirm_', 'fix_cancel_',
        'create_confirm_', 'create_cancel_', 'create_sel_', 'create_api_',
        'proxy_socks5_', 'proxy_http_', 'proxy_cancel_', 'proxy_close_', 'proxy_again_',
        'fixmenu_', 'fix_back_',
        'fix_srv1_', 'fix_srv2_', 'fix_srv3_', 'fix_resetotp_',
        'form_otp_easy_', 'form_otp_hard_', 'form_otp_limauto_',
        'form_otp_limcustom_', 'form_otp_limdetect_', 'form_otp_proses_',
        'limitin_run_', 'limitin_stop_', 'limitin_cancel_',
        'prem_buy_', 'prem_check_', 'prem_cancel_', 'prem_menu_', 'prem_close_',
        'fxinput_', 'fxshow_', 'fxdel_',
        'fxdelall_', 'fxdels1_', 'fxdels2_', 'fxprev_',
        'tgcheck_confirm_', 'tgcheck_abort_', 'tgcheck_cancel_',
        'tgcheck_history_', 'tgcheck_clear_', 'tgcheck_export_',
        'tgcheck_detail_', 'tgcheck_login_', 'sender_checkall_', 'sender_deldead_', 'sender_delall_',
        'sessions_del_', 'sessions_delall_',
        'loginexp_sms_', 'loginexp_app_', 'loginexp_all_', 'loginexp_done_',
        'unban_send_', 'unban_cancel_',
        'gopay_srv1_', 'gopay_srv2_',
        'fb_s1_', 'fb_s2_', 'fb_s3_', 'fb_s3_skip_', 'fb_s3_cancel_',
        'am_cancel_', 'am_home_', 'am_input_', 'menu_am_',
        # Geser halaman menu utama: halaman 2 isinya fitur publik (FIX MERAH,
        # ALIGHT MOTION), jadi user non-allowed harus tetap bisa pindah halaman.
        'menu_page',
        # Tombol TELEGRAM → hub /tele. Dibiarkan publik supaya user non-allowed
        # dapat alert "belum terdaftar" (dari _is_authorized) alih-alih pesan
        # dashboard-nya dihapus senyap.
        'menu_tele_',
    )
    if data.startswith(_public_prefixes):
        # Kepemilikan sudah dijaga gate global di atas (_cb_ownership_ok).
        # Di sini cukup pastikan ID pemilik memang ada & cocok — pakai
        # _cb_owner_of (parser yang sama dengan gate global) supaya format
        # seperti limitin_run_{uid}_{method} tetap kebaca bener.
        # Kalau tidak bisa diparse, tolak (jangan fallback ke penekan).
        owner_id = _cb_owner_of(data)
        if owner_id is not None and owner_id != user_id:
            # User lain mencoba menekan tombol orang lain → tolak senyap
            try:
                await query.answer("Tombol ini bukan untukmu.", show_alert=False)
            except Exception:
                pass
            return
        # Lanjut ke handler di bawah (jangan return!) — fall-through.
    else:
        # Untuk callback non-publik, gate `is_allowed_user` tetap berlaku.
        if not is_allowed_user(user_id):
            await query.answer()
            try: await query.message.delete()
            except: pass
            return

    if data == 'noop':
        await query.answer()
        return

    # ── /am ALIGHT MOTION callbacks ──
    if data.startswith('am_cancel_'):
        await query.answer("Dibatalkan.")
        context.user_data.pop(f'am_waiting_email_{user_id}', None)
        context.user_data.pop(f'am_waiting_link_{user_id}', None)
        context.user_data.pop(f'am_prompt_msg_{user_id}', None)
        context.user_data.pop(f'am_cookie_{user_id}', None)
        try:
            await query.edit_message_text(
                _screen('ALIGHT MOTION PREMIUM', f"{em(AM_EM_FAIL,'❌')} <b>Dibatalkan.</b>"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    if data.startswith('am_home_'):
        await query.answer()
        context.user_data.pop(f'am_waiting_email_{user_id}', None)
        context.user_data.pop(f'am_waiting_link_{user_id}', None)
        context.user_data.pop(f'am_prompt_msg_{user_id}', None)
        try:
            await start_command(update, context)
        except Exception:
            pass
        return

    if data.startswith('menu_am_'):
        await query.answer()
        kb = InlineKeyboardMarkup([
            [InlineKeyboardButton("MASUKKAN EMAIL", callback_data=f"am_input_{user_id}", style="success")],
            [InlineKeyboardButton("KEMBALI", callback_data=f"am_home_{user_id}", style="danger")],
        ])
        try:
            await query.edit_message_text(_am_usage_screen(),
                                          parse_mode=ParseMode.HTML, reply_markup=kb)
        except Exception:
            pass
        return

    if data.startswith('am_input_'):
        await query.answer()
        context.user_data.pop(f'am_waiting_link_{user_id}', None)
        context.user_data[f'am_waiting_email_{user_id}'] = True
        try:
            await query.edit_message_text(
                _screen('ALIGHT MOTION PREMIUM', (
                    f"{em(AM_EM_EMAIL,'✉️')} <b>Kirim email akun Alight Motion kamu.</b>\n\n"
                    f"Contoh: <code>nama@gmail.com</code>\n\n"
                    f"{em(AM_EM_INFO,'ℹ️')} Bot akan mengirim link login premium ke email itu, "
                    f"lalu kamu tinggal balas dengan <b>Link Verifikasi</b>-nya."
                )),
                parse_mode=ParseMode.HTML,
                reply_markup=_am_cancel_kb(user_id),
            )
            # Simpan id prompt email biar bisa dihapus otomatis setelah
            # user mengirim emailnya.
            context.user_data[f'am_prompt_msg_{user_id}'] = query.message.message_id
        except Exception:
            pass
        return

    # ── /tele hub callbacks ──
    if _TELE_OK and data.startswith('tele_'):
        handled = await _tele_callback(update, context)
        if handled:
            return

    # ── CHANGE NUMBER callbacks ──
    if data.startswith('change_cancel_'):
        await query.answer("Dibatalkan.")
        context.user_data.pop(f"change_numbers_{user_id}", None)
        _change_jobs.pop(user_id, None)
        try:
            await query.edit_message_text(
                _screen("CHANGE NUMBER", f"{em(E2,'❌')} <b>Dibatalkan.</b>", "Home › Telegram › Change Number"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    if data.startswith('change_pick_'):
        sid = int(data.split('_')[-1])
        numbers = context.user_data.get(f"change_numbers_{user_id}") or []
        if not numbers:
            await query.answer("Data nomor hilang. Kirim /change lagi.", show_alert=True)
            return
        cur.execute(
            "SELECT id, phone, name, string_session FROM tgcheck_pool WHERE id=? AND user_id=?",
            (sid, user_id),
        )
        row = cur.fetchone()
        if not row or not row[3]:
            await query.answer("Sender tidak ditemukan / bukan milik kamu.", show_alert=True)
            return
        sender_id, sender_phone, sender_name, session_str = row
        context.user_data.pop(f"change_numbers_{user_id}", None)
        job = {
            "user_id": user_id,
            "sender_id": sender_id,
            "sender_phone": sender_phone,
            "sender_name": sender_name or sender_phone,
            "session": session_str,
            "chat_id": query.message.chat_id,
            "message_id": query.message.message_id,
            "targets": {n: {"status": "queued", "detail": "Antri worker"} for n in numbers},
        }
        _change_jobs[user_id] = job
        await query.answer("Memulai change number...")
        await _change_edit_status(context.bot, job)
        asyncio.create_task(_change_run_workers(job, context.bot))
        return

    # ── WhatsApp callbacks (cekbio_start/abort/cancel + wa_*) ──
    if _WA_OK and (data.startswith('wa_') or data.startswith('cekbio_')):
        handled = await _wa_callback(update, context)
        if handled:
            return

    # ── Listele callbacks ──
    if data.startswith('listele_cancel_'):
        await query.answer("Dibatalkan.")
        context.user_data.pop("listele_awaiting_start_link", None)
        # Stop any active monitor
        if user_id in _listele_monitor:
            task = _listele_monitor[user_id].get("task")
            if task and not task.done():
                task.cancel()
            del _listele_monitor[user_id]
        try:
            await query.edit_message_text(
                text=_screen('LIST TELEGRAM', f"{em(E2,'❌')} <b>Dibatalkan.</b>", 'Home › Telegram › List Sender'),
                parse_mode=ParseMode.HTML)
        except: pass
        return

    if data.startswith('listele_pick_'):
        parts = data.split('_')
        sid = int(parts[-1])
        await query.answer()
        cur.execute(
            "SELECT phone, name, status, flood_until, last_used FROM tgcheck_pool WHERE id=?",
            (sid,),
        )
        row = cur.fetchone()
        if not row:
            await query.answer("Sender tidak ditemukan.")
            return
        phone, name, status, flood_until, last_used = row
        now = int(time.time())
        if status == "dead":
            status_text = "Dead"
        elif (flood_until or 0) > now:
            status_text = f"Flood {max(1, ((flood_until or 0) - now) // 60)} menit"
        else:
            status_text = "Siap"
        sender_table = _plain_table([
            ("Nama", name or "-"),
            ("Nomor", "+" + str(phone)),
            ("Status", status_text),
            ("Terakhir", datetime.fromtimestamp(last_used).strftime("%d/%m/%Y %H:%M") if last_used else "-"),
        ])
        keyboard = InlineKeyboardMarkup([
            [
                InlineKeyboardButton("MONITOR", callback_data=f"listele_monitor_{user_id}_{sid}", style="primary"),
                InlineKeyboardButton("START BOT", callback_data=f"listele_prompt_{user_id}_{sid}", style="success"),
            ],
            [InlineKeyboardButton("BATAL", callback_data=f"listele_cancel_{user_id}", style="danger")],
        ])
        await query.edit_message_text(
            _plain_screen(
                "DETAIL SENDER",
                f"<pre>{html.escape(sender_table)}</pre>\n"
                "<blockquote>Pilih tindakan untuk sender ini.</blockquote>",
                "Home › Telegram › Sender",
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=keyboard,
        )
        return

    if data.startswith('listele_prompt_'):
        sid = int(data.split('_')[-1])
        cur.execute("SELECT phone, name FROM tgcheck_pool WHERE id=?", (sid,))
        row = cur.fetchone()
        if not row:
            await query.answer("Sender tidak ditemukan.", show_alert=True)
            return
        phone, name = row
        context.user_data["listele_awaiting_start_link"] = {
            "sid": sid,
            "message_id": query.message.message_id,
        }
        await query.answer()
        await query.edit_message_text(
            _plain_screen(
                "START BOT",
                f"<b>SENDER DIPILIH</b>\n\n"
                f"<pre>{html.escape(_plain_table([('Nama', name or '-'), ('Nomor', '+' + str(phone))]))}</pre>\n"
                "<blockquote>Kirim deep link bot di chat ini.</blockquote>\n"
                "<b>Contoh:</b>\n"
                "<code>https://t.me/FreeModelDevBot?start=JnmjUOKu8bYd</code>\n\n"
                "<i>Ketik BATAL untuk membatalkan.</i>",
                "Home › Telegram › Start Bot",
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("BATAL", callback_data=f"listele_cancel_{user_id}", style="danger"),
            ]]),
        )
        return

    if data.startswith('listele_monitor_'):
        parts = data.split('_')
        sid = int(parts[-1])
        await query.answer()

        # Get sender info from DB
        cur.execute("SELECT phone, name, string_session FROM tgcheck_pool WHERE id=?", (sid,))
        row = cur.fetchone()
        if not row:
            await query.answer("Sender tidak ditemukan.")
            return
        phone, name, session_str = row

        # Edit message to show monitoring state
        stop_kb = InlineKeyboardMarkup([[InlineKeyboardButton("Stop Monitor", callback_data=f"listele_cancel_{user_id}", style="danger")]])
        try:
            await query.edit_message_text(
                text=_screen('LIST TELEGRAM', (
                    f"{em(CE_LIVE,'📡')} <b>MONITOR AKTIF</b>\n\n"
                    f"  {em(CE_NOMOR,'📞')} Sender: <code>+{phone}</code>\n"
                    f"  {em(CE_AKUN,'👤')} Nama: {name or phone}\n\n"
                    f"  {em(CE_LOADING,'🔄')} <i>Menunggu pesan masuk...</i>\n"
                    f"  <i>Semua pesan baru akan diteruskan ke kamu.</i>"
                ), 'Home › Telegram › Monitor'),
                parse_mode=ParseMode.HTML,
                reply_markup=stop_kb)
        except: pass

        # Start monitoring task
        async def _monitor_sender():
            from telethon import TelegramClient
            from telethon.sessions import StringSession
            from telethon.events import NewMessage
            import html as _html
            client = TelegramClient(StringSession(session_str), TG_API_ID, TG_API_HASH)
            try:
                await client.connect()
                if not await client.is_user_authorized():
                    await context.bot.send_message(chat_id=query.message.chat_id,
                        text=f"{em(E2,'❌')} Sender +{phone} session expired.", parse_mode=ParseMode.HTML)
                    return

                # ── Register event handler BEFORE starting updates ──
                @client.on(NewMessage())
                async def handler(event):
                    msg_text = event.message.message or "[media]"
                    sender_info = await event.get_sender()
                    sender_name = getattr(sender_info, 'first_name', '') or str(getattr(sender_info, 'id', '?'))
                    chat = await event.get_chat()
                    chat_title = getattr(chat, 'title', '') or getattr(chat, 'first_name', '') or str(getattr(chat, 'id', '?'))
                    fwd_text = _screen('PESAN BARU', (
                        f"{em(CE_LIVE,'📡')} <b>Pesan Baru</b>\n\n"
                        f"  {em(CE_NOMOR,'📞')} Sender: <code>+{phone}</code>\n"
                        f"  {em(CE_AKUN,'👤')} Dari: {_html.escape(sender_name)}\n"
                        f"  💬 Chat: {_html.escape(str(chat_title))}\n\n"
                        f"<code>{_html.escape(msg_text[:3000])}</code>"
                    ))
                    try:
                        await context.bot.send_message(chat_id=query.message.chat_id,
                            text=fwd_text, parse_mode=ParseMode.HTML)
                    except: pass

                # ── Ambil pesan terbaru (history) ──
                try:
                    dialogs = await client.get_dialogs(limit=5)
                    for dialog in dialogs:
                        if user_id not in _listele_monitor:
                            break
                        try:
                            messages = await client.get_messages(dialog.entity, limit=3)
                            for msg in reversed(messages):
                                if not msg or not msg.message:
                                    continue
                                sender_info = await msg.get_sender()
                                sender_name = getattr(sender_info, 'first_name', '') or str(getattr(sender_info, 'id', '?'))
                                chat_title = getattr(dialog, 'title', '') or getattr(dialog, 'name', '') or str(dialog.id)
                                fwd_text = _screen('PESAN (HISTORY)', (
                                    f"{em(CE_LIVE,'📡')} <b>Pesan (History)</b>\n\n"
                                    f"  {em(CE_NOMOR,'📞')} Sender: <code>+{phone}</code>\n"
                                    f"  {em(CE_AKUN,'👤')} Dari: {_html.escape(sender_name)}\n"
                                    f"  💬 Chat: {_html.escape(str(chat_title))}\n\n"
                                    f"<code>{_html.escape(msg.message[:3000])}</code>"
                                ))
                                try:
                                    await context.bot.send_message(chat_id=query.message.chat_id,
                                        text=fwd_text, parse_mode=ParseMode.HTML)
                                except: pass
                                await asyncio.sleep(0.3)
                        except Exception:
                            continue
                except Exception as e:
                    try:
                        await context.bot.send_message(chat_id=query.message.chat_id,
                            text=f"⚠️ Gagal ambil history: {str(e)[:100]}", parse_mode=ParseMode.HTML)
                    except: pass

                # ── Start update loop (THIS is what makes events fire) ──
                # run_until_disconnected starts internal update dispatcher
                run_task = asyncio.create_task(client.run_until_disconnected())

                # Wait until cancelled or monitor removed
                while user_id in _listele_monitor:
                    await asyncio.sleep(1)

                # Stop: disconnect triggers run_until_disconnected to end
                await client.disconnect()
                try:
                    await run_task
                except: pass
                return
            except asyncio.CancelledError:
                pass
            except Exception as e:
                try:
                    await context.bot.send_message(chat_id=query.message.chat_id,
                        text=f"{em(E2,'❌')} Monitor error: {str(e)[:100]}", parse_mode=ParseMode.HTML)
                except: pass
            finally:
                try:
                    await client.disconnect()
                except: pass

        # Cancel previous monitor if exists
        if user_id in _listele_monitor:
            old_task = _listele_monitor[user_id].get("task")
            if old_task and not old_task.done():
                old_task.cancel()

        task = asyncio.create_task(_monitor_sender())
        _listele_monitor[user_id] = {"phone": phone, "task": task}
        return

