    # === MAIL callbacks ===
    if data.startswith('mail_cancel_'):
        uid = int(data.split('_')[-1])
        if query.from_user.id != uid:
            await query.answer("⛔ Bukan milikmu", show_alert=True)
            return
        await query.answer("Dibatalkan")
        old = _mail_sessions.pop(uid, None)
        if old:
            if old.get("task") and not old["task"].done():
                old["task"].cancel()
            # Close HTTP session (after pop so concurrent handlers see empty session)
            try:
                await _mail_mod.close_session(old.get("session"))
            except Exception:
                pass
        await query.message.edit_text(
            _screen('MAIL', f"{EMOJI['WARNING']} Monitoring dibatalkan.", 'Home › Mail'),
            parse_mode=ParseMode.HTML, reply_markup=None)
        return

    if data.startswith('mail_refresh_'):
        uid = int(data.split('_')[-1])
        if query.from_user.id != uid:
            await query.answer("⛔ Bukan milikmu", show_alert=True)
            return
        await query.answer("🔄 Refreshing...")
        if uid not in _mail_sessions:
            await query.answer("❌ Session expired, pakai /mail lagi", show_alert=True)
            return
        sess_data = _mail_sessions[uid]
        session = sess_data["session"]
        try:
            msgs = await poll_once(session)
        except Exception:
            msgs = []
        if msgs:
            # Email arrived — show new result (this is the ONLY edit case)
            await _mail_show_result(uid, session, msgs, sess_data.get("msg"), sess_data.get("chat_id"), context)
        else:
            # No emails — silent toast, don't touch message
            await query.answer("📭 Belum ada email masuk", show_alert=True)
        return

    if data.startswith('mail_new_'):
        uid = int(data.split('_')[-1])
        if query.from_user.id != uid:
            await query.answer("⛔ Bukan milikmu", show_alert=True)
            return
        await query.answer("🔄 Membuat email baru...")
        # Cleanup old session
        if uid in _mail_sessions:
            old = _mail_sessions[uid]
            if old.get("task") and not old["task"].done():
                old["task"].cancel()
            await _mail_mod.close_session(old.get("session"))
            del _mail_sessions[uid]
        # Edit current message to placeholder
        try:
            await query.message.edit_text(
                _screen('MAIL',
                    f"{em(CE_LOADING, '⏳')} <b>Membuat temp Gmail baru...</b>\n"
                    f"<i>Tunggu sebentar (2-5 detik)...</i>",
                    'Home › Mail'),
                parse_mode=ParseMode.HTML, reply_markup=None)
        except Exception:
            pass
        try:
            session = await create_temp_gmail()
        except Exception as e:
            try:
                await query.message.edit_text(
                    _screen('MAIL', f"{EMOJI['FAILED']} Gagal buat email: {e}"),
                    parse_mode=ParseMode.HTML)
            except Exception:
                pass
            return
        body = _mail_waiting_body(session)
        kb = _mail_waiting_kb(uid, session.email)
        try:
            await query.message.edit_text(
                _screen('MAIL', body, 'Home › Mail'),
                parse_mode=ParseMode.HTML,
                reply_markup=kb)
        except Exception:
            pass
        task = asyncio.create_task(_mail_poll_task(uid, session, query.message, query.message.chat_id, context))
        _mail_sessions[uid] = {"session": session, "task": task, "msg": query.message, "chat_id": query.message.chat_id}
        return

