    # ── LIMITIN: mulai run method ──
    if data.startswith('limitin_run_'):
        # limitin_run_{user_id}_{method}
        parts = data.split('_')
        if len(parts) < 4:
            await query.answer("Callback rusak.", show_alert=True)
            return
        try:
            target_uid = int(parts[2])
        except ValueError:
            await query.answer("Callback rusak.", show_alert=True)
            return
        if target_uid != user_id:
            await query.answer("Tombol ini bukan untukmu.", show_alert=True)
            return
        method = '_'.join(parts[3:]) or 'wa_old'
        if method not in ("wa_old", "sms", "voice"):
            method = "wa_old"
