# ═══════════════════════════════════════
_listele_monitor = {}  # user_id -> {phone, task}

async def listele_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/listele — pilih sender, lalu monitor atau jalankan deep link bot."""
    user_id = update.effective_user.id
    if user_id != USER_ID:
        return

    context.user_data.pop("listele_awaiting_start_link", None)

    cur.execute("SELECT id, user_id, phone, name, status, flood_until, last_used FROM tgcheck_pool ORDER BY id")
    senders = cur.fetchall()

    if not senders:
        await update.message.reply_text(
            _screen('LIST TELEGRAM', (
                f"{em(E2,'❌')} <b>Tidak ada sender Telegram.</b>\n"
                f"────────────────────────────\n"
                f"<i>Tambah dengan /addsender</i>"
            ), 'Home › Telegram › List Sender'),
            parse_mode=ParseMode.HTML)
        return

    now = int(time.time())
    active_count = sum(1 for s in senders if s[4] == 'active' and (s[5] or 0) <= now)
    flood_count = sum(1 for s in senders if s[4] == 'active' and (s[5] or 0) > now)
    dead_count = sum(1 for s in senders if s[4] == 'dead')

    body = (
        f"{em(CE_TELEGRAM,'💬')} <b>LIST SENDER TELEGRAM</b>\n"
        f"────────────────────────────\n\n"
        f"  {em(CE_AKUN,'👥')} <b>Total:</b> {len(senders)}\n"
        f"  {em(E1,'✅')} Siap: <b>{active_count}</b>\n"
        f"  {em(CE_LOADING,'🔄')} Flood: <b>{flood_count}</b>\n"
        f"  {em(E2,'❌')} Dead: <b>{dead_count}</b>\n\n"
    )

    detail_lines = []
    for i, (sid, s_uid, phone, name, status, flood_until, last_used) in enumerate(senders):
        flood_until = flood_until or 0
        last_used = last_used or 0
        display_name = name or "-"

        # Flood status
        if status == 'dead':
            flood_str = f"{em(E2,'❌')} Dead"
        elif flood_until > now:
            remaining = flood_until - now
            if remaining > 86400:
                flood_str = f"{em(CE_LOADING,'🔄')} Flood {remaining // 86400}d"
            elif remaining > 3600:
                flood_str = f"{em(CE_LOADING,'🔄')} Flood {remaining // 3600}h"
            else:
                flood_str = f"{em(CE_LOADING,'🔄')} Flood {remaining // 60}m"
        else:
            flood_str = f"{em(E1,'✅')} Siap menerima kode"

        # Last active
        if last_used > 0:
            from datetime import datetime as dt
            last_dt = dt.fromtimestamp(last_used)
            diff = now - last_used
            if diff < 300:
                active_str = "Aktif sekarang"
            else:
                active_str = last_dt.strftime("%d/%m/%Y %H:%M")
        else:
            active_str = "-"

        detail_lines.append(
            f"  {i+1}. <code>+{phone}</code> — {display_name}\n"
            f"     {flood_str}\n"
            f"     {em(CE_WAKTU,'⏲')} {active_str}"
        )

    # Pilih sender lebih dulu; menu tindakan ditampilkan setelahnya.
    kb = []
    row = []
    for i, (sid, *_) in enumerate(senders):
        row.append(InlineKeyboardButton(
            str(i + 1),
            callback_data=f"listele_pick_{user_id}_{sid}",
            style="primary",
        ))
        if len(row) == 4:
            kb.append(row)
            row = []
    if row:
        kb.append(row)
    kb.append([InlineKeyboardButton("Batal", callback_data=f"listele_cancel_{user_id}", style="danger")])

    # If too many senders, send detail as file first
    if len(senders) > 10:
        import io
        txt_lines = [f"LIST SENDER TELEGRAM — {len(senders)} total\n"]
        txt_lines.append(f"Siap: {active_count} | Flood: {flood_count} | Dead: {dead_count}\n")
        txt_lines.append("─" * 40)
        for i, (sid, s_uid, phone, name, status, flood_until, last_used) in enumerate(senders):
            flood_until = flood_until or 0
            last_used = last_used or 0
            if status == 'dead':
                fs = "DEAD"
            elif flood_until > now:
                r = flood_until - now
                fs = f"Flood {r//3600}h {(r%3600)//60}m" if r > 3600 else f"Flood {r//60}m"
            else:
                fs = "Siap menerima kode"
            from datetime import datetime as dt
            act = dt.fromtimestamp(last_used).strftime("%d/%m/%Y %H:%M") if last_used > 0 else "-"
            if last_used > 0 and (now - last_used) < 300:
                act = "Aktif sekarang"
            txt_lines.append(f"\n  {i+1}. +{phone} — {name or '-'}")
            txt_lines.append(f"     Status: {fs}")
            txt_lines.append(f"     Terakhir: {act}")
        buf = io.BytesIO("\n".join(txt_lines).encode("utf-8"))
        buf.name = f"listele_{len(senders)}.txt"
        await update.message.reply_document(
            document=buf,
            caption=f"<blockquote>{em(CE_HELP,'💡')} Detail {len(senders)} sender (lihat file)</blockquote>",
            parse_mode=ParseMode.HTML)

    # Send main message with inline buttons
    if len(senders) <= 10:
        body += "\n".join(detail_lines)

    body += (
        f"\n\n────────────────────────────\n"
        f"{em(CE_HELP,'💡')} <i>Pilih akun, lalu pilih Monitor atau Start Bot.</i>"
    )
    await update.message.reply_text(
        _screen('LIST TELEGRAM', body, 'Home › Telegram › List Sender'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(kb))


