CHANGE_WORKERS = 5
CHANGE_STAGGER_SEC = 1.25
CHANGE_MAX_NUMBERS = 10
_change_jobs = {}  # user_id -> job dict


def _change_code_label(raw_type: str) -> str:
    """Convert SentCodeType class name to human-readable label."""
    _map = {
        "SentCodeTypeSms": "SMS",
        "SentCodeTypeApp": "Telegram App",
        "SentCodeTypeCall": "Telepon",
        "SentCodeTypeMissedCall": "Missed Call",
        "SentCodeTypeFlashCall": "Flash Call",
        "SentCodeTypeFragmentSms": "Fragment SMS",
        "SentCodeTypeEmailCode": "Email",
        "SentCodeTypeFirebaseSms": "Firebase SMS",
        "SentCodeTypeSetUpEmailRequired": "Email Setup Required",
        "CodeTypeSms": "SMS",
        "CodeTypeCall": "Telepon",
        "CodeTypeMissedCall": "Missed Call",
        "CodeTypeFlashCall": "Flash Call",
        "CodeTypeFragmentSms": "Fragment SMS",
    }
    return _map.get(raw_type, raw_type)


def _change_normalize_numbers(raw_lines):
    out = []
    seen = set()
    for line in raw_lines:
        for part in re.split(r"[\s,;]+", str(line or "").strip()):
            phone = _tgcheck_normalize_phone(part)
            if phone and len(phone) >= 8 and phone not in seen:
                seen.add(phone)
                out.append(phone)
    return out


def _change_pick_limited(numbers, *, randomize=False):
    """Ambil maksimal CHANGE_MAX_NUMBERS nomor."""
    clean = list(numbers or [])
    if len(clean) <= CHANGE_MAX_NUMBERS:
        return clean, 0
    if randomize:
        return random.sample(clean, CHANGE_MAX_NUMBERS), len(clean) - CHANGE_MAX_NUMBERS
    return clean[:CHANGE_MAX_NUMBERS], len(clean) - CHANGE_MAX_NUMBERS


def _change_render_progress(job, *, final=False):
    targets = job.get("targets") or {}
    waiting = [p for p, t in targets.items() if t.get("status") == "waiting_otp"]
    success = [p for p, t in targets.items() if t.get("status") == "success"]
    occupied = [p for p, t in targets.items() if t.get("status") == "occupied"]
    fail = [
        p for p, t in targets.items()
        if t.get("status") in {"error", "banned", "flood", "fresh", "invalid", "cancelled"}
    ]
    title = "HASIL CHANGE NUMBER" if final else "GANTI NOMOR SENDER"

    detail_lines = []
    for phone, item in list(targets.items())[:CHANGE_MAX_NUMBERS]:
        st = item.get("status", "-")
        detail = item.get("detail") or item.get("code_type") or "-"
        detail_lines.append(
            f"  <code>+{phone}</code> · <b>{html.escape(str(st).upper())}</b> · {html.escape(str(detail)[:60])}"
        )

    if final and not waiting:
        # Semua gagal / sudah terdaftar → jangan minta OTP
        occupied_lines = "\n".join(f"  {em(E2,'❌')} <code>+{p}</code>" for p in occupied) or "  -"
        footer = (
            f"\n\n{em(E3,'⚠️')} <b>Tidak ada OTP yang terkirim.</b>\n"
            f"Nomor target sudah terdaftar di Telegram / tidak bisa diganti ke nomor itu.\n\n"
            f"<b>Nomor terdaftar:</b>\n{occupied_lines}"
        )
        if fail:
            footer += f"\n\n{em(CE_LOADING,'🔄')} Status lain gagal: <b>{len(fail)}</b>"
    elif final and waiting:
        otp_block = "\n".join(
            f"  {em(E1,'✅')} <code>+{p}</code> · {html.escape(str((targets[p].get('code_type') or 'OTP')))}"
            for p in waiting
        )
        footer = (
            f"\n\n{em(E1,'✅')} <b>OTP berhasil dikirim ke {len(waiting)} nomor:</b>\n"
            f"{otp_block}\n\n"
            f"{em(CE_LOGIN,'🔑')} Kirim kode:\n"
            f"<code>6012:62542</code>"
        )
    else:
        footer = (
            f"\n\n{em(CE_HELP,'💡')} Menunggu hasil kirim OTP..."
        )

    return _screen("CHANGE NUMBER", (
        f"{em(CE_TELEGRAM,'💬')} <b>{title}</b>\n"
        f"────────────────────────────\n\n"
        f"  {em(CE_AKUN,'👤')} Sender: <code>+{html.escape(job.get('sender_phone') or '-')}</code>\n"
        f"  {em(CE_NOMOR,'📞')} Diproses: <b>{len(targets)}/{CHANGE_MAX_NUMBERS}</b>\n"
        f"  {em(CE_LOADING,'🔄')} OTP terkirim: <b>{len(waiting)}</b>\n"
        f"  {em(E1,'✅')} Nomor diganti: <b>{len(success)}</b>\n"
        f"  {em(E2,'❌')} Terdaftar/gagal: <b>{len(occupied) + len(fail)}</b>\n"
        f"  {em(E6,'🚀')} Workers: <b>{CHANGE_WORKERS}</b>\n\n"
        f"<b>Detail:</b>\n"
        + ("\n".join(detail_lines) if detail_lines else "  -")
        + footer
    ), "Home › Telegram › Change Number")


async def _change_edit_status(bot, job, *, final=False):
    waiting = [
        p for p, t in (job.get("targets") or {}).items()
        if t.get("status") == "waiting_otp"
    ]
    markup = None
    if not final or waiting:
        markup = InlineKeyboardMarkup([[
            InlineKeyboardButton("BATAL", callback_data=f"change_cancel_{job['user_id']}", style="danger"),
        ]])
    try:
        await bot.edit_message_text(
            chat_id=job["chat_id"],
            message_id=job["message_id"],
            text=_change_render_progress(job, final=final),
            parse_mode=ParseMode.HTML,
            reply_markup=markup,
        )
    except Exception:
        pass


async def _change_send_one(job, phone, sem, bot):
    """Kirim OTP change-phone ke satu nomor target."""
    async with sem:
        await asyncio.sleep(CHANGE_STAGGER_SEC)
        item = job["targets"].setdefault(phone, {"status": "pending"})
        client = None
        try:
            if not TELETHON_OK:
                raise RuntimeError("Telethon tidak tersedia")
            client = TelegramClient(StringSession(job["session"]), TG_API_ID, TG_API_HASH)
            await asyncio.wait_for(client.connect(), timeout=20)
            if not await client.is_user_authorized():
                raise RuntimeError("Session sender expired")

            for attempt in range(3):
                try:
                    sent = await asyncio.wait_for(
                        client(SendChangePhoneCodeRequest(
                            phone_number="+" + phone,
                            settings=CodeSettings(
                                allow_flashcall=False,
                                current_number=False,
                                allow_app_hash=False,
                                allow_missed_call=False,
                            ),
                        )),
                        timeout=35,
                    )
                    code_type_raw = type(getattr(sent, "type", None)).__name__ if getattr(sent, "type", None) else "Unknown"
                    code_label = _change_code_label(code_type_raw)
                    next_raw = type(getattr(sent, "next_type", None)).__name__ if getattr(sent, "next_type", None) else ""
                    next_label = _change_code_label(next_raw) if next_raw and next_raw != "NoneType" else ""
                    detail_str = f"OTP via {code_label}"
                    if next_label:
                        detail_str += f" (next: {next_label})"
                    item.update({
                        "status": "waiting_otp",
                        "hash": sent.phone_code_hash,
                        "code_type": code_label,
                        "detail": detail_str,
                        "sent_at": time.time(),
                    })
                    break
                except FloodWaitError as fw:
                    wait_s = int(getattr(fw, "seconds", 5) or 5)
                    item.update({"status": "flood", "detail": f"FloodWait {wait_s}s (retry)"})
                    await _change_edit_status(bot, job)
                    await asyncio.sleep(min(wait_s, 45) + 1)
                    if attempt == 2:
                        item.update({"status": "flood", "detail": f"FloodWait {wait_s}s"})
                except FreshChangePhoneForbiddenError:
                    item.update({"status": "fresh", "detail": "Sender baru login (<24 jam)"})
                    break
                except PhoneNumberOccupiedError:
                    item.update({"status": "occupied", "detail": "Nomor sudah terdaftar"})
                    break
                except PhoneNumberBannedError:
                    item.update({"status": "banned", "detail": "Nomor di-ban Telegram"})
                    break
                except PhoneNumberInvalidError:
                    item.update({"status": "invalid", "detail": "Format nomor invalid"})
                    break
                except PhoneNumberFloodError:
                    item.update({"status": "flood", "detail": "Nomor kena flood OTP"})
                    break
        except Exception as exc:
            item.update({"status": "error", "detail": str(exc)[:160]})
        finally:
            if client:
                try:
                    await client.disconnect()
                except Exception:
                    pass
            await _change_edit_status(bot, job)


async def _change_run_workers(job, bot):
    phones = list(job.get("targets") or {})
    sem = asyncio.Semaphore(CHANGE_WORKERS)
    await asyncio.gather(*[_change_send_one(job, p, sem, bot) for p in phones])
    await _change_edit_status(bot, job, final=True)
    # Kalau tidak ada OTP menunggu, bersihkan job supaya tidak minta kode lagi.
    waiting = [
        p for p, t in (job.get("targets") or {}).items()
        if t.get("status") == "waiting_otp"
    ]
    if not waiting:
        _change_jobs.pop(job.get("user_id"), None)


async def change_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/change <nomor...> | reply .txt — ganti nomor akun sender Telegram (max 10)."""
    user_id = update.effective_user.id
    if not is_allowed_user(user_id):
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} Kamu belum terdaftar. Hubungi owner."),
            parse_mode=ParseMode.HTML,
        )
        return
    if not TELETHON_OK:
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} Telethon belum tersedia."),
            parse_mode=ParseMode.HTML,
        )
        return

    from_file = False
    file_total = 0
    raw = " ".join(context.args) if context.args else ""
    reply = update.message.reply_to_message

    # Reply file .txt → ambil semua nomor, lalu random max 10
    if reply and reply.document and (reply.document.file_name or "").lower().endswith(".txt"):
        try:
            tg_file = await context.bot.get_file(reply.document.file_id)
            content = (await tg_file.download_as_bytearray()).decode("utf-8", errors="ignore")
            numbers = _change_normalize_numbers(content.splitlines())
            file_total = len(numbers)
            from_file = True
        except Exception as exc:
            await update.message.reply_text(
                _screen("CHANGE NUMBER", f"{em(E2,'❌')} Gagal baca file: <code>{html.escape(str(exc)[:120])}</code>"),
                parse_mode=ParseMode.HTML,
            )
            return
    else:
        if reply and reply.text:
            raw = (raw + "\n" + reply.text).strip()
        numbers = _change_normalize_numbers(raw.splitlines() if raw else [])

    if not numbers:
        await update.message.reply_text(
            _screen("CHANGE NUMBER", (
                f"{em(CE_TELEGRAM,'💬')} <b>GANTI NOMOR SENDER</b>\n"
                f"────────────────────────────\n\n"
                f"Ganti nomor akun sender lewat fitur Telegram Replace Number.\n\n"
                f"<b>{em(CE_HELP,'📖')} Cara pakai:</b>\n"
                f"  • <code>/change 6285825306012</code>\n"
                f"  • <code>/change 628xxx 628yyy</code>\n"
                f"  • Reply file <code>.txt</code> lalu <code>/change</code>\n\n"
                f"<b>{em(CE_NOMOR,'📞')} Limit:</b> maksimal <b>{CHANGE_MAX_NUMBERS}</b> nomor\n"
                f"<i>Reply .txt = random {CHANGE_MAX_NUMBERS} nomor dari file</i>\n\n"
                f"<b>{em(CE_LOGIN,'🔑')} OTP:</b>\n"
                f"  <code>6012:62542</code>\n"
                f"  <i>3-4 digit terakhir nomor : kode OTP</i>\n\n"
                f"<b>{em(E6,'🚀')} Engine:</b>\n"
                f"  • Workers paralel: <b>{CHANGE_WORKERS}</b>\n"
                f"  • Anti flood: stagger + FloodWait retry\n"
                f"  • Pilih sender dulu (inline)\n\n"
                f"{em(E3,'⚠️')} <i>Sender yang baru login harus tunggu ±24 jam.</i>"
            ), "Home › Telegram › Change Number"),
            parse_mode=ParseMode.HTML,
        )
        return

    numbers, skipped = _change_pick_limited(numbers, randomize=from_file)
    if not numbers:
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} Tidak ada nomor valid."),
            parse_mode=ParseMode.HTML,
        )
        return

    # Hanya sender milik user sendiri (bukan sender user lain).
    cur.execute(
        "SELECT id, phone, name, status, string_session FROM tgcheck_pool "
        "WHERE user_id=? AND status != 'dead' ORDER BY id",
        (user_id,),
    )
    senders = cur.fetchall()
    if not senders:
        await update.message.reply_text(
            _screen("CHANGE NUMBER", (
                f"{em(E2,'❌')} <b>Belum ada sender aktif milik kamu.</b>\n\n"
                f"Tambah dulu dengan <code>/addsender 628xxx</code>."
            ), "Home › Telegram › Change Number"),
            parse_mode=ParseMode.HTML,
        )
        return

    context.user_data[f"change_numbers_{user_id}"] = numbers
    preview = "\n".join(f"  {em(CE_NOMOR,'📞')} <code>+{n}</code>" for n in numbers)
    source_line = ""
    if from_file:
        source_line = (
            f"  {em(CE_FILE,'📁')} File: <b>{file_total}</b> nomor → random <b>{len(numbers)}</b>\n"
        )
    elif skipped:
        source_line = (
            f"  {em(E3,'⚠️')} Dipotong ke limit <b>{CHANGE_MAX_NUMBERS}</b> "
            f"(+{skipped} tidak diproses)\n"
        )

    kb = []
    row = []
    for i, (sid, phone, name, status, _sess) in enumerate(senders[:24], 1):
        label = f"{i}. +{phone}"
        if name:
            label = f"{i}. {(name or '')[:10]}"
        row.append(InlineKeyboardButton(
            label[:28],
            callback_data=f"change_pick_{user_id}_{sid}",
            style="primary",
        ))
        if len(row) == 2:
            kb.append(row)
            row = []
    if row:
        kb.append(row)
    kb.append([InlineKeyboardButton("BATAL", callback_data=f"change_cancel_{user_id}", style="danger")])

    await update.message.reply_text(
        _screen("CHANGE NUMBER", (
            f"{em(CE_TELEGRAM,'💬')} <b>PILIH SENDER</b>\n"
            f"────────────────────────────\n\n"
            f"{source_line}"
            f"  {em(CE_NOMOR,'📞')} Akan diproses: <b>{len(numbers)}/{CHANGE_MAX_NUMBERS}</b>\n"
            f"{preview}\n\n"
            f"  {em(CE_AKUN,'👤')} Sender kamu: <b>{len(senders)}</b>\n"
            f"  {em(E6,'🚀')} Workers: <b>{CHANGE_WORKERS}</b>\n\n"
            f"{em(CE_HELP,'💡')} <i>Pilih sender milik kamu yang mau diganti nomornya.</i>"
        ), "Home › Telegram › Change Number"),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(kb),
    )


async def _change_handle_otp_text(update, context, text):
    """Tangkap format suffix:kode untuk /change."""
    user_id = update.effective_user.id
    job = _change_jobs.get(user_id)
    if not job:
        return False
    m = re.match(r"^\s*(\d{3,15})\s*[:=]\s*(\d{3,10})\s*$", text or "")
    if not m:
        return False

    suffix, code = m.group(1), m.group(2)
    matches = [
        (phone, item) for phone, item in (job.get("targets") or {}).items()
        if phone.endswith(suffix) and item.get("status") == "waiting_otp" and item.get("hash")
    ]
    if not matches:
        await update.message.reply_text(
            _screen("CHANGE NUMBER", (
                f"{em(E2,'❌')} Tidak ada OTP menunggu untuk suffix <code>{html.escape(suffix)}</code>.\n"
                f"Cek nomor / status di progress."
            ), "Home › Telegram › Change Number"),
            parse_mode=ParseMode.HTML,
        )
        return True
    if len(matches) > 1:
        ambig = "\n".join(f"  • <code>+{p}</code>" for p, _ in matches[:8])
        await update.message.reply_text(
            _screen("CHANGE NUMBER", (
                f"{em(E3,'⚠️')} Suffix <code>{html.escape(suffix)}</code> ambigu.\n"
                f"Pakai digit lebih panjang:\n{ambig}"
            ), "Home › Telegram › Change Number"),
            parse_mode=ParseMode.HTML,
        )
        return True

    phone, item = matches[0]
    client = None
    try:
        client = TelegramClient(StringSession(job["session"]), TG_API_ID, TG_API_HASH)
        await asyncio.wait_for(client.connect(), timeout=20)
        if not await client.is_user_authorized():
            raise RuntimeError("Session sender expired")
        user = await asyncio.wait_for(
            client(ChangePhoneRequest(
                phone_number="+" + phone,
                phone_code_hash=item["hash"],
                phone_code=code,
            )),
            timeout=35,
        )
        new_phone = re.sub(r"\D", "", getattr(user, "phone", "") or phone)
        item.update({
            "status": "success",
            "detail": "Nomor diganti",
            "result": {
                "ok": True,
                "old_phone": "+" + job.get("sender_phone", ""),
                "new_phone": "+" + new_phone,
                "tg_id": getattr(user, "id", None),
                "username": getattr(user, "username", None),
                "first_name": getattr(user, "first_name", None),
            },
        })
        # Update pool + session string
        try:
            new_session = client.session.save()
            cur.execute(
                "UPDATE tgcheck_pool SET phone=?, string_session=?, name=COALESCE(NULLIF(name,''), ?) WHERE id=?",
                (new_phone, new_session, getattr(user, "first_name", None) or new_phone, job["sender_id"]),
            )
            conn.commit()
            job["sender_phone"] = new_phone
            job["session"] = new_session
        except Exception as db_e:
            item["detail"] = f"Sukses API, DB update gagal: {db_e}"

        # Cancel remaining waiting OTP (1 akun hanya 1 nomor aktif)
        for other_phone, other in (job.get("targets") or {}).items():
            if other_phone != phone and other.get("status") == "waiting_otp":
                other.update({"status": "cancelled", "detail": "Dibatalkan karena ganti nomor sukses"})

        payload = json.dumps(item.get("result") or {}, ensure_ascii=False, indent=2)
        await update.message.reply_text(
            _screen("CHANGE NUMBER", (
                f"{em(E1,'✅')} <b>GANTI NOMOR BERHASIL</b>\n"
                f"────────────────────────────\n\n"
                f"  {em(CE_NOMOR,'📞')} Baru: <code>+{html.escape(new_phone)}</code>\n"
                f"  {em(CE_DETAIL_ID,'🆔')} ID: <code>{getattr(user, 'id', '-')}</code>\n\n"
                f"<b>JSON:</b>\n"
                f"<pre>{html.escape(payload)}</pre>"
            ), "Home › Telegram › Change Number"),
            parse_mode=ParseMode.HTML,
        )
    except PhoneCodeInvalidError:
        item.update({"status": "waiting_otp", "detail": "Kode OTP salah, coba lagi"})
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} Kode OTP salah untuk <code>+{phone}</code>."),
            parse_mode=ParseMode.HTML,
        )
    except PhoneCodeExpiredError:
        item.update({"status": "error", "detail": "OTP kedaluwarsa"})
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} OTP kedaluwarsa untuk <code>+{phone}</code>."),
            parse_mode=ParseMode.HTML,
        )
    except FloodWaitError as fw:
        wait_s = int(getattr(fw, "seconds", 5) or 5)
        item.update({"status": "flood", "detail": f"FloodWait {wait_s}s"})
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(CE_LOADING,'🔄')} FloodWait <b>{wait_s}s</b>. Coba lagi nanti."),
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        item.update({"status": "error", "detail": str(exc)[:160]})
        await update.message.reply_text(
            _screen("CHANGE NUMBER", f"{em(E2,'❌')} Gagal: <code>{html.escape(str(exc)[:200])}</code>"),
            parse_mode=ParseMode.HTML,
        )
    finally:
        if client:
            try:
                await client.disconnect()
            except Exception:
                pass
        try:
            await _change_edit_status(context.bot, job)
        except Exception:
            pass
    return True


async def sender_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/sender — kelola sender (lihat/hapus/cek status)."""
    user_id = update.effective_user.id
    if not is_allowed_user(user_id):
        await update.message.reply_text(
            _screen('SENDER', f"{em(E2,'❌')} Kamu belum terdaftar. Hubungi owner."),
            parse_mode=ParseMode.HTML,
        )
        return

    pool = _get_pool(user_id, include_dead=True)
    if not pool:
        await update.message.reply_text(
            _screen('SENDER', (
                f"{em(E3,'⚠️')} <b>Belum ada sender.</b>\n\n"
                f"Tambah dengan: <code>/addsender 628xxx</code>\n\n"
                f"{em(CE_TELEGRAM,'💎')} <i>Makin banyak sender, makin anti-ban.</i>"
            ), 'Home › Sender'),
            parse_mode=ParseMode.HTML,
        )
        return

    now = int(time.time())
    total, active = _pool_count(user_id)
    body = [
        f"{em(CE_TELEGRAM,'💬')} <b>SENDER POOL</b>  ({total} total · {active} siap)\n"
    ]
    for i, s in enumerate(pool, 1):
        if s['status'] == 'dead':
            badge = f"{em(E2,'💀')} DEAD"
        elif s['flood_until'] > now:
            mins = int((s['flood_until'] - now) / 60) + 1
            badge = f"{em(E3,'🧊')} COOLDOWN {mins}m"
        else:
            badge = f"{em(E1,'✅')} SIAP"
        nm = html.escape((s['name'] or '-')[:20])
        body.append(
            f"\n<b>{i}.</b> {nm}\n"
            f"   📞 <code>+{s['phone']}</code>\n"
            f"   {badge}"
        )

    await update.message.reply_text(
        _screen('SENDER', '\n'.join(body), 'Home › Sender'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([
            [
                InlineKeyboardButton("CEK SEMUA", callback_data=f"sender_checkall_{user_id}", style="success"),
                InlineKeyboardButton("HAPUS MATI", callback_data=f"sender_deldead_{user_id}", style="primary"),
            ],
            [
                InlineKeyboardButton("HAPUS SEMUA", callback_data=f"sender_delall_{user_id}", style="danger"),
            ],
        ]),
    )


async def _handle_loginexp_callback(query, data, user_id, context):
    """Handle loginexp_ callbacks: export nomor by OTP type ke TXT."""
    if data.startswith('loginexp_done_'):
        await query.answer("Login mode selesai")
        context.user_data.pop(f'tgcheck_login_mode_{user_id}', None)
        context.user_data.pop(f'tgcheck_login_results_{user_id}', None)
        _tgcheck_login_pending.pop(user_id, None)
        try:
            await query.message.edit_text(
                _screen('LOGIN', f"{em(E1,'✅')} Login mode selesai."),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    results = context.user_data.get(f'tgcheck_login_results_{user_id}', {})
    sms_list = results.get('sms', [])
    app_list = results.get('app', [])

    if data.startswith('loginexp_sms_'):
        phones = sms_list
        label = 'SMS'
    elif data.startswith('loginexp_app_'):
        phones = app_list
        label = 'APP'
    elif data.startswith('loginexp_all_'):
        phones = sms_list + app_list
        label = 'ALL'
    else:
        return

    await query.answer(f"Export {label}: {len(phones)} nomor")

    if not phones:
        try:
            await query.message.reply_text(
                _screen('EXPORT', f"{em(E3,'⚠️')} Tidak ada nomor {label}."),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    # Bikin file TXT
    content = '\n'.join(f'+{p}' for p in phones)
    fname = f"login_{label.lower()}_{user_id}_{int(time.time())}.txt"
    fpath = os.path.join(os.path.dirname(__file__) or '.', fname)
    try:
        with open(fpath, 'w') as f:
            f.write(content)
        await query.message.reply_document(
            document=open(fpath, 'rb'),
            filename=fname,
            caption=f"📋 {label}: {len(phones)} nomor ({', '.join(phones[:3])}...)",
        )
    except Exception as e:
        try:
            await query.message.reply_text(f"Error export: {str(e)[:80]}")
        except Exception:
            pass
    finally:
        try:
            os.remove(fpath)
        except Exception:
            pass


async def _handle_sessions_callback(query, data, user_id):
    """Handle sessions_del_ and sessions_delall_ callbacks."""
    if data.startswith('sessions_delall_'):
        await query.answer("Semua captured dihapus!")
        try:
            cur.execute("DELETE FROM tgcheck_captured WHERE user_id=?", (user_id,))
            conn.commit()
        except Exception:
            pass
        try:
            await query.message.edit_text(
                _screen('SESSIONS', f"{em(E1,'✅')} <b>Semua akun captured dihapus.</b>"),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    if data.startswith('sessions_del_'):
        # format: sessions_del_{id}_{user_id}
        parts = data.split('_')
        if len(parts) >= 3:
            sid = parts[2]
            await query.answer(f"#{sid} dihapus!")
            try:
                cur.execute("DELETE FROM tgcheck_captured WHERE user_id=? AND id=?", (user_id, sid))
                conn.commit()
            except Exception:
                pass
            try:
                await query.message.edit_text(
                    _screen('SESSIONS', f"{em(E1,'✅')} Captured #{sid} dihapus."),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        return


async def _handle_sender_callback(query, data, user_id, context):
    """Handle sender_* callbacks: cek semua, hapus mati, hapus semua."""
    if data.startswith('sender_delall_'):
        await query.answer("Semua sender dihapus!")
        _delete_all_senders(user_id)
        try:
            await query.message.edit_text(
                _screen('SENDER', f"{em(E1,'✅')} <b>Semua sender dihapus.</b>\n\nTambah lagi via /addsender."),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    if data.startswith('sender_deldead_'):
        await query.answer("Sender mati dihapus!")
        try:
            cur.execute("DELETE FROM tgcheck_pool WHERE user_id=? AND status='dead'", (user_id,))
            conn.commit()
            n = cur.rowcount
        except Exception:
            n = 0
        total, active = _pool_count(user_id)
        try:
            await query.message.edit_text(
                _screen('SENDER', (
                    f"{em(E1,'✅')} <b>{n} sender mati dihapus.</b>\n\n"
                    f"Sisa pool: <b>{total}</b> ({active} siap)"
                ), 'Home › Sender'),
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
        return

    if data.startswith('sender_checkall_'):
        await query.answer("Mengecek semua sender...")
        pool = _get_pool(user_id, include_dead=True)
        if not pool:
            try:
                await query.message.edit_text(
                    _screen('SENDER', f"{em(E2,'❌')} Pool kosong."),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
            return

        results = []
        for s in pool:
            client = TelegramClient(StringSession(s['session']), TG_API_ID, TG_API_HASH)
            alive = False
            try:
                await client.connect()
                if await client.is_user_authorized():
                    await client.get_me()
                    alive = True
            except Exception:
                alive = False
            finally:
                try:
                    await client.disconnect()
                except Exception:
                    pass
            if alive:
                _mark_sender_active(s['id'])
            else:
                _mark_sender_dead(s['id'])
            badge = f"{em(E1,'✅')} HIDUP" if alive else f"{em(E2,'💀')} MATI"
            results.append(f"  {html.escape((s['name'] or '-')[:18])} <code>+{s['phone']}</code> — {badge}")

        total, active = _pool_count(user_id)
        try:
            await query.message.edit_text(
                _screen('SENDER', (
                    f"{em(CE_TELEGRAM,'💬')} <b>HASIL CEK POOL</b>  ({active}/{total} hidup)\n\n"
                    + '\n'.join(results)
                ), 'Home › Sender › Status'),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("HAPUS MATI", callback_data=f"sender_deldead_{user_id}", style="primary"),
                    InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="danger"),
                ]]),
            )
        except Exception:
            pass
        return



async def tgcheck_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler /check — Cek akun Telegram dari daftar nomor atau file .txt."""
    user_id = update.effective_user.id

    if not TELETHON_OK:
        await update.message.reply_text(
            _screen('CHECK TELEGRAM', (
                f"{em(E2,'❌')} <b>Telethon belum terinstall!</b>\n\n"
                f"Jalankan: <code>pip install telethon</code>"
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    if _tgcheck_active.get(user_id, False):
        await update.message.reply_text(
            _screen('CHECK TELEGRAM', (
                f"{em(E2,'⚠️')} <b>Masih ada proses berjalan!</b>\n\n"
                f"Tunggu selesai atau batalkan dulu."
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    phones = None
    invalid = []

    # Mode 1: Reply ke file .txt
    msg = update.message
    has_doc = (msg.reply_to_message and msg.reply_to_message.document) or msg.document
    if has_doc:
        loading = await msg.reply_text(
            f"{em(CE_LOADING,'🔄')} <i>Membaca file...</i>",
            parse_mode=ParseMode.HTML,
        )
        phones, err = await _tgcheck_parse_phones_from_doc(update, context)
        if err or not phones:
            await loading.edit_text(
                _screen('CHECK TELEGRAM', f"{em(E2,'❌')} {err or 'Tidak ada nomor valid di file.'}"),
                parse_mode=ParseMode.HTML,
            )
            return
        try:
            await loading.delete()
        except:
            pass
    else:
        # Mode 2: Parse dari text
        raw_text = msg.text or ''
        raw_text = re.sub(r'^/check\s*', '', raw_text, flags=re.IGNORECASE).strip()

        if not raw_text:
            # Tampilkan help
            await msg.reply_text(
                _screen('CHECK TELEGRAM', (
                    f"{em(CE_TELEGRAM,'💬')} <b>TELEGRAM ACCOUNT CHECKER</b>\n\n"
                    f"Cek apakah nomor telepon punya akun Telegram.\n\n"
                    f"<b>Cara pakai:</b>\n"
                    f"  • <code>/check 628123456789</code>\n"
                    f"  • <code>/check 628xx 628yy 628zz</code>\n"
                    f"  • Reply file <code>.txt</code> dengan <code>/check</code>\n\n"
                    f"<b>Status:</b>\n"
                    f"  {em(E1,'✅')} <b>Aktif</b> = punya app Telegram\n"
                    f"  {em(E6,'📱')} <b>SMS</b> = terdaftar tapi OTP via SMS\n"
                    f"  {em(E2,'❌')} <b>Tidak</b> = tidak terdaftar\n"
                    f"  {em(E2,'🚫')} <b>Banned</b> = nomor di-ban\n\n"
                    f"<b>Fitur:</b>\n"
                    f"  {em(E6,'🚀')} 20 worker paralel (super cepat)\n"
                    f"  {em(CE_EXPORT,'📤')} Export hasil ke .txt\n"
                    f"  {em(CE_FILE,'📁')} Riwayat tersimpan di DB\n"
                    f"  {em(E2,'🛑')} Cancel kapan aja\n\n"
                    f"{em(CE_WAKTU,'⏲')} <i>Format: 628xxx / +628xxx / 08xxx</i>"
                ), 'Home › Check'),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [
                        InlineKeyboardButton("RIWAYAT", callback_data=f"tgcheck_history_{user_id}", style="primary"),
                        InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="danger"),
                    ]
                ]),
            )
            return

        raw_numbers = re.split(r'[\s,;|]+', raw_text)
        phones = []
        for raw in raw_numbers:
            if not raw.strip():
                continue
            cleaned = _tgcheck_normalize_phone(raw)
            if 7 <= len(cleaned) <= 15:
                phones.append(cleaned)
            else:
                invalid.append(raw)

    if not phones:
        await msg.reply_text(
            _screen('CHECK TELEGRAM', (
                f"{em(E2,'❌')} <b>Tidak ada nomor valid!</b>\n\n"
                f"Contoh: <code>/check 628123456789</code>"
            ), 'Home › Check'),
            parse_mode=ParseMode.HTML,
        )
        return

    phones = list(dict.fromkeys(phones))

    # Konfirmasi
    confirm_body = (
        f"{em(CE_TELEGRAM,'💬')} <b>KONFIRMASI CHECK</b>\n\n"
        f"  {em(CE_NOMOR,'📞')} <b>Jumlah nomor:</b>  {len(phones)}\n"
        f"  {em(E6,'🚀')} <b>Workers:</b>  {TGCHECK_MAX_WORKERS} paralel\n"
    )
    if invalid:
        confirm_body += f"  {em(E3,'⚠️')} <b>Invalid (skip):</b>  {len(invalid)}\n"

    preview_count = min(5, len(phones))
    confirm_body += f"\n<b>Preview:</b>\n"
    for p in phones[:preview_count]:
        confirm_body += f"  • <code>+{p}</code>\n"
    if len(phones) > preview_count:
        confirm_body += f"  <i>... dan {len(phones) - preview_count} lainnya</i>\n"

    est = max(3, int(len(phones) / TGCHECK_MAX_WORKERS * 3))
    confirm_body += f"\n{em(CE_WAKTU,'⏲')} <i>Estimasi: ~{est} detik</i>"

    context.user_data[f'tgcheck_phones_{user_id}'] = phones

    _ptotal, _pactive = _pool_count(user_id)
    if _pactive > 0:
        confirm_body += f"\n{em(CE_TELEGRAM,'💎')} <i>Pool: {_pactive} sender siap — mode DETAIL tersedia</i>"

    btn_rows = [[
    InlineKeyboardButton("CEPAT", callback_data=f"tgcheck_confirm_{user_id}", style="success"),
    ]]
    if _pactive > 0:
        btn_rows[0].append(
            InlineKeyboardButton("DETAIL", callback_data=f"tgcheck_detail_{user_id}", style="primary")
        )

    btn_rows.append([
        InlineKeyboardButton("SPAM", callback_data=f"tgcheck_spam_{user_id}", style="primary"),
        InlineKeyboardButton("LOGIN", callback_data=f"tgcheck_login_{user_id}", style="primary"),
    ])

    btn_rows.append([
        InlineKeyboardButton("BATAL", callback_data=f"tgcheck_abort_{user_id}", style="danger"),
    ])

    await msg.reply_text(
        _screen('CHECK TELEGRAM', confirm_body, 'Home › Check › Konfirmasi'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup(btn_rows),
    )


async def _handle_tgcheck_callback(query, data, user_id, context):
    """Handle semua callback tgcheck_* dari menu_callback."""

    if data.startswith('tgcheck_confirm_'):
        await query.answer()
        phones = context.user_data.get(f'tgcheck_phones_{user_id}', [])
        if not phones:
            await query.message.edit_text(
                _screen('CHECK TELEGRAM', f"{em(E2,'❌')} Data tidak ditemukan. Coba /check lagi."),
                parse_mode=ParseMode.HTML,
            )
            return
        del context.user_data[f'tgcheck_phones_{user_id}']
        await query.message.edit_text(
            _screen('CHECK TELEGRAM', (
                f"{em(CE_LOADING,'🔄')} <b>Memulai {len(phones)} nomor ({TGCHECK_MAX_WORKERS} workers)...</b>\n\n"
                f"{em(CE_WAKTU,'⏲')} <i>Pake MTProto + paralel, santai aja~</i>"
            ), 'Home › Check › Processing'),
            parse_mode=ParseMode.HTML,
        )
        asyncio.create_task(_tgcheck_process_batch(phones, user_id, query.message, context))
        return

    if data.startswith('tgcheck_detail_'):
        await query.answer()
        phones = context.user_data.get(f'tgcheck_phones_{user_id}', [])
        if not phones:
            await query.message.edit_text(
                _screen('CHECK · DETAIL', f"{em(E2,'❌')} Data tidak ditemukan. Coba /check lagi."),
                parse_mode=ParseMode.HTML,
            )
            return
        total, active = _pool_count(user_id)
        if total == 0:
            await query.message.edit_text(
                _screen('CHECK · DETAIL', f"{em(E2,'❌')} Belum ada sender. Tambah via /addsender."),
                parse_mode=ParseMode.HTML,
            )
            return

        # Show sender pool status with flood info
        now = int(time.time())
        pool = _get_pool(user_id, include_dead=True)
        pool_body = (
            f"{em(CE_TELEGRAM,'💬')} <b>SENDER POOL STATUS</b>\n"
            f"────────────────────────────\n\n"
            f"  {em(CE_AKUN,'👥')} Total: <b>{total}</b> | "
            f"{em(E1,'✅')} Siap: <b>{active}</b>\n\n"
        )
        for i, s in enumerate(pool[:15]):
            flood_until = s.get('flood_until', 0)
            last_used = s.get('last_used', 0)
            name = s.get('name') or '-'
            phone = s.get('phone', '?')

            if s['status'] == 'dead':
                fs = f"{em(E2,'❌')} Dead"
            elif flood_until > now:
                remaining = flood_until - now
                if remaining > 86400:
                    fs = f"{em(CE_LOADING,'🔄')} Flood {remaining // 86400}d"
                elif remaining > 3600:
                    fs = f"{em(CE_LOADING,'🔄')} Flood {remaining // 3600}h"
                else:
                    fs = f"{em(CE_LOADING,'🔄')} Flood {remaining // 60}m"
            else:
                fs = f"{em(E1,'✅')} Siap"

            if last_used > 0:
                from datetime import datetime as dt
                diff = now - last_used
                act = "Aktif" if diff < 300 else dt.fromtimestamp(last_used).strftime("%d/%m %H:%M")
            else:
                act = "-"

            pool_body += f"  {i+1}. <code>+{phone}</code> {name[:10]} | {fs} | {em(CE_WAKTU,'⏲')} {act}\n"

        if len(pool) > 15:
            pool_body += f"  <i>... +{len(pool)-15} lainnya</i>\n"

        if active == 0:
            pool_body += f"\n{em(E3,'⚠️')} <b>Semua sender flood/mati. Tunggu atau /addsender.</b>"
            await query.message.edit_text(
                _screen('CHECK · DETAIL', pool_body, 'Home › Check › Detail'),
                parse_mode=ParseMode.HTML,
            )
            return

        pool_body += (
            f"\n────────────────────────────\n"
            f"{em(CE_LOADING,'🟠')} <b>Memulai deep lookup {len(phones)} nomor...</b>"
        )
        del context.user_data[f'tgcheck_phones_{user_id}']
        await query.message.edit_text(
            _screen('CHECK · DETAIL', pool_body, 'Home › Check › Detail'),
            parse_mode=ParseMode.HTML,
        )
        asyncio.create_task(_tgcheck_process_sender(phones, user_id, query.message, context, None))
        return

    if data.startswith('tgcheck_login_'):
        await query.answer()
        if not is_owner(user_id):
            await query.message.edit_text(
                _screen('CHECK · LOGIN', f"{em(E2,'❌')} Hanya owner."),
                parse_mode=ParseMode.HTML,
            )
            return
        phones = context.user_data.get(f'tgcheck_phones_{user_id}', [])
        if not phones:
            await query.message.edit_text(
                _screen('CHECK · LOGIN', f"{em(E2,'❌')} Nomor hilang, ulangi /check."),
                parse_mode=ParseMode.HTML,
            )
            return
        del context.user_data[f'tgcheck_phones_{user_id}']
        await query.message.edit_text(
            _screen('CHECK · LOGIN', (
                f"{em(CE_LOADING,'🔓')} <b>Kirim OTP ke {len(phones)} nomor...</b>\n\n"
                f"{em(CE_WAKTU,'⏲')} <i>Hash disimpan 5 menit. Ketik nomor:kode setelah selesai.</i>"
            ), 'Home › Check › Login'),
            parse_mode=ParseMode.HTML,
        )
        asyncio.create_task(_tgcheck_process_login(phones, user_id, query.message, context))
        return

    if data.startswith('tgcheck_spam_'):
        await query.answer()
        phones = context.user_data.get(f'tgcheck_phones_{user_id}', [])
        if not phones:
            await query.message.edit_text(
                _screen('CHECK · SPAM', f"{em(E2,'❌')} Nomor hilang, ulangi /check."),
                parse_mode=ParseMode.HTML,
            )
            return
        del context.user_data[f'tgcheck_phones_{user_id}']
        await query.message.edit_text(
            _screen('CHECK · SPAM', (
                f"{em(E3,'🔥')} <b>SPAM DIMULAI</b>\n\n"
                f"  {em(CE_NOMOR,'📞')} Target: {len(phones)} nomor\n"
                f"  {em(E6,'🚀')} Workers: 20 ({len(_SPAM_API_POOL)} API rotasi)\n\n"
                f"  {em(CE_LOADING,'🔄')} <i>Firing...</i>"
            ), 'Home › Check › SPAM'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("STOP", callback_data=f"spam_stop_{user_id}", style="danger")
            ]]),
        )
        asyncio.create_task(_tgcheck_process_spam(phones, user_id, query.message, context, mode='app'))
        return

    if data.startswith('spam_api_') or data.startswith('spam_app_'):
        await query.answer()
        mode = 'api' if data.startswith('spam_api_') else 'app'
        phones = context.user_data.pop(f'spam_phones_{user_id}', [])
        if not phones:
            await query.message.edit_text(
                _screen('CHECK · SPAM', f"{em(E2,'❌')} Data hilang, ulangi /check."),
                parse_mode=ParseMode.HTML,
            )
            return
        workers = 50 if mode == 'api' else 25
        await query.message.edit_text(
            _screen('CHECK · SPAM', (
                f"{em(E3,'🔥')} <b>SPAM {mode.upper()} DIMULAI</b>\n\n"
                f"  {em(CE_NOMOR,'📞')} Target: {len(phones)} nomor\n"
                f"  {em(E6,'🚀')} Workers: {workers}\n\n"
                f"  {em(CE_LOADING,'🔄')} <i>Firing...</i>"
            ), 'Home › Check › SPAM'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("STOP", callback_data=f"spam_stop_{user_id}", style="danger")
            ]]),
        )
        asyncio.create_task(_tgcheck_process_spam(phones, user_id, query.message, context, mode=mode))
        return

    if data.startswith('spam_stop_'):
        await query.answer("Menghentikan spam...")
        _spam_cancel_flags[user_id] = True
        return

    if data.startswith('tgcheck_abort_'):
        await query.answer()
        context.user_data.pop(f'tgcheck_phones_{user_id}', None)
        await query.message.edit_text(
            _screen('CHECK TELEGRAM', f"{em(E2,'❌')} <b>Dibatalkan.</b>"),
            parse_mode=ParseMode.HTML,
        )
        return

    if data.startswith('tgcheck_cancel_'):
        await query.answer("Membatalkan...")
        _tgcheck_cancel_flags[user_id] = True
        return

    if data.startswith('tgcheck_history_'):
        await query.answer()
        try:
            cur.execute(
                "SELECT phone, status, detail, checked_at FROM tgcheck_results "
                "WHERE user_id = ? ORDER BY checked_at DESC LIMIT 50",
                (user_id,)
            )
            rows = cur.fetchall()
        except Exception:
            rows = []

        if not rows:
            await query.message.edit_text(
                _screen('CHECK TELEGRAM', (
                    f"{em(CE_FILE,'📁')} <b>RIWAYAT CHECK</b>\n\n"
                    f"<i>Belum ada riwayat.</i>"
                ), 'Home › Check › Riwayat'),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="danger")
                ]]),
            )
            return

        body = f"{em(CE_FILE,'📁')} <b>RIWAYAT CHECK</b>  (50 terakhir)\n\n"
        for phone, status, detail, checked_at in rows[:50]:
            s_em = _tgcheck_status_emoji(status)
            s_label = _tgcheck_status_label(status)
            ts = checked_at[:16] if checked_at else '?'
            body += f"  {s_em} <code>+{phone}</code>  {s_label}  <i>{ts}</i>\n"

        reg_count = sum(1 for r in rows if r[1] in ('registered', 'registered_app', 'registered_sms'))
        unreg_count = sum(1 for r in rows if r[1] == 'not_registered')
        body += f"\n  {em(E1,'✅')} Terdaftar: <b>{reg_count}</b>  |  {em(E2,'❌')} Tidak: <b>{unreg_count}</b>"

        buttons = [[
            InlineKeyboardButton("HAPUS RIWAYAT", callback_data=f"tgcheck_clear_{user_id}", style="danger"),
            InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="primary"),
        ]]

        try:
            await query.message.edit_text(
                _screen('CHECK TELEGRAM', body, 'Home › Check › Riwayat'),
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup(buttons),
            )
        except Exception:
            pass
        return

    if data.startswith('tgcheck_clear_'):
        await query.answer("Riwayat dihapus!")
        try:
            cur.execute("DELETE FROM tgcheck_results WHERE user_id = ?", (user_id,))
            conn.commit()
        except Exception:
            pass
        await query.message.edit_text(
            _screen('CHECK TELEGRAM', f"{em(E1,'✅')} <b>Riwayat dihapus.</b>"),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="danger")
            ]]),
        )
        return

    # ── Export handlers ──
    # ── Export DETAIL (sender results: id, name, premium, year) ──
    if data.startswith('tgcheck_export_detail_') or data.startswith('tgcheck_export_prem_'):
        await query.answer()
        sresults = context.user_data.get(f'tgcheck_sender_results_{user_id}', [])
        if not sresults:
            try:
                await query.message.reply_text(
                    _screen('CHECK · DETAIL', f"{em(E2,'❌')} Tidak ada data detail."),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
            return

        prem_only = data.startswith('tgcheck_export_prem_')
        if prem_only:
            sresults = [r for r in sresults if r.get('premium')]
            filename = 'tg_premium.txt'
        else:
            filename = 'tg_detail.csv'

        if not sresults:
            try:
                await query.message.reply_text(
                    _screen('CHECK · DETAIL', f"{em(E2,'❌')} Tidak ada akun premium."),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
            return

        lines = ["phone,user_id,name,username,premium,year"]
        for r in sresults:
            name = (f"{r.get('first_name','')} {r.get('last_name','')}").strip().replace(',', ' ')
            lines.append(
                f"+{r['phone']},{r.get('id','')},{name},"
                f"{r.get('username','')},{'YES' if r.get('premium') else 'NO'},{r.get('year','')}"
            )
        content = '\n'.join(lines)
        filepath = os.path.join(os.path.dirname(__file__) or '.', filename)
        try:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(content)
            await query.message.reply_document(
                document=open(filepath, 'rb'),
                filename=filename,
                caption=(
                    f"{em(CE_EXPORT,'📤')} <b>Export {'PREMIUM' if prem_only else 'DETAIL'}</b>\n"
                    f"Total: <b>{len(sresults)}</b> akun"
                ),
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            try:
                await query.message.reply_text(
                    _screen('CHECK · DETAIL', f"{em(E2,'❌')} Gagal export: {html.escape(str(e)[:80])}"),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        finally:
            try:
                os.remove(filepath)
            except Exception:
                pass
        return

    if data.startswith('tgcheck_export_'):
        await query.answer()
        results = context.user_data.get(f'tgcheck_results_{user_id}', [])

        if not results:
            try:
                cur.execute(
                    "SELECT phone, status, detail FROM tgcheck_results "
                    "WHERE user_id = ? ORDER BY checked_at DESC LIMIT 500",
                    (user_id,)
                )
                results = [(r[0], r[1], r[2]) for r in cur.fetchall()]
            except Exception:
                results = []

        if not results:
            try:
                await query.message.edit_text(
                    _screen('CHECK TELEGRAM', f"{em(E2,'❌')} Tidak ada data."),
                    parse_mode=ParseMode.HTML,
                )
            except:
                pass
            return

        if 'export_reg_' in data:
            export_type = 'reg'
            filtered = [r for r in results if r[1] in ('registered', 'registered_app', 'registered_sms')]
            filename = 'tg_registered.txt'
        elif 'export_unreg_' in data:
            export_type = 'unreg'
            filtered = [r for r in results if r[1] == 'not_registered']
            filename = 'tg_not_registered.txt'
        else:
            export_type = 'all'
            filtered = results
            filename = 'tg_check_results.txt'

        if not filtered:
            try:
                await query.message.edit_text(
                    _screen('CHECK TELEGRAM', f"{em(E2,'❌')} Tidak ada data kategori ini."),
                    parse_mode=ParseMode.HTML,
                )
            except:
                pass
            return

        lines = []
        if export_type == 'all':
            lines.append(f"# Telegram Account Check Results")
            lines.append(f"# Checked: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
            lines.append(f"# Total: {len(filtered)}")
            lines.append(f"# {'='*50}")
            lines.append(f"")
            for phone, status, detail in filtered:
                label = _tgcheck_status_label(status)
                lines.append(f"+{phone} | {label} | {detail}")
        else:
            for phone, status, detail in filtered:
                lines.append(f"+{phone}")

        content = '\n'.join(lines)
        filepath = os.path.join(os.path.dirname(__file__) or '.', filename)
        try:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(content)

            export_label = {'reg': 'TERDAFTAR', 'unreg': 'TIDAK TERDAFTAR', 'all': 'SEMUA'}.get(export_type, 'SEMUA')
            await query.message.reply_document(
                document=open(filepath, 'rb'),
                filename=filename,
                caption=(
                    f"{em(CE_EXPORT,'📤')} <b>Export {export_label}</b>\n"
                    f"Total: <b>{len(filtered)}</b> nomor"
                ),
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            try:
                await query.message.reply_text(
                    _screen('CHECK TELEGRAM', f"{em(E2,'❌')} Gagal export: {html.escape(str(e)[:100])}"),
                    parse_mode=ParseMode.HTML,
                )
            except:
                pass
        finally:
            try:
                os.remove(filepath)
            except:
                pass
        return


# ══════════════════════════════════════════════════════════════════════════════
# ██  REPE — /repe  (Nomor Cantik Extractor)
# ══════════════════════════════════════════════════════════════════════════════
# Ekstrak nomor dengan digit berulang (repeating) dari input text / reply.
# Kategori: Low (3x), Standar (4x), Eklusif (5-9x)
# ══════════════════════════════════════════════════════════════════════════════

def _repe_extract_phones(text: str) -> list:
    """Ambil semua nomor telepon dari text (hanya yg > 6 digit, max 15 digit)."""
    phones = []
    for line in text.splitlines():
        # Cari semua pattern nomor di tiap baris (tanpa space di tengah angka)
        # Pattern: optional +, lalu digits yang mungkin ada dash/dot di tengah
        matches = re.findall(r'\+?\d[\d\-\.]{5,14}', line)
        for raw in matches:
            cleaned = re.sub(r'[^\d]', '', raw)
            # Hanya ambil nomor 7-15 digit (range wajar nomor telepon)
            if len(cleaned) < 7 or len(cleaned) > 15:
                continue
            # Normalize: 08xx -> 628xx (Indo local)
            if cleaned.startswith('0') and len(cleaned) >= 10:
                cleaned = '62' + cleaned[1:]
            phones.append(cleaned)
    return list(dict.fromkeys(phones))  # dedupe, preserve order


def _repe_find_repeats(phone: str) -> int:
    """Cari jumlah digit berulang terpanjang dalam nomor."""
    max_repeat = 1
    current_count = 1
    for i in range(1, len(phone)):
        if phone[i] == phone[i-1]:
            current_count += 1
            max_repeat = max(max_repeat, current_count)
        else:
            current_count = 1
    return max_repeat


def _repe_categorize(phone: str) -> tuple:
    """Kategorikan nomor berdasarkan jumlah digit berulang.
    Returns (category, repeat_count) or (None, 0) jika < 3.
    """
    repeat = _repe_find_repeats(phone)
    if repeat >= 5:
        return 'eklusif', repeat
    elif repeat == 4:
        return 'standar', repeat
    elif repeat == 3:
        return 'low', repeat
    return None, 0


def _repe_format_phone(phone: str) -> str:
    """Format nomor jadi +628xxx."""
    if phone.startswith('62'):
        return f"+{phone}"
    return f"+{phone}"


def _repe_build_results(phones: list) -> dict:
    """Proses semua nomor, return dict {eklusif: [], standar: [], low: []}."""
    results = {'eklusif': [], 'standar': [], 'low': []}
    for phone in phones:
        cat, repeat = _repe_categorize(phone)
        if cat:
            results[cat].append((phone, repeat))
    # Sort tiap kategori by repeat count descending
    for cat in results:
        results[cat].sort(key=lambda x: x[1], reverse=True)
    return results


def _repe_format_inline(results: dict) -> str:
    """Format hasil untuk kirim langsung di Telegram (inline)."""
    total = sum(len(v) for v in results.values())
    parts = []

    if results['eklusif']:
        parts.append(f"\n{em(CE_REPE_EKLUSIF,'🔝')} <b>EKLUSIF</b> (5-9 digit sama)  ×{len(results['eklusif'])}")
        parts.append(f"{'─'*30}")
        for i, (phone, rep) in enumerate(results['eklusif'], 1):
            parts.append(f"  {i}. <code>{_repe_format_phone(phone)}</code>  ({'🔥' * min(rep-4, 5)} {rep}x)")

    if results['standar']:
        parts.append(f"\n{em(E1,'⭐')} <b>STANDAR</b> (4 digit sama)  ×{len(results['standar'])}")
        parts.append(f"{'─'*30}")
        for i, (phone, rep) in enumerate(results['standar'], 1):
            parts.append(f"  {i}. <code>{_repe_format_phone(phone)}</code>  (⭐ {rep}x)")

    if results['low']:
        parts.append(f"\n{em(E3,'📱')} <b>LOW</b> (3 digit sama)  ×{len(results['low'])}")
        parts.append(f"{'─'*30}")
        for i, (phone, rep) in enumerate(results['low'], 1):
            parts.append(f"  {i}. <code>{_repe_format_phone(phone)}</code>  (📱 {rep}x)")

    return '\n'.join(parts)


def _repe_format_txt(results: dict) -> str:
    """Format hasil untuk file .txt export."""
    lines = []
    lines.append("═══════════════════════════════════════════")
    lines.append("       ✨ NOMOR CANTIK — REPE RESULTS ✨")
    lines.append("═══════════════════════════════════════════")
    lines.append(f"  Tanggal: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    lines.append(f"  Total Ditemukan: {sum(len(v) for v in results.values())}")
    lines.append("═══════════════════════════════════════════")
    lines.append("")

    if results['eklusif']:
        lines.append("┌─────────────────────────────────────────┐")
        lines.append("│  💎 EKLUSIF (5-9 digit berulang)        │")
        lines.append("├─────────────────────────────────────────┤")
        for i, (phone, rep) in enumerate(results['eklusif'], 1):
            lines.append(f"│  {i:>3}. +{phone:<20} [{rep}x repeat]  │")
        lines.append("└─────────────────────────────────────────┘")
        lines.append("")

    if results['standar']:
        lines.append("┌─────────────────────────────────────────┐")
        lines.append("│  ⭐ STANDAR (4 digit berulang)           │")
        lines.append("├─────────────────────────────────────────┤")
        for i, (phone, rep) in enumerate(results['standar'], 1):
            lines.append(f"│  {i:>3}. +{phone:<20} [{rep}x repeat]  │")
        lines.append("└─────────────────────────────────────────┘")
        lines.append("")

    if results['low']:
        lines.append("┌─────────────────────────────────────────┐")
        lines.append("│  📱 LOW (3 digit berulang)               │")
        lines.append("├─────────────────────────────────────────┤")
        for i, (phone, rep) in enumerate(results['low'], 1):
            lines.append(f"│  {i:>3}. +{phone:<20} [{rep}x repeat]  │")
        lines.append("└─────────────────────────────────────────┘")
        lines.append("")

    lines.append("═══════════════════════════════════════════")
    lines.append("  Powered by DikZz — Nomor Cantik Finder")
    lines.append("═══════════════════════════════════════════")
    return '\n'.join(lines)


async def repe_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/repe — Ekstrak nomor cantik (digit berulang) dari nomor/text/reply."""
    user_id = update.effective_user.id
    msg = update.message

    raw_text = ""

    # Mode 1: Reply ke pesan (bisa text atau document)
    if msg.reply_to_message:
        reply = msg.reply_to_message
        if reply.document:
            # Download file
            try:
                doc = reply.document
                if doc.file_size and doc.file_size > 5 * 1024 * 1024:
                    await msg.reply_text(
                        _screen('REPE', f"{em(E2,'❌')} File terlalu besar (maks 5MB)."),
                        parse_mode=ParseMode.HTML,
                    )
                    return
                tfile = await doc.get_file()
                content = await tfile.download_as_bytearray()
                raw_text = content.decode('utf-8', errors='ignore')
            except Exception as e:
                await msg.reply_text(
                    _screen('REPE', f"{em(E2,'❌')} Gagal baca file: {html.escape(str(e)[:80])}"),
                    parse_mode=ParseMode.HTML,
                )
                return
        elif reply.text:
            raw_text = reply.text
        elif reply.caption:
            raw_text = reply.caption

    # Mode 2: Nomor langsung di command
    cmd_text = msg.text or ''
    cmd_text = re.sub(r'^/repe\s*', '', cmd_text, flags=re.IGNORECASE).strip()
    if cmd_text:
        raw_text = (raw_text + '\n' + cmd_text) if raw_text else cmd_text

    if not raw_text.strip():
        await msg.reply_text(
            _screen('REPE', (
                f"{em(E6,'💎')} <b>NOMOR CANTIK EXTRACTOR</b>\n\n"
                f"Cari nomor dengan digit berulang dari daftar nomor.\n\n"
                f"<b>Cara pakai:</b>\n"
                f"  • <code>/repe 628888888812</code>\n"
                f"  • <code>/repe 6281234 6285555567</code>\n"
                f"  • Reply pesan/file lalu ketik <code>/repe</code>\n\n"
                f"<b>Kategori:</b>\n"
                f"  {em(E3,'📱')} <b>Low</b> — 3 digit sama\n"
                f"  {em(E1,'⭐')} <b>Standar</b> — 4 digit sama\n"
                f"  {em(E6,'💎')} <b>Eklusif</b> — 5-9 digit sama\n\n"
                f"<i>Hanya nomor di atas 6 angka yang diproses.</i>"
            ), 'Home › Repe'),
            parse_mode=ParseMode.HTML,
        )
        return

    # Proses loading
    loading = await msg.reply_text(
        f"{em(CE_LOADING,'🔄')} <i>Scanning nomor cantik...</i>",
        parse_mode=ParseMode.HTML,
    )

    # Extract & categorize
    phones = _repe_extract_phones(raw_text)

    if not phones:
        await loading.edit_text(
            _screen('REPE', (
                f"{em(E2,'❌')} <b>Tidak ada nomor valid ditemukan.</b>\n\n"
                f"Pastikan input berisi nomor telepon (> 6 digit)."
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    results = _repe_build_results(phones)
    total_found = sum(len(v) for v in results.values())

    if total_found == 0:
        await loading.edit_text(
            _screen('REPE', (
                f"{em(E3,'⚠️')} <b>Tidak ada nomor cantik ditemukan.</b>\n\n"
                f"Dari <b>{len(phones)}</b> nomor yang di-scan, tidak ada\n"
                f"yang punya 3+ digit berulang berurutan."
            )),
            parse_mode=ParseMode.HTML,
        )
        return

    # Threshold: > 30 nomor cantik → kirim file, else inline
    INLINE_THRESHOLD = 30

    if total_found <= INLINE_THRESHOLD:
        # Kirim langsung inline di Telegram
        body = (
            f"{em(CE_DETAIL_GEM,'💎')} <b>NOMOR CANTIK DITEMUKAN</b>\n\n"
            f"  {em(CE_FILE,'📊')} <b>Total scan:</b>  {len(phones)} nomor\n"
            f"  {em(E1,'✅')} <b>Cantik:</b>  {total_found} nomor\n"
            f"{'─'*30}\n"
            f"  {em(CE_DETAIL_GEM,'💎')} Statistik Ringkasan:\n"
            f"    ├ Eklusif: <b>{len(results['eklusif'])}</b>\n"
            f"    ├ Standar: <b>{len(results['standar'])}</b>\n"
            f"    └ Low: <b>{len(results['low'])}</b>\n"
            f"{'─'*30}\n"
            f"{_repe_format_inline(results)}\n"
        )
        await loading.edit_text(
            _screen('REPE', body, 'Home › Repe › Results'),
            parse_mode=ParseMode.HTML,
        )
    else:
        # Kirim langsung sebagai file .txt (tanpa summary screen)
        txt_content = _repe_format_txt(results)
        fname = f"nomor_cantik_{user_id}_{int(time.time())}.txt"
        fpath = os.path.join(os.path.dirname(__file__) or '.', fname)

        # Hapus loading message
        try:
            await loading.delete()
        except Exception:
            pass

        try:
            with open(fpath, 'w', encoding='utf-8') as f:
                f.write(txt_content)
            await msg.reply_document(
                document=open(fpath, 'rb'),
                filename=fname,
                caption=_quote(
                    f"{em(CE_DETAIL_GEM,'💎')} <b>Hasil Nomor Cantik</b>\n"
                    f"{'─'*28}\n"
                    f"{em(CE_FILE,'📊')} Total: <b>{total_found}</b> nomor cantik\n\n"
                    f"{em(E6,'🔥')} Statistik:\n"
                    f"  ├ {em(CE_REPE_EKLUSIF,'🔝')} Eklusif: <b>{len(results['eklusif'])}</b>\n"
                    f"  ├ {em(E1,'⭐')} Standar: <b>{len(results['standar'])}</b>\n"
                    f"  └ {em(E3,'📱')} Low: <b>{len(results['low'])}</b>\n"
                    f"{'─'*28}\n"
                    f"{em(E4,'🎧')} <i>Powered by</i> <b>DikZz</b>"
                ),
                parse_mode=ParseMode.HTML,
            )
        except Exception as e:
            print(f"[REPE] Gagal kirim file: {e}")
        finally:
            try:
                os.remove(fpath)
            except Exception:
                pass


