async def _fb_process(query, context, server: int):
    """Process FB lookup after server selection."""
    user_id = query.from_user.id
    phones = context.user_data.get(f"fb_phones_{user_id}", [])
    if not phones:
        await query.message.edit_text(f"{EMOJI['FAILED']} No phones stored.", parse_mode=ParseMode.HTML)
        return

    lookup_fn = lookup_facebook_s2 if server == 2 else lookup_facebook
    bulk_fn = bulk_lookup_s2 if server == 2 else bulk_lookup
    sv_label = "Server 2" if server == 2 else "Server 1"

    if len(phones) == 1:
        await query.message.edit_text(
            f"<blockquote>{em(CE_FB, '🔍')} <b>Facebook Lookup</b> · {sv_label}\n\n"
            f"{em(CE_LOADING, '🔄')} Checking <code>+{phones[0]}</code>...</blockquote>",
            parse_mode=ParseMode.HTML
        )
        loop = asyncio.get_event_loop()
        result = await loop.run_in_executor(None, lambda: lookup_fn(phones[0]))
        await query.message.edit_text(_fb_format_single(result), parse_mode=ParseMode.HTML)
    else:
        msg = query.message
        await msg.edit_text(
            f"<blockquote>{em(CE_FB, '🔍')} <b>Facebook Bulk</b> · {sv_label}\n\n"
            f"{em(CE_NOMOR, '📂')} Total: <b>{len(phones)}</b> nomor\n"
            f"{em(CE_LIVE, '📡')} Worker: <b>40</b>\n"
            f"{em(CE_LOADING, '🔄')} Progress: 0/{len(phones)} (0%)</blockquote>",
            parse_mode=ParseMode.HTML
        )
        loop = asyncio.get_event_loop()
        last_upd = [0]

        def _prog(done, total):
            now = time.time()
            if now - last_upd[0] < 2.5: return
            last_upd[0] = now
            pct = int(done / total * 100)
            bar = "█" * (pct // 10) + "░" * (10 - pct // 10)
            loop.call_soon_threadsafe(
                lambda: asyncio.create_task(
                    msg.edit_text(
                        f"<blockquote>{em(CE_FB, '🔍')} <b>Facebook Bulk</b> · {sv_label}\n\n"
                        f"{em(CE_NOMOR, '📂')} Total: <b>{total}</b> nomor\n"
                        f"{em(CE_LIVE, '📡')} Worker: <b>40</b>\n"
                        f"{EMOJI['SUCCESS']} Progress: {done}/{total} ({pct}%)\n"
                        f"<code>[{bar}]</code></blockquote>",
                        parse_mode=ParseMode.HTML
                    )
                ),
            )

        results = await loop.run_in_executor(
            None, lambda: bulk_fn(phones, max_workers=40, progress_cb=_prog)
        )

        # 3-tier counting
        confirmed = [r for r in results if r.status == "found"]
        uncertain = [r for r in results if r.status == "uncertain"]
        not_found_list = [r for r in results if r.status == "not_found"]
        error_list = [r for r in results if r.error]
        total_accts = sum(len(r.accounts) for r in results if r.found)

        if len(results) <= 5:
            parts = [_fb_format_single(r) for r in results]
            parts.append(
                _screen('FACEBOOK LOOKUP', (
                    f"{em(CE_FB, '🔍')} <b>RINGKASAN</b> · {sv_label}\n"
                    f"────────────────────────────\n\n"
                    f"  {EMOJI['SUCCESS']} <b>Terdaftar:</b> {len(confirmed)}\n"
                    f"  {em(E3, '⚠️')} <b>Tersembunyi:</b> {len(uncertain)}\n"
                    f"  {EMOJI['FAILED']} <b>Tidak terdaftar:</b> {len(not_found_list)}\n"
                    f"  {em(CE_LIVE, '📊')} <b>Total akun:</b> {total_accts}"
                ), 'Home › Facebook › Results')
            )
            await msg.edit_text("\n".join(parts), parse_mode=ParseMode.HTML)
        else:
            # ── Build file output with 3 tiers ──
            lines = []
            lines.append(f"{'═'*55}")
            lines.append(f"   🔍 FACEBOOK LOOKUP RESULTS")
            lines.append(f"   {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} | {sv_label}")
            lines.append(f"{'═'*55}")
            lines.append(f"   ✅ Terdaftar   : {len(confirmed)}")
            lines.append(f"   ⚠️ Tersembunyi : {len(uncertain)}")
            lines.append(f"   ❌ Tidak       : {len(not_found_list)}")
            if error_list:
                lines.append(f"   💀 Error       : {len(error_list)}")
            lines.append(f"   👤 Total Akun  : {total_accts}")
            lines.append(f"{'═'*55}")
            lines.append("")

            # Section 1: TERDAFTAR (confirmed real)
            if confirmed:
                lines.append(f"┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓")
                lines.append(f"┃  ✅ TERDAFTAR ({len(confirmed)} nomor)")
                lines.append(f"┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛")
                lines.append("")
                for idx, r in enumerate(confirmed, 1):
                    lines.append(f"  [{idx:>3}] +{r.phone}")
                    for a in r.accounts:
                        lines.append(f"        ├─ 👤 Nama     : {a.name}")
                        if a.uid:
                            uid_short = a.uid[:40] + "..." if len(a.uid) > 40 else a.uid
                            lines.append(f"        ├─ 🆔 UID      : {uid_short}")
                        if a.masked_phone:
                            lines.append(f"        ├─ 📞 Phone    : {a.masked_phone}")
                        if a.masked_email:
                            lines.append(f"        ├─ 📩 Email    : {a.masked_email}")
                        if a.recovery:
                            lines.append(f"        ├─ 📲 Recovery : {a.recovery}")
                        pic_status = "Custom" if a.has_custom_pic else "Default"
                        lines.append(f"        └─ 🖼 Foto     : {pic_status}")
                    lines.append("")
                lines.append("")

            # Section 2: TERSEMBUNYI (uncertain / honeypot / masked only)
            if uncertain:
                lines.append(f"┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓")
                lines.append(f"┃  ⚠️ TERSEMBUNYI ({len(uncertain)} nomor)")
                lines.append(f"┃  FB return masked data — bisa honeypot / private")
                lines.append(f"┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛")
                lines.append("")
                for idx, r in enumerate(uncertain, 1):
                    lines.append(f"  [{idx:>3}] +{r.phone}")
                    for a in r.accounts:
                        if a.uid:
                            uid_short = a.uid[:40] + "..." if len(a.uid) > 40 else a.uid
                            lines.append(f"        ├─ 🆔 UID      : {uid_short}")
                        if a.masked_phone:
                            lines.append(f"        ├─ 📞 Phone    : {a.masked_phone}")
                        if a.recovery:
                            lines.append(f"        └─ 📲 Recovery : {a.recovery}")
                        else:
                            lines.append(f"        └─ ⚠️ Status   : Tersembunyi")
                    lines.append("")
                lines.append("")

            # Section 3: TIDAK TERDAFTAR
            if not_found_list:
                lines.append(f"┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓")
                lines.append(f"┃  ❌ TIDAK TERDAFTAR ({len(not_found_list)} nomor)")
                lines.append(f"┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛")
                lines.append("")
                for idx, r in enumerate(not_found_list, 1):
                    lines.append(f"  [{idx:>3}] +{r.phone}")
                lines.append("")

            # Section 4: ERROR
            if error_list:
                lines.append(f"┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓")
                lines.append(f"┃  💀 ERROR ({len(error_list)} nomor)")
                lines.append(f"┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛")
                lines.append("")
                for idx, r in enumerate(error_list, 1):
                    lines.append(f"  [{idx:>3}] +{r.phone} — {r.error}")
                lines.append("")

            lines.append(f"{'═'*55}")
            lines.append(f"   Powered by DikZz | {sv_label}")
            lines.append(f"{'═'*55}")

            import tempfile
            fname = f"fb_{sv_label.replace(' ','').lower()}_{datetime.now().strftime('%H%M%S')}.txt"
            tmp_path = os.path.join(tempfile.gettempdir(), fname)
            with open(tmp_path, 'w', encoding='utf-8') as f:
                f.write("\n".join(lines))
            await msg.edit_text(
                _screen('FACEBOOK LOOKUP', (
                    f"{em(CE_FB, '🔍')} <b>HASIL LOOKUP</b> · {sv_label}\n"
                    f"────────────────────────────\n\n"
                    f"  {EMOJI['SUCCESS']} <b>Terdaftar:</b> {len(confirmed)}\n"
                    f"  {em(E3, '⚠️')} <b>Tersembunyi:</b> {len(uncertain)}\n"
                    f"  {EMOJI['FAILED']} <b>Tidak:</b> {len(not_found_list)}\n"
                    f"  {em(CE_LIVE, '📊')} <b>Total akun:</b> {total_accts}\n\n"
                    f"  {em(CE_FILE, '📄')} File dikirim di bawah"
                ), 'Home › Facebook › Results'),
                parse_mode=ParseMode.HTML
            )
            await msg.reply_document(
                document=open(tmp_path, 'rb'), filename=fname,
                caption=(
                    f"{em(CE_FB, '🔍')} FB {sv_label}\n"
                    f"✅ {len(confirmed)} | ⚠️ {len(uncertain)} | ❌ {len(not_found_list)}"
                ),
                parse_mode=ParseMode.HTML
            )
            os.remove(tmp_path)


# ═══ FACEBOOK SERVER 3 — Parallel SMS Recovery ═══════════════════════════
_fb_s3_active = {}  # user_id -> True/False
_fb_s3_data = {}    # user_id -> {phone: {cuid, cp_id, name, ...}}
FB_S3_USER_LIMIT = 20
FB_S3_ADDUSER_LIMIT = 150
FB_S3_WORKERS = 10
FB_S3_SUBMIT_STAGGER = 1.0
FB_S3_DEFAULT_PW = "dika2007"

# Create table for FB passwords if not exists
try:
    cur.execute('''CREATE TABLE IF NOT EXISTS fb_passwords (
        user_id INTEGER PRIMARY KEY,
        password TEXT NOT NULL DEFAULT 'dika2007',
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
except:
    pass


def _get_fb_password(context, user_id: int) -> str:
    """Get user's custom FB password from DB or default."""
    try:
        cur.execute("SELECT password FROM fb_passwords WHERE user_id = ?", (user_id,))
        row = cur.fetchone()
        if row:
            return row[0]
    except:
        pass
    return FB_S3_DEFAULT_PW


def _set_fb_password(user_id: int, password: str):
    """Save user's FB password to DB."""
    try:
        cur.execute(
            "INSERT OR REPLACE INTO fb_passwords (user_id, password, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP)",
            (user_id, password))
        conn.commit()
    except:
        pass


def _reset_fb_password(user_id: int):
    """Reset user's FB password to default."""
    try:
        cur.execute("DELETE FROM fb_passwords WHERE user_id = ?", (user_id,))
        conn.commit()
    except:
        pass


