def _nokos_flag_em(alpha2: str, fallback: str = "🌎") -> str:
    """Custom flag emoji for /cek /trafic /nomor + OTP send.

    Primary: authoritative _FLAG dict (unique ID per country, from main bot).
    Fallback: legacy _NOKOS_FLAGS (some IDs duplicated, kept for coverage gaps).
    """
    if alpha2:
        a2 = alpha2.upper()
        entry = _FLAG.get(a2)
        if entry and entry[0]:
            return f'<tg-emoji emoji-id="{entry[0]}">{entry[1] or fallback}</tg-emoji>'
        eid = _NOKOS_FLAGS.get(a2)
        if eid:
            return f'<tg-emoji emoji-id="{eid}">{fallback}</tg-emoji>'
    # Final fallback — global default
    default = _FLAG.get('DEFAULT')
    if default and default[0]:
        return f'<tg-emoji emoji-id="{default[0]}">{default[1] or fallback}</tg-emoji>'
    return fallback


def _nokos_svc_em(service: str, fallback: str = "📱") -> str:
    eid = _NOKOS_SVC.get(service)
    return f'<tg-emoji emoji-id="{eid}">{fallback}</tg-emoji>' if eid else fallback


