async def ff_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/ff <uid> — Free Fire player profile lookup via Garena API."""
    user_id = update.effective_user.id
    args = context.args or []

    uid_str = args[0].strip() if args else "2167058509"
    if not uid_str.isdigit():
        await update.message.reply_text(
            _screen('FREE FIRE', (
                f"{em(CE_FF, '🎮')} <b>FREE FIRE LOOKUP</b>\n\n"
                f"  {em(E2, '❌')} UID harus berupa angka digit!\n"
                f"  Contoh: <code>/ff 2167058509</code>"
            ), 'Home › FreeFire › Lookup'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("Batal", callback_data=f"ff_cancel_{user_id}", style="danger"),
            ]]),
        )
        return

    uid = int(uid_str)
    sent_msg = await update.message.reply_text(
        _screen('FREE FIRE', (
            f"{em(CE_FF, '🎮')} <b>FREE FIRE KONTOL</b>\n\n"
            f"  {em(CE_LOADING, '🟠')} Memuat data UID <code>{uid}</code>..."
        ), 'Home › FreeFire › Kontol'),
        parse_mode=ParseMode.HTML,
    )

    def _fetch_ff():
        from faq._test_ff_live import (
            load_har_auth, make_uid_request, make_personal_show_request,
            make_stats_request, call_ff_api, load_items, iname, rk, ts,
        )
        headers = load_har_auth()
        if not headers:
            return None, "Auth header tidak ditemukan di HAR"

        load_items()

        # Call 1: GetAccountInfoByAccountID
        acc = call_ff_api("GetAccountInfoByAccountID", make_uid_request(uid), headers) or {}
        # Call 2: GetPlayerPersonalShow
        show = call_ff_api("GetPlayerPersonalShow", make_personal_show_request(uid), headers) or {}
        # Call 3: GetPlayerStats (BR)
        stats = call_ff_api("GetPlayerStats", make_stats_request(uid, 0), headers) or {}

        if not acc and not show:
            return None, "Gagal mengambil data dari server Garena"

        return (acc, show, stats, iname, rk, ts), None

    loop = asyncio.get_running_loop()
    res, err = await loop.run_in_executor(None, _fetch_ff)

    if err or not res:
        await sent_msg.edit_text(
            _screen('FREE FIRE', (
                f"{em(CE_FF, '🎮')} <b>FREE FIRE KONTOL</b>\n\n"
                f"  {em(E2, '❌')} <b>Gagal:</b> {err or 'Unknown error'}"
            ), 'Home › FreeFire › Kontol'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("Batal", callback_data=f"ff_cancel_{user_id}", style="danger"),
            ]]),
        )
        return

    acc, show, stats, iname, rk, ts = res

    # Extract account info
    nick = html.escape(str(acc.get('3') or show.get('1', {}).get('3') or 'Unknown'))
    region = html.escape(str(acc.get('5') or 'ID'))
    level = acc.get('6') or show.get('1', {}).get('6') or '?'
    exp = acc.get('7', 0)
    exp_str = f"{exp:,}" if isinstance(exp, int) and exp > 0 else str(exp)
    likes = acc.get('21') or show.get('1', {}).get('21') or 0
    likes_str = f"{likes:,}" if isinstance(likes, int) and likes > 0 else str(likes)

    br_rank = acc.get('14', '?')
    br_pts = acc.get('15', '?')
    cs_rank = acc.get('30', '?')
    cs_pts = acc.get('31', '?')

    head_pic_id = acc.get('12')
    head_pic_name = html.escape(iname(head_pic_id)) if head_pic_id else '-'
    pin_id = acc.get('33')
    pin_name = html.escape(iname(pin_id)) if pin_id else '-'

    season = acc.get('20', '?')
    created = ts(acc.get('44', 0)) if acc.get('44') else '-'
    last_login = ts(acc.get('24', 0)) if acc.get('24') else '-'
    version = html.escape(str(acc.get('50') or 'OB54'))

    # Extract Pet
    pet_obj = show.get('8', {}) if isinstance(show.get('8'), dict) else {}
    pet_id = pet_obj.get('1')
    pet_name = html.escape(iname(pet_id)) if pet_id else '-'
    pet_lv = pet_obj.get('3', '-')
    pet_skin_id = pet_obj.get('6')
    pet_skin_name = html.escape(iname(pet_skin_id)) if pet_skin_id else '-'
    pet_skill_id = pet_obj.get('9')
    pet_skill_name = html.escape(iname(pet_skill_id)) if pet_skill_id else '-'

    # Extract Clan & Social
    clan_obj = show.get('6', {}) if isinstance(show.get('6'), dict) else {}
    clan_name = html.escape(str(clan_obj.get('2') or acc.get('13') or '-'))
    clan_lv = clan_obj.get('4', '-')
    clan_mem = clan_obj.get('6', '-')
    clan_cap = clan_obj.get('5', '-')

    captain_obj = show.get('7', {}) if isinstance(show.get('7'), dict) else {}
    cap_nick = html.escape(str(captain_obj.get('3') or '-'))
    cap_uid = captain_obj.get('1', '-')

    social_obj = show.get('9', {}) if isinstance(show.get('9'), dict) else {}
    bio = html.escape(str(social_obj.get('9') or '-'))

    credit_obj = show.get('11', {}) if isinstance(show.get('11'), dict) else {}
    credit_score = credit_obj.get('1', '-')

    diamond_obj = show.get('10', {}) if isinstance(show.get('10'), dict) else {}
    diamond_cost = diamond_obj.get('1', '-')

    # Extract Battle Stats
    def _fmt_mode(m_obj):
        if not isinstance(m_obj, dict):
            return "0 games · 0 wins (0%) · 0 kills · K/D 0 · HS 0"
        g = m_obj.get('2', 0)
        w = m_obj.get('3', 0)
        k = m_obj.get('4', 0)
        wr = (w / g * 100) if g else 0
        det = m_obj.get('5', {}) if isinstance(m_obj.get('5'), dict) else {}
        d = det.get('1', 0)
        kd = (k / d) if d else 0
        hs = det.get('11', 0)
        return f"<b>{g:,}</b> games · <b>{w:,}</b> wins ({wr:.1f}%) · <b>{k:,}</b> kills · K/D <b>{kd:.2f}</b> · HS <b>{hs:,}</b>"

    solo_str = _fmt_mode(stats.get('1'))
    duo_str = _fmt_mode(stats.get('2'))
    squad_str = _fmt_mode(stats.get('3'))

    # Format output (no emojis in row labels per user request)
    body = (
        f"{em(CE_FF, '🎮')} <b>PLAYER PROFILE</b>\n\n"
        f"  Nickname: <b>{nick}</b>\n"
        f"  Region: <b>{region}</b>\n"
        f"  Level: <b>{level}</b> ({exp_str} EXP)\n"
        f"  Likes: <b>{likes_str}</b>\n"
        f"  BR Rank: <b>{rk(br_rank)}</b> ({br_pts} pts)\n"
        f"  CS Rank: <b>{rk(cs_rank)}</b> ({cs_pts} pts)\n"
        f"  Head Pic: <b>{head_pic_name} [{head_pic_id or '-'}]</b>\n"
        f"  PIN: <b>{pin_name} [{pin_id or '-'}]</b>\n"
        f"  Created: <b>{created}</b>\n"
        f"  Last Login: <b>{last_login}</b>\n"
        f"  Version: <b>{version}</b> · Season <b>{season}</b>\n\n"
        f"  <b>PET</b>\n"
        f"  • Pet: <b>{pet_name} [{pet_id or '-'}]</b> (Lv {pet_lv})\n"
        f"  • Skin: <b>{pet_skin_name} [{pet_skin_id or '-'}]</b>\n"
        f"  • Skill: <b>{pet_skill_name} [{pet_skill_id or '-'}]</b>\n\n"
        f"  <b>CLAN & SOCIAL</b>\n"
        f"  • Clan: <b>{clan_name}</b> (Lv{clan_lv}, {clan_mem}/{clan_cap})\n"
        f"  • Captain: <b>{cap_nick}</b> (UID {cap_uid})\n"
        f"  • Bio: <i>{bio}</i>\n"
        f"  • Credit Score: <b>{credit_score}/100</b>\n\n"
      #  f"  • Diamond Cost: <b>{diamond_cost}</b>\n\n"
        f"  <b>BATTLE STATS (BR)</b>\n"
        f"  • Solo: {solo_str}\n"
        f"  • Duo: {duo_str}\n"
        f"  • Squad: {squad_str}"
    )

    # Check Telegram limit (4096 chars). If too long, send text file.
    screen_text = _screen('FREE FIRE', body, 'Home › FreeFire › Hasil Kontolmu')
    if len(screen_text) > 4000:
        import io
        clean_file_text = (
            f"FREE FIRE PLAYER PROFILE — UID {uid}\n"
            f"========================================\n"
            f"Nickname     : {nick}\n"
            f"Region       : {region}\n"
            f"Level        : {level} ({exp_str} EXP)\n"
            f"Likes        : {likes_str}\n"
            f"BR Rank      : {rk(br_rank)} ({br_pts} pts)\n"
            f"CS Rank      : {rk(cs_rank)} ({cs_pts} pts)\n"
            f"Head Pic     : {head_pic_name} [{head_pic_id or '-'}]\n"
            f"PIN          : {pin_name} [{pin_id or '-'}]\n"
            f"Created      : {created}\n"
            f"Last Login   : {last_login}\n"
            f"Version      : {version} · Season {season}\n\n"
            f"PET:\n"
            f"  Pet        : {pet_name} [{pet_id or '-'}] (Lv {pet_lv})\n"
            f"  Skin       : {pet_skin_name} [{pet_skin_id or '-'}]\n"
            f"  Skill      : {pet_skill_name} [{pet_skill_id or '-'}]\n\n"
            f"CLAN & SOCIAL:\n"
            f"  Clan       : {clan_name} (Lv{clan_lv}, {clan_mem}/{clan_cap})\n"
            f"  Captain    : {cap_nick} (UID {cap_uid})\n"
            f"  Bio        : {bio}\n"
            f"  CreditScore: {credit_score}/100\n"
        #    f"  DiamondCost: {diamond_cost}\n\n"
            f"BATTLE STATS (BR):\n"
            f"  Solo       : {solo_str.replace('<b>','').replace('</b>','')}\n"
            f"  Duo        : {duo_str.replace('<b>','').replace('</b>','')}\n"
            f"  Squad      : {squad_str.replace('<b>','').replace('</b>','')}\n"
        )
        file_obj = io.BytesIO(clean_file_text.encode('utf-8'))
        file_obj.name = f"ff_profile_{uid}.txt"
        await update.message.reply_document(
            document=file_obj,
            caption=f"Hasil lookup FF UID {uid} (terlalu panjang untuk chat).",
        )
        try:
            await sent_msg.delete()
        except Exception:
            pass
        return

    await sent_msg.edit_text(
        screen_text,
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("Hapus", callback_data=f"ff_cancel_{user_id}", style="danger"),
        ]]),
    )


async def nokos_clear_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/nokos_clear — clear active nokos session."""
    user_id = update.effective_user.id
    if user_id in _nokos_pages:
        _nokos_pages.pop(user_id, None)
        _nokos_watchers.pop(user_id, None)
        await update.message.reply_text(
            _screen('NOKOS', f"{EMOJI['SUCCESS']} Session dihapus. Silakan /nokos lagi."),
            parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(
            _screen('NOKOS', f"{em(CE_PHONE, '📞')} Tidak ada session aktif."),
            parse_mode=ParseMode.HTML)


async def nokos_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/nokos <prefix|prefix|...> [count] — get virtual numbers (bulk prefix supported)."""
    user_id = update.effective_user.id
    args = context.args or []

    if len(args) < 1:
        await update.message.reply_text(
            _screen('NOKOS', (
                f"{em(CE_PHONE, '📞')} <b>NOKOS — Virtual Numbers</b>\n\n"
                f"  {em(CE_HELP, '💡')} <b>Penggunaan:</b>\n"
                f"  <code>/nokos &lt;prefix&gt; &lt;jumlah&gt;</code>\n\n"
                f"  <b>Bulk prefix (pisah pakai |):</b>\n"
                f"  <code>/nokos 99210000|99211223 5</code>\n"
                f"  <code>/nokos 628582|628583|628584 3</code>\n\n"
                f"  <b>Contoh single:</b>\n"
                f"  <code>/nokos 99211111 10</code>\n"
                f"  <code>/nokos 628582530 5</code>\n"
                f"  <code>/nokos 23350 3</code>\n\n"
                f"  {em(CE_GLOBE, '🌎')} Prefix = kode negara + awalan nomor"
            ), 'Home › Nokos'),
            parse_mode=ParseMode.HTML)
        return

    # Parse prefixes: support | separator dan multi-arg sebelum count
    raw_prefix = args[0]
    # Cek count di arg terakhir
    count = 10
    if len(args) > 1 and args[-1].isdigit():
        count = int(args[-1])
        # Gabung semua args kecuali count terakhir jadi prefix string
        raw_prefix = " ".join(args[:-1])
    elif len(args) > 1:
        raw_prefix = " ".join(args)

    # Split by | atau spasi, extract digit-only prefixes
    prefixes = [re.sub(r'[^\d]', '', p) for p in re.split(r'[|\s]+', raw_prefix)]
    prefixes = [p for p in prefixes if p]  # buang kosong
    if not prefixes:
        await update.message.reply_text(
            _screen('NOKOS', f"{EMOJI['FAILED']} Prefix tidak valid."),
            parse_mode=ParseMode.HTML)
        return

    count = min(count, 50)
    count_per = max(1, count)  # count per prefix

    # Check if user already has active session
    if user_id in _nokos_pages and _nokos_pages[user_id].get("numbers"):
        await update.message.reply_text(
            _screen('NOKOS', (
                f"{EMOJI['FAILED']} <b>Session aktif!</b>\n\n"
                f"  Hapus nomor lama dulu sebelum request baru.\n"
                f"  Tekan tombol <b>Hapus</b> di pesan sebelumnya,\n"
                f"  atau kirim /nokos_clear"
            ), 'Home › Nokos'),
            parse_mode=ParseMode.HTML)
        return

    # Show loading
    total_est = count_per * len(prefixes)
    prefix_lines = "\n".join(f"    <code>{p}</code>" for p in prefixes)
    msg = await update.message.reply_text(
        _screen('NOKOS', (
            f"{em(CE_PHONE, '📞')} <b>NOKOS — Bulk Request</b>\n\n"
            f"  {em(CE_LOADING, '🟠')} Mengambil nomor...\n\n"
            f"  {em(CE_SIGNAL, '📡')} Prefix: <b>{len(prefixes)}</b>\n"
            f"{prefix_lines}\n\n"
            f"  {em(CE_PHONE, '📞')} Target: ~<b>{total_est}</b> nomor ({count_per}/prefix)"
        ), 'Home › Nokos › Proses'),
        parse_mode=ParseMode.HTML)

    # Fetch parallel tiap prefix (cepat)
    tasks = [get_numbers(p, count_per) for p in prefixes]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    numbers = []
    for r in results:
        if isinstance(r, list):
            numbers.extend(r)

    if not numbers:
        await msg.edit_text(
            _screen('NOKOS', f"{EMOJI['FAILED']} Gagal mengambil nomor. Coba prefix lain."),
            parse_mode=ParseMode.HTML)
        return

    # Get country info from first number
    c_name, c_flag, c_alpha2 = get_country_info(numbers[0].no_plus)

    # Build pages (6 per page) — always inline, no txt file
    PAGE_SIZE = 6
    pages = [numbers[i:i+PAGE_SIZE] for i in range(0, len(numbers), PAGE_SIZE)]
    page_idx = 0
    _nokos_pages[user_id] = {"numbers": numbers, "pages": pages, "page": 0, "prefix": "|".join(prefixes)}
    # Register for OTP watching
    _nokos_watchers[user_id] = set(n.no_plus for n in numbers)

    # Format page
    body = _nokos_format_page(pages[0], page_idx, len(pages), c_name, c_flag, c_alpha2, len(numbers))
    kb = _nokos_build_kb(pages[0], user_id, page_idx, len(pages))

    await msg.edit_text(body, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(kb))


def _nokos_format_page(nums, page_idx, total_pages, c_name, c_flag, c_alpha2, total_nums):
    flag_em = _nokos_flag_em(c_alpha2, c_flag)
    lines = [
        f"{flag_em} <b>NOKOS — {c_name}</b>",
        "",
    ]
    for i, n in enumerate(nums, start=page_idx * 6 + 1):
        lines.append(f"  {i}. <code>+{n.no_plus}</code>")
    lines.append(f"\n{em(CE_LIVE, '📡')} {total_nums} nomor dialokasi")
    if total_pages > 1:
        lines.append(f"📄 Halaman {page_idx+1}/{total_pages}")
    return _screen('NOKOS', '\n'.join(lines), f'Home › Nokos › {c_name}')


def _nokos_build_kb(nums, user_id, page_idx, total_pages):
    kb = []
    # Copy buttons (2 per row) — show FULL number
    for i in range(0, len(nums), 2):
        row = []
        for n in nums[i:i+2]:
            row.append(InlineKeyboardButton(
                f"+{n.no_plus}",
                copy_text=CopyTextButton(text=f"+{n.no_plus}"),
                api_kwargs={"style": "primary", "icon_custom_emoji_id": CE_PHONE},
            ))
        kb.append(row)
    # Copy Semua button — split into chunks if text > 256
    state = _nokos_pages.get(user_id)
    if state:
        all_nums = [f"+{n.no_plus}" for n in state["numbers"]]
        all_text = '\n'.join(all_nums)
        if len(all_text) <= 256:
            kb.append([InlineKeyboardButton(
                "Copy Semua",
                copy_text=CopyTextButton(text=all_text),
                api_kwargs={"style": "success", "icon_custom_emoji_id": CE_CHECK},
            )])
        else:
            # Split into chunks that fit 256 chars each
            chunks = []
            current = []
            current_len = 0
            for num in all_nums:
                add_len = len(num) + (1 if current else 0)  # +1 for \n
                if current_len + add_len > 256:
                    chunks.append(current)
                    current = [num]
                    current_len = len(num)
                else:
                    current.append(num)
                    current_len += add_len
            if current:
                chunks.append(current)
            row = []
            start = 1
            for chunk in chunks:
                end = start + len(chunk) - 1
                txt = '\n'.join(chunk)
                row.append(InlineKeyboardButton(
                    f"Copy {start}-{end}",
                    copy_text=CopyTextButton(text=txt),
                    api_kwargs={"style": "success", "icon_custom_emoji_id": CE_CHECK},
                ))
                start = end + 1
            kb.append(row)
    # Control row
    ctrl = []
    if page_idx > 0:
        ctrl.append(InlineKeyboardButton("◂", callback_data=f"nk_prev_{user_id}", style="primary"))
    ctrl.append(InlineKeyboardButton("Hapus", callback_data=f"nk_del_{user_id}", style="danger"))
    ctrl.append(InlineKeyboardButton("Check OTP", callback_data=f"nk_check_{user_id}", style="primary"))
    if page_idx < total_pages - 1:
        ctrl.append(InlineKeyboardButton("▸", callback_data=f"nk_next_{user_id}", style="primary"))
    kb.append(ctrl)
    return kb


async def check_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/check <nomor> — check OTP for a number."""
    user_id = update.effective_user.id
    args = context.args or []

    if not args:
        await update.message.reply_text(
            _screen('CHECK OTP', (
                f"{em(CE_CHECK, '✅')} <b>CHECK OTP</b>\n\n"
                f"  {em(CE_HELP, '💡')} <b>Penggunaan:</b>\n"
                f"  <code>/check &lt;nomor&gt;</code>\n\n"
                f"  <b>Contoh:</b>\n"
                f"  <code>/check 992111111286</code>"
            ), 'Home › Check OTP'),
            parse_mode=ParseMode.HTML)
        return

    number = re.sub(r'[^\d]', '', args[0])
    c_name, c_flag, c_alpha2 = get_country_info(number)

    msg = await update.message.reply_text(
        _screen('CHECK OTP', f"{em(CE_LOADING, '🟠')} Mengecek OTP untuk +{number}..."),
        parse_mode=ParseMode.HTML)

    otps = await get_success_otps()
    found = [o for o in otps if number in o.get("number", "")]

    if found:
        otp_data = found[0]
        otp_msg = otp_data.get("message", "")
        otp_code = "?"
        m = re.search(r'(\d{3}-\d{3})', otp_msg)
        if m:
            otp_code = m.group(1).replace('-', '')
        else:
            m2 = re.search(r'(?:code|kode|is|:)\s*(\d{4,8})', otp_msg, re.I)
            if m2:
                otp_code = m2.group(1)
            else:
                m3 = re.search(r'\b(\d{4,8})\b', otp_msg)
                if m3:
                    otp_code = m3.group(1)

        ts = otp_data.get("time", 0)
        dt = datetime.fromtimestamp(ts/1000).strftime("%H:%M:%S") if ts else "?"
        svc = detect_service(otp_msg)

        flag_em = _nokos_flag_em(c_alpha2, c_flag)
        svc_em = _nokos_svc_em(svc)

        body = (
            f"{flag_em} <b>CHECK OTP — +{number}</b>\n\n"
            f"  {em(CE_CHECK, '✅')} <b>OTP Ditemukan!</b>\n\n"
            f"  {svc_em} Service: <b>{svc}</b>\n"
            f"  {em('5256248974767046755', '🔒')} Code: <code>{otp_code}</code>\n"
            f"  {em(CE_DETAIL_MSG, '💬')} <i>{html.escape(otp_msg[:80])}</i>\n"
            f"  {em(CE_WAKTU, '⏱')} {dt}"
        )
        kb = [[
            InlineKeyboardButton(
                f"{otp_code}", copy_text=CopyTextButton(text=otp_code),
                api_kwargs={"style": "success", "icon_custom_emoji_id": CE_CHECK}),
            InlineKeyboardButton(
                "Refresh", callback_data=f"nk_refresh_{user_id}_{number}",
                api_kwargs={"style": "primary", "icon_custom_emoji_id": CE_LOADING}),
        ]]
        await msg.edit_text(
            _screen('CHECK OTP', body, f'Home › Check › {c_alpha2}'),
            parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(kb))
    else:
        body = (
            f"{_nokos_flag_em(c_alpha2, c_flag)} <b>CHECK OTP — +{number}</b>\n\n"
            f"  {em(CE_LOADING, '⏳')} <b>Belum ada OTP</b>\n"
            f"  Tunggu beberapa saat...\n"
        )
        kb = [[InlineKeyboardButton(
            "Refresh", callback_data=f"nk_refresh_{user_id}_{number}",
            api_kwargs={"style": "primary", "icon_custom_emoji_id": CE_LOADING})]]
        await msg.edit_text(
            _screen('CHECK OTP', body, f'Home › Check › {c_alpha2}'),
            parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(kb))


async def trafic_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """/trafic — show top active traffic."""
    msg = await update.message.reply_text(
        _screen('TRAFFIC', f"{em(CE_LOADING, '🟠')} Memuat live traffic..."),
        parse_mode=ParseMode.HTML)

    # Combine BOTH endpoints for complete picture
    traffic = await get_traffic()  # console (Facebook/IG)
    otps = await get_success_otps()  # success-otp (WhatsApp etc)

    if not traffic and not otps:
        await msg.edit_text(
            _screen('TRAFFIC', f"{EMOJI['FAILED']} Gagal memuat traffic."),
            parse_mode=ParseMode.HTML)
        return

    from collections import Counter
    counter = Counter()

    # From console
    for t in traffic:
        key = (t.alpha2, t.flag, t.service)
        counter[key] += 1

    # From success-otp
    for o in otps:
        num = o.get("number", "")
        msg_text = o.get("message", "")
        svc = detect_service(msg_text)
        c_name, c_flag, c_alpha2 = get_country_info(num)
        key = (c_alpha2, c_flag, svc)
        counter[key] += 1

    top = counter.most_common(10)
    lines = [
        f"{em(CE_LIVE, '📡')} <b>LIVE TRAFFIC — Top Services</b>",
        "",
    ]
    for (alpha2, flag, svc), cnt in top:
        flag_em = _nokos_flag_em(alpha2, flag)
        svc_em = _nokos_svc_em(svc)
        lines.append(f"  {flag_em} {alpha2}  {svc_em} <b>{svc}</b>  ({cnt} aktif)")

    lines.append(f"\n{em(CE_WAKTU, '⏱')} Updated: {datetime.now().strftime('%H:%M:%S')}")
    await msg.edit_text(
        _screen('TRAFFIC', '\n'.join(lines), 'Home › Traffic'),
        parse_mode=ParseMode.HTML)


# Nokos OTP auto-forward — background polling
_nokos_otp_seen = set()  # track sent OTP IDs
_nokos_watchers = {}  # user_id -> set of numbers being watched


def _nokos_format_otp_msg(number, otp_code, message, svc, c_alpha2, c_flag):
    """Format OTP notification like main1.py premium style."""
    flag_em = _nokos_flag_em(c_alpha2, c_flag)
    svc_em = _nokos_svc_em(svc)
    separator = f'<tg-emoji emoji-id="6217304154138742190">✨</tg-emoji>'
    masked = f"+{number[:4]}{separator}{number[-4:]}"
    svc_short = {"WhatsApp": "WS", "Telegram": "TG", "Facebook": "FB", "Instagram": "IG",
                 "Google": "GO", "TikTok": "TT", "Twitter": "TW", "Discord": "DC"}.get(svc, "OT")
    text = f"<b>{flag_em} {c_alpha2} {svc_em} {masked} {svc_short}</b>"
    return text


async def _nokos_otp_poll(app):
    """Background task: poll success-otp and forward to watchers."""
    while True:
        try:
            if not _nokos_watchers:
                await asyncio.sleep(8)
                continue
            otps = await get_success_otps()
            for o in otps:
                otp_id = o.get("otp_id", "")
                if otp_id in _nokos_otp_seen:
                    continue
                num = o.get("number", "").replace("+", "")
                msg_text = o.get("message", "")
                # Check if any watcher has this number
                for uid, nums_set in list(_nokos_watchers.items()):
                    if num in nums_set:
                        _nokos_otp_seen.add(otp_id)
                        # Extract OTP code
                        otp_code = "?"
                        m = re.search(r'(\d{3}-\d{3})', msg_text)
                        if m:
                            otp_code = m.group(1).replace('-', '')
                        else:
                            m2 = re.search(r'(?:code|kode|is|:)\s*(\d{4,8})', msg_text, re.I)
                            if m2: otp_code = m2.group(1)
                            else:
                                m3 = re.search(r'\b(\d{4,8})\b', msg_text)
                                if m3: otp_code = m3.group(1)
                        svc = detect_service(msg_text)
                        c_name, c_flag, c_alpha2 = get_country_info(num)
                        text = _nokos_format_otp_msg(num, otp_code, msg_text, svc, c_alpha2, c_flag)
                        kb = [
                            [InlineKeyboardButton(
                                f"{otp_code}",
                                copy_text=CopyTextButton(text=otp_code),
                                api_kwargs={"style": "success", "icon_custom_emoji_id": CE_CHECK},
                            )],
                            [InlineKeyboardButton(
                                "Message",
                                copy_text=CopyTextButton(text=msg_text),
                                api_kwargs={"style": "primary", "icon_custom_emoji_id": CE_PHONE},
                            )],
                        ]
                        try:
                            await app.bot.send_message(
                                chat_id=uid, text=text,
                                parse_mode=ParseMode.HTML,
                                reply_markup=InlineKeyboardMarkup(kb))
                        except Exception:
                            pass
                        break
        except Exception:
            pass
        await asyncio.sleep(6)


