def _get_gmail_config(user_id: int) -> GmailConfig:
    """Get user's Gmail config from DB."""
    try:
        cur.execute("SELECT first_name, last_name, password, birthday FROM gmail_settings WHERE user_id = ?", (user_id,))
        row = cur.fetchone()
        if row:
            return GmailConfig(first_name=row[0], last_name=row[1], password=row[2], birthday=row[3])
    except:
        pass
    return GmailConfig()


def _set_gmail_setting(user_id: int, **kwargs):
    """Update Gmail settings."""
    try:
        cur.execute("INSERT OR IGNORE INTO gmail_settings (user_id) VALUES (?)", (user_id,))
        for key, val in kwargs.items():
            cur.execute(f"UPDATE gmail_settings SET {key} = ?, updated_at = CURRENT_TIMESTAMP WHERE user_id = ?", (val, user_id))
        conn.commit()
    except:
        pass


