async def mail_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Generate temp .edu email, poll inbox, show code inline."""
    user_id = update.effective_user.id
    if not MAIL_OK:
        await update.message.reply_text(
            _screen('MAIL', f"{EMOJI['FAILED']} Module mail_server tidak tersedia."),
            parse_mode=ParseMode.HTML)
        return

    # Always destroy old session and create new
    if user_id in _mail_sessions:
        old = _mail_sessions[user_id]
        if old.get("task") and not old["task"].done():
            old["task"].cancel()
        await _mail_mod.close_session(old.get("session"))
        # Try delete old message
        try:
            old_msg = old.get("msg")
            if old_msg:
                await old_msg.delete()
        except Exception:
            pass
        del _mail_sessions[user_id]

    # Show instant placeholder
    placeholder = await update.message.reply_text(
        _screen('MAIL',
            f"{em(CE_LOADING, '⏳')} <b>Membuat temp Gmail...</b>\n"
            f"<i>Tunggu sebentar (2-5 detik)...</i>",
            'Home › Mail'),
        parse_mode=ParseMode.HTML)

    try:
        session = await create_temp_gmail()
    except Exception as e:
        await placeholder.edit_text(
            _screen('MAIL', f"{EMOJI['FAILED']} Gagal buat email: {e}"),
            parse_mode=ParseMode.HTML)
        return

    body = _mail_waiting_body(session)
    kb = _mail_waiting_kb(user_id, session.email)
    try:
        await placeholder.edit_text(
            _screen('MAIL', body, 'Home › Mail'),
            parse_mode=ParseMode.HTML,
            reply_markup=kb)
        msg = placeholder
    except Exception:
        msg = await update.message.reply_text(
            _screen('MAIL', body, 'Home › Mail'),
            parse_mode=ParseMode.HTML,
            reply_markup=kb)

    chat_id = update.effective_chat.id
    task = asyncio.create_task(_mail_poll_task(user_id, session, msg, chat_id, context))
    _mail_sessions[user_id] = {"session": session, "task": task, "msg": msg, "chat_id": chat_id}


async def _mail_poll_task(user_id, session, msg, chat_id, context):
    """Background polling via GetEduMail API."""
    interval = 5
    consecutive_errors = 0
    try:
        while True:
            try:
                msgs = await poll_once(session)
                if msgs:
                    await _mail_show_result(user_id, session, msgs, msg, chat_id, context)
                    return
                consecutive_errors = 0  # reset on success
            except asyncio.CancelledError:
                raise
            except Exception as e:
                consecutive_errors += 1
                logging.warning(f"[mail_poll] transient error #{consecutive_errors}: {e}")
                # Only give up after 20 consecutive errors (100s of failures)
                if consecutive_errors >= 20:
                    logging.error(f"[mail_poll] giving up after 20 errors")
                    return
            await asyncio.sleep(interval)
    except asyncio.CancelledError:
        pass
    finally:
        entry = _mail_sessions.get(user_id)
        if entry and entry.get("task") is asyncio.current_task():
            _mail_sessions.pop(user_id, None)
        if session.active:
            try:
                await _mail_mod.close_session(session)
            except Exception:
                pass


async def _mail_stop_task(user_id):
    entry = _mail_sessions.get(user_id)
    if not entry:
        return
    task = entry.get("task")
    if task and not task.done():
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass


async def _mail_show_result(user_id, session, messages, msg, chat_id, context):
    """Show received email(s) with code inline."""
    await _mail_stop_task(user_id)
    lines = []
    kb_rows = []
    for i, m in enumerate(messages):
        service = detect_service(m.content)
        code = m.code or extract_code(m.content) or extract_code(m.subject)
        lines.append(
            f"  {em(CE_GMAIL, '✉️')} <b>Email #{i+1}</b>\n"
            f"  {em(CE_DETAIL_NAME, '👤')} <b>From:</b> {html.escape(m.sender_name or m.sender or 'Unknown')}\n"
            f"  {em(CE_DETAIL_MSG, '✍️')} <b>Subject:</b> {html.escape(m.subject or 'No subject')}\n"
            f"  {em(CE_PLATFORM, '🌍')} <b>Service:</b> {service}"
        )
        if code:
            lines.append(f"  {em(CE_CHECK, '✅')} <b>Code:</b> <code>{code}</code>")
            kb_rows.append([InlineKeyboardButton(
                f"Copy Code: {code}",
                copy_text=CopyTextButton(text=code),
                api_kwargs={"style": "success", "icon_custom_emoji_id": CE_CHECK},
            )])
        # Full message in blockquote
        content_short = (m.content or "")[:200]
        if content_short:
            lines.append(f"\n  <blockquote>{html.escape(content_short)}</blockquote>")

    # Copy email button
    kb_rows.append([InlineKeyboardButton(
        "Copy Email",
        copy_text=CopyTextButton(text=session.email),
        api_kwargs={"style": "primary", "icon_custom_emoji_id": CE_GMAIL},
    )])

    body = (
        f"{em(CE_GMAIL, '✉️')} <b>TEMP GMAIL — EMAIL MASUK!</b>\n\n"
        + '\n'.join(lines)
    )
    # DELETE old placeholder message + send fresh NEW message
    try:
        if msg:
            await msg.delete()
    except Exception:
        pass
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=_screen('MAIL', body, 'Home › Mail › Result'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup(kb_rows))
    except Exception as e:
        logging.error(f"[mail_show_result] failed to send: {e}")
    # Cleanup session
    try:
        await _mail_mod.close_session(session)
    except Exception:
        pass
    _mail_sessions.pop(user_id, None)


