def _plain_table(rows):
    """Format tabel sederhana untuk Telegram HTML <pre>."""
    width = max((len(label) for label, _ in rows), default=0)
    return "\n".join(f"{label.ljust(width)} : {value}" for label, value in rows)


def _plain_screen(title, body, breadcrumb=""):
    """Layar blockquote tanpa custom emoji untuk fitur baru."""
    breadcrumb_line = f"\n<i>{html.escape(breadcrumb)}</i>" if breadcrumb else ""
    inner = (
        f"<b>{html.escape(title)}</b>{breadcrumb_line}\n"
        f"{_BAR}\n{body}\n\n"
        f"{_BAR}\n<i>Powered by </i><b>DikZz</b>"
    )
    return _quote(inner)


def _mask_fix_phone(phone):
    """Nomor lengkap tanpa sensor untuk log grup: +6285xxxxxxxx."""
    digits = re.sub(r"\D", "", str(phone or ""))
    return f"+{digits}" if digits else "-"


def _new_fix_banding_id():
    return f"LRFM{int(time.time() * 1000)}"


def _fmt_otp_wait(seconds) -> str:
    """Format detik jadi 'X jam Y menit (Z detik)'; -1 = method dimatikan server."""
    try:
        d = int(seconds)
    except (TypeError, ValueError):
        return "-"
    if d < 0:
        return "tidak tersedia"
    if d == 0:
        return "0 (boleh minta kode sekarang)"
    return f"{d // 3600} jam {(d % 3600) // 60} menit ({d} detik)"


# ── npm auto-install buat code/cek_wait.js (curve25519-js, phone) ────────────
_NPM_READY = None                # True kalau node_modules udah oke (cache per proses)
_NPM_LOCK = asyncio.Lock()       # cuman satu npm install jalan dalam satu waktu
_NPM_FAILED_AT = 0.0             # cooldown retry 5 mnt kalau npm install gagal


async def _ensure_npm_deps() -> tuple[bool, str]:
    """Pastiin node_modules code/ tersedia. Kalau gak ada → npm install otomatis.

    Return (ok, pesan). Sukses di-cache; gagal di-retry lagi setelah 5 menit.
    """
    global _NPM_READY, _NPM_FAILED_AT
    if _NPM_READY:
        return True, "ok"
    code_dir = BASE_DIR / "code"
    if not code_dir.exists():
        return False, f"folder code/ tidak ditemukan ({code_dir})"
    # udah terinstall? (node_modules dua-duanya ada)
    if (code_dir / "node_modules" / "curve25519-js").exists() and \
       (code_dir / "node_modules" / "phone").exists():
        _NPM_READY = True
        return True, "ok"
    # baru gagal barusan → tunggu 5 mnt sebelum nyoba install lagi
    if _NPM_FAILED_AT and (time.time() - _NPM_FAILED_AT) < 300:
        return False, "npm install sebelumnya gagal — coba lagi beberapa menit"
    if not (code_dir / "package.json").exists():
        return False, "code/package.json tidak ditemukan — upload folder code/ lengkap"
    async with _NPM_LOCK:
        # double-check setelah dapet lock (mungkin task lain udah install)
        if (code_dir / "node_modules" / "curve25519-js").exists() and \
           (code_dir / "node_modules" / "phone").exists():
            _NPM_READY = True
            return True, "ok"
        # npm di Windows = npm.cmd; di Linux = npm. Pakai shell biar PATH kebaca.
        try:
            proc = await asyncio.create_subprocess_shell(
                "npm install --production --no-audit --no-fund",
                cwd=str(code_dir),
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.STDOUT,
            )
            stdout, _ = await asyncio.wait_for(proc.communicate(), timeout=300)
            tail = (stdout or b"").decode("utf-8", "replace")[-300:]
            if proc.returncode == 0:
                _NPM_READY = True
                return True, "ok"
            _NPM_FAILED_AT = time.time()
            return False, f"npm install gagal (exit {proc.returncode}): {tail}"
        except FileNotFoundError:
            _NPM_FAILED_AT = time.time()
            return False, "npm tidak tersedia di server — install Node.js + npm"
        except asyncio.TimeoutError:
            _NPM_FAILED_AT = time.time()
            return False, "npm install timeout (300 dtk)"
        except Exception as e:
            _NPM_FAILED_AT = time.time()
            return False, f"npm install error: {type(e).__name__}: {e}"


# ── Detect OTP wait via API (primary) — api.makluxnxx.my.id ──────────────────
_OTP_DETECT_API = "https://api.makluxnxx.my.id/v1/tools/detect-otp-whatsapp"
_OTP_DETECT_TIMEOUT = 25


def _fmt_otp_wait_human(human: str, seconds) -> str:
    """Gabungin human label dari API; kalau ada detik, tambahin '(N detik)'."""
    h = str(human or "").strip()
    try:
        s = int(seconds)
    except (TypeError, ValueError):
        return h or "-"
    if s < 0:
        return h or "tidak tersedia"
    if s == 0:
        return h or "0 (boleh minta kode sekarang)"
    if h:
        return f"{h} ({s} detik)"
    return _fmt_otp_wait(s)


async def _detect_otp_wait_api(nomor_clean: str, method: str = "wa_old") -> dict:
    """Cek wait nomor via API detect-otp-whatsapp (tanpa node/npm).

    Return format sama kayak _detect_otp_wait (node) biar caller gak perlu bedah.
    ok=False kalau blocked / API error. data = hasil mentah API.
    """
    out = {"ok": False, "data": None, "sms_wait": None, "sms_wait_fmt": None,
           "voice_wait": None, "voice_wait_fmt": None,
           "retry_after": None, "retry_after_fmt": None,
           "raw": None, "error": None}
    digits = re.sub(r"\D", "", str(nomor_clean or ""))
    if not digits:
        out["error"] = "nomor tidak valid"
        return out
    method = str(method or "wa_old").strip().lower() or "wa_old"
    try:
        async with httpx.AsyncClient(timeout=_OTP_DETECT_TIMEOUT) as client:
            r = await client.get(_OTP_DETECT_API, params={
                "number": digits, "method": method, "proxy_mode": "direct", "raw": "false"})
        out["raw"] = r.text
        j = r.json()
        if not isinstance(j, dict) or not j.get("status"):
            out["error"] = f"API error (HTTP {r.status_code})"
            return out
        res = j.get("result") or {}
        out["data"] = res
        cd = res.get("cooldown") or {}
        sms = (cd.get("sms") or {}).get("seconds")
        if sms is None and not res.get("blocked"):
            out["error"] = f"gak bisa ke-detect ({res.get('reason') or 'no sms cooldown'})"
            return out
        if sms is None:
            out["error"] = f"gak bisa ke-detect (blocked)"
            return out
        out["ok"] = True
        out["sms_wait"] = sms
        out["sms_wait_fmt"] = _fmt_otp_wait_human((cd.get("sms") or {}).get("human"), sms)
        voice = (cd.get("voice") or {}).get("seconds")
        out["voice_wait"] = voice
        out["voice_wait_fmt"] = _fmt_otp_wait_human((cd.get("voice") or {}).get("human"), voice)
        ra = cd.get("retry_after")
        if isinstance(ra, dict):
            out["retry_after"] = ra.get("seconds")
            out["retry_after_fmt"] = _fmt_otp_wait_human(ra.get("human"), ra.get("seconds"))
    except httpx.HTTPError as e:
        out["error"] = f"API request gagal: {type(e).__name__}"
    except ValueError:
        out["error"] = "respons API bukan JSON"
    except Exception as e:
        out["error"] = f"{type(e).__name__}: {e}"
    return out


async def _detect_otp_wait(nomor_clean: str, method: str = "wa_old") -> dict:
    """Cek wait nomor: API detect-otp-whatsapp (primary) → node code/cek_wait.js (fallback).

    Return: {ok, data, sms_wait, sms_wait_fmt, voice_wait, voice_wait_fmt,
             retry_after, retry_after_fmt, raw, error}
    ok=False kalau nomor blocked / request gagal. Kalau `data` ada tapi tanpa
    sms_wait (blocked) → data tetap dibalikin buat alasan.
    """
    # ── PRIMARY: API (gak butuh node/npm) ──
    out = await _detect_otp_wait_api(nomor_clean, method)
    if out.get("ok"):
        return out

    # ── FALLBACK: node code/cek_wait.js (kalau API down) ──
    api_err = out.get("error") or ""
    out = {"ok": False, "data": None, "sms_wait": None, "sms_wait_fmt": None,
           "voice_wait": None, "voice_wait_fmt": None,
           "retry_after": None, "retry_after_fmt": None,
           "raw": None, "error": None}
    script = BASE_DIR / "code" / "cek_wait.js"
    if not script.exists():
        out["error"] = f"API gagal ({api_err[:80]}) dan script cek_wait.js tidak ditemukan"
        return out
    # pastiin node_modules (curve25519-js, phone) tersedia — auto npm install
    npm_ok, npm_msg = await _ensure_npm_deps()
    if not npm_ok:
        out["error"] = f"API gagal ({api_err[:80]}) dan {npm_msg}"
        return out
    digits = re.sub(r"\D", "", str(nomor_clean or ""))
    if not digits:
        out["error"] = "nomor tidak valid"
        return out
    method = str(method or "wa_old").strip().lower() or "wa_old"
    try:
        proc = await asyncio.create_subprocess_exec(
            "node", str(script), f"+{digits}", method,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=40)
        text = (stdout or b"").decode("utf-8", "replace")
        out["raw"] = text
        # Respons JSON ada setelah baris 'Respons:' — bisa diakhiri '\n---'
        # (kalau ada sms_wait) ATAU langsung EOF (blocked/invalid). JSON-nya
        # bisa multiline + berisi brace dalam string, jadi di-balance manual.
        m = re.search(r"Respons:\s*", text)
        if not m:
            out["error"] = "format output cek_wait tidak dikenali"
            return out
        depth = 0
        start = None
        end = None
        in_str = False
        esc = False
        for i in range(m.end(), len(text)):
            ch = text[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
                continue
            if ch == '"':
                in_str = True
            elif ch == "{":
                if depth == 0:
                    start = i
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0 and start is not None:
                    end = i + 1
                    break
        if start is None or end is None:
            out["error"] = "respons JSON tidak ditemukan"
            return out
        try:
            data = json.loads(text[start:end])
        except ValueError:
            out["error"] = "respons bukan JSON valid"
            return out
        if not isinstance(data, dict):
            out["error"] = "respons bukan JSON object"
            return out
        out["data"] = data
        if "sms_wait" not in data:
            reason = data.get("reason")
            out["error"] = f"gak bisa ke-detect ({reason or 'blocked/no sms_wait'})"
            return out
        out["ok"] = True
        out["sms_wait"] = data.get("sms_wait")
        out["sms_wait_fmt"] = _fmt_otp_wait(data.get("sms_wait"))
        out["voice_wait"] = data.get("voice_wait")
        out["voice_wait_fmt"] = _fmt_otp_wait(data.get("voice_wait"))
        out["retry_after"] = data.get("retry_after")
        out["retry_after_fmt"] = _fmt_otp_wait(data.get("retry_after"))
    except FileNotFoundError:
        out["error"] = "node tidak tersedia di server"
    except asyncio.TimeoutError:
        out["error"] = "timeout deteksi (40 detik)"
    except Exception as e:
        out["error"] = f"{type(e).__name__}: {e}"
    return out


async def _resolve_tg_profile(user_id):
    """Ambil username + nama via Bot API getChat. Coba kedua token (dual-bot)."""
    username = "-"
    full_name = "-"
    for tok in (TELEGRAM_BOT_TOKEN, DUAL_BOT_TOKEN):
        try:
            async with httpx.AsyncClient(timeout=15) as client:
                response = await client.get(
                    f"https://api.telegram.org/bot{tok}/getChat",
                    params={"chat_id": int(user_id)},
                )
                payload = response.json()
                if payload.get("ok"):
                    chat = payload.get("result") or {}
                    if chat.get("username"):
                        username = f"@{chat['username']}"
                    full_name = " ".join(
                        filter(None, [chat.get("first_name"), chat.get("last_name")])
                    ) or "-"
                    break
        except Exception:
            continue
    return username, full_name


def _describe_fix_origin(chat):
    """Ringkas asal perintah /fix: Private / Group / Supergroup."""
    if chat is None:
        return "Tidak diketahui"
    chat_type = getattr(chat, "type", None)
    chat_type = getattr(chat_type, "value", chat_type) or "unknown"
    chat_id = getattr(chat, "id", None)
    title = getattr(chat, "title", None) or getattr(chat, "full_name", None) or getattr(chat, "first_name", None)
    if chat_type == "private":
        return f"Private Chat ({chat_id})"
    if chat_type in {"group", "supergroup"}:
        label = "Group" if chat_type == "group" else "Supergroup"
        name = title or "-"
        return f"{label} · {name} ({chat_id})"
    if chat_type == "channel":
        return f"Channel · {title or '-'} ({chat_id})"
    return f"{chat_type} ({chat_id})"


def _capture_fix_origin(context, chat):
    """Simpan asal chat /fix ke user_data untuk log grup."""
    if context is None:
        return "Tidak diketahui"
    origin = _describe_fix_origin(chat)
    try:
        context.user_data["fix_chat_origin"] = origin
    except Exception:
        pass
    return origin


async def _send_rich_label_table(chat_id, *, title, subtitle, rows, footer):
    """Kirim tabel native Bot API 10.2 (gaya /me). Coba kedua token (dual-bot)."""
    def cell(text, header=False):
        value = {"text": str(text), "align": "left", "valign": "middle"}
        if header:
            value["is_header"] = True
        return value

    blocks = [
        {"type": "heading", "text": title, "size": 2},
        {
            "type": "paragraph",
            "text": {"type": "italic", "text": subtitle},
        },
        {
            "type": "table",
            "cells": [
                [cell("LABEL", True), cell("DETAIL", True)],
                *[[cell(label, True), cell(value)] for label, value in rows],
            ],
            "is_bordered": True,
            "is_striped": True,
        },
        {"type": "footer", "text": footer},
    ]
    last_err = None
    for tok in (TELEGRAM_BOT_TOKEN, DUAL_BOT_TOKEN):
        try:
            async with httpx.AsyncClient(timeout=20) as client:
                response = await client.post(
                    f"https://api.telegram.org/bot{tok}/sendRichMessage",
                    json={
                        "chat_id": chat_id,
                        "rich_message": {"blocks": blocks, "skip_entity_detection": True},
                    },
                )
                payload = response.json()
                if payload.get("ok"):
                    return payload
                migrate_id = (payload.get("parameters") or {}).get("migrate_to_chat_id")
                if migrate_id:
                    return {
                        "ok": False,
                        "migrate_to_chat_id": int(migrate_id),
                        "description": payload.get("description"),
                    }
                last_err = RuntimeError(payload.get("description") or f"HTTP {response.status_code}")
        except Exception as e:
            last_err = e
    raise last_err or RuntimeError("sendRichMessage gagal di kedua bot")


async def _send_plain_label_table(chat_id, *, title, subtitle, rows, footer_html):
    """Fallback HTML rapi tanpa blockquote luar. Coba kedua token (dual-bot)."""
    body = (
        f"<b>{html.escape(title)}</b>\n"
        f"<i>{html.escape(subtitle)}</i>\n\n"
        f"<pre>{html.escape(_plain_table(rows))}</pre>\n\n"
        f"{footer_html}"
    )
    for tok in (TELEGRAM_BOT_TOKEN, DUAL_BOT_TOKEN):
        try:
            async with httpx.AsyncClient(timeout=20) as client:
                response = await client.post(
                    f"https://api.telegram.org/bot{tok}/sendMessage",
                    json={
                        "chat_id": chat_id,
                        "text": body,
                        "parse_mode": "HTML",
                        "disable_web_page_preview": True,
                    },
                )
                payload = response.json()
                if payload.get("ok"):
                    return payload
        except Exception:
            continue
        migrate_id = (payload.get("parameters") or {}).get("migrate_to_chat_id")
        if migrate_id:
            return {
                "ok": False,
                "migrate_to_chat_id": int(migrate_id),
                "description": payload.get("description"),
            }
        raise RuntimeError(payload.get("description") or f"HTTP {response.status_code}")


async def notify_fix_group_log(
    *,
    user_id,
    phone,
    status,
    banding_id=None,
    server=None,
    source=None,
    username=None,
    full_name=None,
    chat_origin=None,
    limit_hours=None,
):
    """Kirim log /fix ke grup monitoring (terkirim / balasan)."""
    global FIX_LOG_GROUP_ID
    try:
        if not username or username == "-" or not full_name or full_name == "-":
            resolved_user, resolved_name = await _resolve_tg_profile(user_id)
            if not username or username == "-":
                username = resolved_user
            if not full_name or full_name == "-":
                full_name = resolved_name

        banding_id = banding_id or _new_fix_banding_id()
        status_u = str(status or "").upper()
        if status_u in {"SUCCESS", "REPLY", "BALASAN", "REPLIED"}:
            title = "PROSES FIXMERAH BERHASIL"
            status_label = "SUCCESS"
        else:
            title = "PROSES FIXMERAH TERKIRIM"
            status_label = "SENT"

        if username and username != "-" and not str(username).startswith("@"):
            username = f"@{username}"

        rows = [
            ("Telegram ID", str(user_id)),
            ("Username", username or "-"),
            ("Nama", full_name or "-"),
            ("Nomor", _mask_fix_phone(phone)),
            ("Banding", banding_id),
            ("Limit", f"{int(limit_hours or 24)} jam"),
            ("Asal Chat", chat_origin or "-"),
            ("Status", status_label),
        ]
        if server not in (None, "", 0):
            rows.insert(-1, ("Server", str(server)))
        if source:
            rows.insert(-1, ("Sumber", str(source)))

        subtitle = "Home › Fix › Group Log"
        footer = "Powered by DikZz"
        footer_html = (
            f"<i>Powered by</i> <b>DikZz</b>"
        )

        async def _dispatch(chat_id):
            try:
                return await _send_rich_label_table(
                    chat_id,
                    title=title,
                    subtitle=subtitle,
                    rows=rows,
                    footer=footer,
                )
            except Exception as rich_exc:
                print(f"[FIX LOG] rich fallback: {rich_exc}")
                return await _send_plain_label_table(
                    chat_id,
                    title=title,
                    subtitle=subtitle,
                    rows=rows,
                    footer_html=footer_html,
                )

        result = await _dispatch(FIX_LOG_GROUP_ID)
        if result.get("ok"):
            return

        migrate_id = result.get("migrate_to_chat_id")
        if migrate_id:
            FIX_LOG_GROUP_ID = int(migrate_id)
            print(f"[FIX LOG] chat migrated -> {FIX_LOG_GROUP_ID}")
            result = await _dispatch(FIX_LOG_GROUP_ID)
            if result.get("ok"):
                return

        raise RuntimeError(result.get("description") or "Gagal kirim fix log")
    except Exception as exc:
        print(f"[FIX LOG] gagal kirim ke grup {FIX_LOG_GROUP_ID}: {exc}")
        logging.warning("[FIX LOG] gagal kirim ke grup %s: %s", FIX_LOG_GROUP_ID, exc)


