async def _handle_dewabiz_ns_input(update: Update, context: ContextTypes.DEFAULT_TYPE, ns_wait: dict, text: str):
    """Handle input nameserver manual dari user setelah tekan tombol GANTI NAMESERVER."""
    user_id = update.effective_user.id
    db_id = ns_wait["db_id"]
    dom_name = ns_wait["domain"]
    chat_id = ns_wait["chat_id"]
    old_msg_id = ns_wait["msg_id"]

    # Hapus pesan lama (prompt input)
    try:
        await context.bot.delete_message(chat_id, old_msg_id)
    except Exception:
        pass

    # Parse input: 2 baris = ns1, ns2
    lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
    if len(lines) < 2:
        # Coba split spasi jika user kirim 1 baris: "ns1 ns2"
        parts = text.strip().split()
        if len(parts) >= 2 and "." in parts[0] and "." in parts[1]:
            lines = parts[:2]

    if len(lines) < 2:
        await update.message.reply_text(
            _screen('NAMESERVER GAGAL',
                    f"<b>FORMAT SALAH</b>\n\n"
                    f"Kirim 2 nameserver, masing-masing di baris baru:\n\n"
                    f"<code>chip.ns.cloudflare.com\ntreasure.ns.cloudflare.com</code>\n\n"
                    f"<i>Silakan coba lagi dari detail domain.</i>",
                    'Home › ListDomain › Nameserver'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("KEMBALI KE DETAIL", callback_data=f"dewabiz_det_{db_id}_{user_id}", style="primary")]
            ])
        )
        return

    ns1 = lines[0].lower().rstrip(".")
    ns2 = lines[1].lower().rstrip(".")

    # Validasi format basic
    if not re.match(r'^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$', ns1) or "." not in ns1:
        await update.message.reply_text(
            _screen('NAMESERVER GAGAL', f"<b>NS1 tidak valid:</b> <code>{html.escape(ns1)}</code>", 'Home › ListDomain › Nameserver'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("KEMBALI KE DETAIL", callback_data=f"dewabiz_det_{db_id}_{user_id}", style="primary")]])
        )
        return
    if not re.match(r'^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$', ns2) or "." not in ns2:
        await update.message.reply_text(
            _screen('NAMESERVER GAGAL', f"<b>NS2 tidak valid:</b> <code>{html.escape(ns2)}</code>", 'Home › ListDomain › Nameserver'),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("KEMBALI KE DETAIL", callback_data=f"dewabiz_det_{db_id}_{user_id}", style="primary")]])
        )
        return

    # Ambil kredensial
    try:
        cur.execute("SELECT email, password, domain_id, pin_code FROM dewabiz_domains WHERE id = ?", (db_id,))
        cred = cur.fetchone()
    except Exception:
        cred = None

    if not cred:
        await update.message.reply_text(
            _screen('ERROR', "<b>Domain tidak ditemukan di database!</b>", 'Home › ListDomain'),
            parse_mode=ParseMode.HTML
        )
        return

    email_acc, pass_acc, domain_id, pin_acc = cred

    # Kirim pesan loading
    loading_msg = await update.message.reply_text(
        _screen('MENGUBAH NAMESERVER',
                f"{em(CE_LOADING,'🟠')} <b>PROSES GANTI NAMESERVER</b>\n\n"
                f"🌐 <b>Domain:</b> <code>{dom_name}</code>\n\n"
                f"<b>NS baru:</b>\n"
                f"1. <code>{ns1}</code>\n"
                f"2. <code>{ns2}</code>\n\n"
                f"<i>Login ke akun & menyimpan nameserver...</i>",
                'Home › ListDomain › Nameserver'),
        parse_mode=ParseMode.HTML
    )

    # Jalankan perubahan NS
    ok, new_status, msg_res = await bg.run(user_id, check_and_update_nameservers, email_acc, pass_acc, domain_id, ns1, ns2, pin_acc)

    # Update DB
    if ok and new_status == 'active':
        try:
            cur.execute("UPDATE dewabiz_domains SET status='active', ns1=?, ns2=?, last_checked_at=CURRENT_TIMESTAMP WHERE id=?", (ns1, ns2, db_id))
            conn.commit()
        except Exception:
            pass
    elif new_status == 'pending':
        try:
            cur.execute("UPDATE dewabiz_domains SET status='pending', last_checked_at=CURRENT_TIMESTAMP WHERE id=?", (db_id,))
            conn.commit()
        except Exception:
            pass

    if ok and new_status == 'active':
        res_text = (
            f"{em(E1,'🎉')} <b>NAMESERVER BERHASIL DIUBAH!</b>\n\n"
            f"🌐 <b>Domain:</b> <code>{dom_name}</code>\n"
            f"🟢 <b>Status:</b> <code>ACTIVE</code>\n\n"
            f"📡 <b>Nameserver Baru:</b>\n"
            f"1. <code>{ns1}</code>\n"
            f"2. <code>{ns2}</code>\n\n"
            f"<i>Nameserver lama (ns3, ns4) otomatis dihapus oleh sistem.</i>"
        )
    else:
        res_text = (
            f"<b>GAGAL UBAH NAMESERVER</b>\n\n"
            f"🌐 <b>Domain:</b> <code>{dom_name}</code>\n"
            f"🟠 <b>Status:</b> <code>{new_status.upper()}</code>\n\n"
            f"<b>Info:</b> {msg_res}\n\n"
            f"<i>Domain harus berstatus ACTIVE sebelum nameserver bisa diubah.</i>"
        )

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("KEMBALI KE DETAIL", callback_data=f"dewabiz_det_{db_id}_{user_id}", style="primary")],
        [InlineKeyboardButton("KEMBALI LIST DOMAIN", callback_data=f"dewabiz_list_0_{user_id}", style="danger")]
    ])

    await loading_msg.edit_text(
        _screen('STATUS NAMESERVER', res_text, 'Home › ListDomain › Nameserver'),
        parse_mode=ParseMode.HTML,
        reply_markup=kb
    )


async def freedomain_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handler /freedomain <nama domain> [jumlah]"""
    if not is_allowed_user(update.effective_user.id):
        return
    user_id = update.effective_user.id

    args = context.args or []
    if not args:
        max_allowed = "Unlimited" if is_owner(user_id) else ("8" if is_admin(user_id) else "5")
        await update.message.reply_text(
            _build(
                TEMPLATE_DEWABIZ_HELP,
                'FREE DOMAIN',
                'Home › FreeDomain',
                message=(
                    "<b>CARA PENGGUNAAN /FREEDOMAIN</b>\n\n"
                    "Gunakan perintah ini untuk mendaftarkan domain gratis secara otomatis.\n"
                    "Mendukung: <code>.my.id</code> (default), <code>.web.id</code>, <code>.biz.id</code>, <code>.co.id</code>, dll.\n\n"
                    "<b>Format:</b>\n"
                    "• <code>/freedomain &lt;nama_domain&gt; [jumlah] [kode_promo]</code>\n\n"
                    "<b>Contoh:</b>\n"
                    "• <code>/freedomain dikzxinxz</code> → dikzxinxz.my.id\n"
                    "• <code>/freedomain dikzxinxz.web.id</code> → dikzxinxz.web.id\n"
                    "• <code>/freedomain dikzxinxz.web.id 3</code> → 3 domain .web.id\n"
                    "• <code>/freedomain dikzxinxz 2 KODEPROMO</code> → Pakai kode promo lain\n\n"
                    f"<b>Kode Promo Aktif:</b> <code>{html.escape(DEFAULT_PROMO_CODE)}</code>\n"
                    "<i>(Kalau kuota kode promo habis, registrasi otomatis dibatalkan sebelum checkout supaya tidak muncul tagihan — isi kode promo baru di argumen ketiga.)</i>\n\n"
                    f"<b>Batas Pembuatan Domain Kamu:</b> <code>{max_allowed}</code>\n"
                    "<i>(User: 5, Admin/Worker: 8, Owner: Unlimited)</i>\n\n"
                    "<i>Gunakan /listdomain untuk melihat daftar domain & mengubah Nameserver Cloudflare.</i>"
                )
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("DAFTAR DOMAIN SAYA", callback_data=f"dewabiz_list_0_{user_id}", style="primary"),
                InlineKeyboardButton("KEMBALI", callback_data=f"menu_start_{user_id}", style="danger")
            ]])
        )
        return

    # Parse domain name & quantity
    raw_domain = args[0].strip()
    qty = 1
    if len(args) > 1 and args[1].isdigit():
        qty = int(args[1])
        if qty < 1:
            qty = 1

    # Kode promo opsional: argumen non-angka setelah nama domain.
    # Perlu karena kode default bisa habis kuotanya di sisi penyedia.
    promo_code = DEFAULT_PROMO_CODE
    for a in args[1:]:
        a = a.strip()
        if a and not a.isdigit():
            promo_code = a.upper()
            break

    # Check user limits
    if not is_owner(user_id):
        limit = 8 if is_admin(user_id) else 5
        role_name = "Admin/Worker" if is_admin(user_id) else "User"

        try:
            cur.execute("SELECT COUNT(*) FROM dewabiz_domains WHERE user_id = ?", (user_id,))
            current_count = cur.fetchone()[0]
        except Exception:
            current_count = 0

        if current_count >= limit:
            await update.message.reply_text(
                _build(
                    TEMPLATE_ERROR,
                    'BATAS DOMAIN TERCAPAI',
                    'Home › FreeDomain › Limit',
                    message=f"Batas maksimal registrasi domain kamu ({role_name}) adalah <b>{limit} domain</b>.\n\nKamu sudah memiliki <b>{current_count} domain</b> tersimpan."
                ),
                parse_mode=ParseMode.HTML
            )
            return

        if current_count + qty > limit:
            allowed_qty = limit - current_count
            await update.message.reply_text(
                _build(
                    TEMPLATE_ERROR,
                    'BATAS JUMLAH TERCAPAI',
                    'Home › FreeDomain › Limit',
                    message=f"Sisa kuota domain kamu adalah <b>{allowed_qty} domain</b> lagi.\n\nKamu meminta <b>{qty} domain</b> (Total: {current_count + qty}/{limit})."
                ),
                parse_mode=ParseMode.HTML
            )
            return

    # Parse TLD dari input — deteksi .web.id, .biz.id, dll; default .my.id
    raw = raw_domain.lower()
    if raw.startswith("http://") or raw.startswith("https://"):
        raw = raw.split("//", 1)[1]
    raw = raw.split("/")[0]

    tld = ".my.id"  # default
    for _t in sorted(SUPPORTED_TLDS, key=len, reverse=True):
        if raw.endswith(_t):
            tld = _t
            raw = raw[:-len(_t)]
            break
    base_name = raw.rstrip(".")

    # Progress berjalan dari worker thread. Simpan event loop yang aktif lalu
    # jadwalkan edit pesan dengan aman dari thread tersebut.
    event_loop = asyncio.get_running_loop()

    def _render_domain_progress(completed_cnt, total_qty, last_name, step_text):
        inner = (
            f"<b>MEMPROSES BATCH REGISTRASI ({completed_cnt}/{total_qty})</b>\n\n"
            f"<b>Domain Terakhir:</b>\n<code>{html.escape(last_name)}</code>\n\n"
            f"<i>{html.escape(step_text)}</i>"
        )
        return _quote(inner)

    # Kirim status awal
    msg = await update.message.reply_text(
        _render_domain_progress(0, qty, f"{base_name}{tld}", "Menyiapkan pool 8 worker..."),
        parse_mode=ParseMode.HTML
    )

    results_success = []
    results_failed = []
    completed_counter = 0

    # Buat daftar target domain
    target_domains = []
    for idx in range(1, qty + 1):
        suffix = f"{idx}" if idx > 1 else ""
        t_name = f"{base_name}{suffix}{tld}"
        target_domains.append(t_name)

    # Fungsi registrasi 1 domain untuk diajukan ke ThreadPoolExecutor(max_workers=8)
    def _worker_task(t_name):
        nonlocal completed_counter
        def _cb(step_text):
            def _schedule_edit():
                try:
                    asyncio.create_task(
                        msg.edit_text(
                            _render_domain_progress(completed_counter, qty, t_name, step_text),
                            parse_mode=ParseMode.HTML,
                        )
                    )
                except Exception:
                    pass
            event_loop.call_soon_threadsafe(_schedule_edit)

        ok, res, err_msg = register_dewabiz_domain(t_name, promo_code, _cb)
        completed_counter += 1
        return t_name, ok, res, err_msg

    # Eksekusi paralel dengan 8 worker
    def _run_batch():
        out = []
        with ThreadPoolExecutor(max_workers=8) as executor:
            futures = [executor.submit(_worker_task, d) for d in target_domains]
            for f in futures:
                out.append(f.result())
        return out

    batch_outputs = await bg.run(user_id, _run_batch)

    for target_name, ok, res, err_msg in batch_outputs:
        if ok and res:
            try:
                cur.execute(
                    """INSERT INTO dewabiz_domains
                       (user_id, domain, email, password, pin_code, domain_id, order_num, status,
                        fullname, locale, phone)
                       VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?)""",
                    (user_id, res['domain'], res['email'], res['password'], res['pin_code'],
                     res['domain_id'], res['order_num'],
                     res.get('fullname', ''), res.get('locale', ''), res.get('phone', ''))
                )
                conn.commit()
                results_success.append(res)
            except Exception as dbe:
                print(f"[FREEDOMAIN] Save DB error: {dbe}")
                results_failed.append((target_name, f"Save DB error: {dbe}"))
        else:
            results_failed.append((target_name, err_msg or "Gagal registrasi"))

    # Hapus pesan progress animasi
    try:
        await msg.delete()
    except Exception:
        pass

    # Buat isi rincian file TXT
    txt_lines = []
    txt_lines.append("==========================================================")
    txt_lines.append("            HASIL REGISTRASI FREE DOMAIN")
    txt_lines.append("==========================================================")
    txt_lines.append(f"User ID       : {user_id}")
    txt_lines.append(f"Total Diminta : {qty}")
    txt_lines.append(f"Kode Promo    : {promo_code}")
    txt_lines.append(f"Sukses        : {len(results_success)}")
    txt_lines.append(f"Gagal         : {len(results_failed)}")
    txt_lines.append(f"Waktu         : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    txt_lines.append("==========================================================\n")

    if results_success:
        txt_lines.append("--- [ DAFTAR AKUN BERHASIL DIDAFTARKAN ] ---")
        for i, r in enumerate(results_success, 1):
            txt_lines.append(f"[{i}] DOMAIN   : {r['domain']}")
            txt_lines.append(f"    NAMA     : {r.get('fullname', '-')}")
            txt_lines.append(f"    NEGARA   : {r.get('locale', '-')}")
            txt_lines.append(f"    KOTA     : {r.get('city', '-')}, {r.get('state', '-')}")
            txt_lines.append(f"    TELEPON  : {r.get('phone', '-')}")
            txt_lines.append(f"    EMAIL    : {r['email']}")
            txt_lines.append(f"    PASSWORD : {r['password']}")
            txt_lines.append(f"    2FA PIN  : {r['pin_code']}")
            txt_lines.append(f"    ORDER NO : {r['order_num']}")
            txt_lines.append("----------------------------------------------------------")
        txt_lines.append("")

    if results_failed:
        txt_lines.append("--- [ DAFTAR DOMAIN GAGAL ] ---")
        for i, (fn, fe) in enumerate(results_failed, 1):
            txt_lines.append(f"[{i}] DOMAIN : {fn}")
            txt_lines.append(f"    ERROR  : {fe}")
            txt_lines.append("----------------------------------------------------------")
        txt_lines.append("")

    txt_lines.append("Catatan:")
    txt_lines.append("- Domain berstatus PENDING (memerlukan waktu aktivasi sekitar ±15 menit).")
    txt_lines.append("- Gunakan /listdomain di Telegram Bot untuk memeriksa status aktivasi & mengaitkan Nameserver Cloudflare.")

    txt_content = "\n".join(txt_lines)

    # Kirim pesan rangkuman ringkas + file TXT detail
    promo_blocked = any(
        'promo' in (fe or '').lower() for _fn, fe in results_failed
    )
    promo_note = ""
    if promo_blocked and not results_success:
        promo_note = (
      #      f"\n\n<blockquote>Kode promo <code>{html.escape(promo_code)}</code> "
       #     f"sudah tidak bisa dipakai (kuota habis di sisi penyedia), jadi proses "
          #  f"dihentikan sebelum checkout agar tidak muncul tagihan.\n"
         #   f"Coba lagi dengan kode lain: <code>/freedomain {html.escape(base_name)} "
         #   f"{qty} KODEPROMOBARU</code></blockquote>"
        )

    summary_body = (
        f"<b>PROSES REGISTRASI DOMAIN SELESAI</b>\n\n"
        f"<b>Total Diminta:</b> <code>{qty}</code>\n"
        f"<b>Sukses:</b> <code>{len(results_success)}</code>\n"
        f"<b>Gagal:</b> <code>{len(results_failed)}</code>\n\n"
        f"<blockquote>Seluruh kredensial akun & detail domain telah dilampirkan dalam file TXT di atas.\n"
        f"Gunakan <b>/listdomain</b> untuk memeriksa aktivasi & memasang Nameserver Cloudflare.</blockquote>"
        f"{promo_note}"
    )

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("LIHAT DI LIST DOMAIN", callback_data=f"dewabiz_list_0_{user_id}", style="success")],
        [InlineKeyboardButton("KEMBALI UTAMA", callback_data=f"menu_start_{user_id}", style="primary")]
    ])

    file_bytes = io.BytesIO(txt_content.encode('utf-8'))
    file_bytes.name = f"freedomain_{base_name}_{len(results_success)}success.txt"

    await update.message.reply_document(
        document=file_bytes,
        filename=file_bytes.name,
        caption=_screen('REGISTRASI DOMAIN', summary_body, 'Home › FreeDomain › Hasil'),
        parse_mode=ParseMode.HTML,
        reply_markup=kb
    )


async def listdomain_command(update: Update, context: ContextTypes.DEFAULT_TYPE, page=0):
    """Handler /listdomain - List domain milik user dengan pagination 6 per halaman (gaya /listele)"""
    if not is_allowed_user(update.effective_user.id):
        return
    user_id = update.effective_user.id

    try:
        cur.execute(
            "SELECT id, domain, status, created_at, ns1, ns2 FROM dewabiz_domains WHERE user_id = ? ORDER BY id ASC",
            (user_id,)
        )
        domains = cur.fetchall()
    except Exception:
        domains = []

    if not domains:
        text_empty = _screen(
            'DAFTAR FREE DOMAIN',
            f"{em(CE_FILE,'📁')} <b>BELUM ADA DOMAIN TERSIMPAN</b>\n\n"
            "Kamu belum memiliki domain tersimpan.\n\n"
            "Gunakan perintah <code>/freedomain &lt;namadomain&gt; [jumlah]</code> untuk mendaftarkan domain baru.",
            'Home › ListDomain'
        )
        kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("KEMBALI MENU", callback_data=f"menu_start_{user_id}",
                                 style="danger", icon_custom_emoji_id=CE_BACK)
        ]])
        if update.callback_query:
            chat_id = update.callback_query.message.chat_id
            try:
                await update.callback_query.edit_message_text(text_empty, parse_mode=ParseMode.HTML, reply_markup=kb)
            except Exception:
                try:
                    await update.callback_query.message.delete()
                except Exception:
                    pass
                # send_message, bukan reply_text: pesan yang dikutip sudah dihapus.
                await context.bot.send_message(chat_id=chat_id, text=text_empty,
                                               parse_mode=ParseMode.HTML, reply_markup=kb)
        else:
            await update.message.reply_text(text_empty, parse_mode=ParseMode.HTML, reply_markup=kb)
        return

    # Hitung jumlah active & pending
    per_page = 6
    total = len(domains)
    count_active = sum(1 for d in domains if d[2] == 'active')
    count_pending = total - count_active

    # Filter berdasarkan context (jika ada filter aktif)
    active_filter = context.user_data.get(f"dewabiz_filter_{user_id}", "all")  # "all", "active", "pending"

    if active_filter == "active":
        filtered = [d for d in domains if d[2] == 'active']
    elif active_filter == "pending":
        filtered = [d for d in domains if d[2] != 'active']
    else:
        filtered = domains

    total_filtered = len(filtered)
    total_pages = max(1, (total_filtered - 1) // per_page + 1)
    page = max(0, min(page, total_pages - 1))

    start = page * per_page
    chunk = filtered[start:start + per_page]

    # ── Auto live-check status: hanya domain PENDING di halaman ini yang dicek ──
    # Kenapa cuma 1 halaman (maks 6): user bisa punya ratusan domain pending, dan tiap
    # cek = login penuh ke DewaBiz (~beberapa detik). Cek semua akan bikin callback
    # Telegram timeout & membebani server. Domain 'active' di-skip (final). Rate-limit
    # LIVE_CHECK_MIN_GAP mencegah re-login saat user bolak-balik halaman.
    LIVE_CHECK_MIN_GAP = 300  # detik
    _sync_msg = None  # pesan "SINKRONISASI" (khusus command teks) yang dihapus di akhir
    if chunk and DEWABIZ_OK:
        pending_ids = [r[0] for r in chunk if r[2] != 'active']
        rows_to_check = []
        if pending_ids:
            qmarks = ",".join("?" * len(pending_ids))
            try:
                cur.execute(
                    f"SELECT id, domain, email, password, domain_id, pin_code FROM dewabiz_domains "
                    f"WHERE id IN ({qmarks}) AND ("
                    f"  last_checked_at IS NULL OR "
                    f"  (strftime('%s','now') - strftime('%s', last_checked_at)) > ?"
                    f")",
                    (*pending_ids, LIVE_CHECK_MIN_GAP),
                )
                rows_to_check = cur.fetchall()
            except Exception as _e:
                print(f"[listdomain autocheck] query: {_e}")
                rows_to_check = []

        if rows_to_check:
            checking_screen = _quote(
                f"{em(CE_LOADING,'🟠')} <b>SINKRONISASI STATUS DOMAIN</b>\n\n"
                f"Mengecek <b>{len(rows_to_check)}</b> domain pending (halaman {page+1})...\n"
                f"<i>Sebentar ya — login & cek aktivasi tiap domain.</i>"
            )
            # Simpan referensi pesan "sinkronisasi" supaya bisa dihapus setelah selesai.
            try:
                if update.callback_query:
                    await update.callback_query.edit_message_text(checking_screen, parse_mode=ParseMode.HTML)
                else:
                    _sync_msg = await update.message.reply_text(checking_screen, parse_mode=ParseMode.HTML)
            except Exception:
                pass

            changed = False
            # Cek pending SECARA PARALEL (maks 20 worker). Login/cek di thread pool,
            # update DB dikumpulin lalu ditulis di thread utama (sqlite tidak thread-safe).
            def _check_one_page(pr):
                p_id, p_dom, p_email, p_pass, p_domid, p_pin = pr
                try:
                    okc, ns, _m = check_domain_status(p_email, p_pass, p_domid, p_dom, pin_code=p_pin)
                    return (p_id, p_dom, bool(okc), ns)
                except Exception as _e:
                    print(f"[listdomain autocheck] {p_dom}: {_e}")
                    return (p_id, p_dom, False, 'unknown')

            def _run_page_batch():
                out = []
                workers = min(20, len(rows_to_check))
                with ThreadPoolExecutor(max_workers=workers) as executor:
                    futures = [executor.submit(_check_one_page, pr) for pr in rows_to_check]
                    for f in futures:
                        out.append(f.result())
                return out

            try:
                page_results = await bg.run(user_id, _run_page_batch)
            except Exception as _e:
                print(f"[listdomain autocheck] batch: {_e}")
                page_results = []

            for p_id, p_dom, okc, ns in page_results:
                try:
                    if okc and ns == 'active':
                        cur.execute(
                            "UPDATE dewabiz_domains SET status='active', last_checked_at=CURRENT_TIMESTAMP WHERE id=?",
                            (p_id,)
                        )
                        changed = True
                    else:
                        cur.execute(
                            "UPDATE dewabiz_domains SET last_checked_at=CURRENT_TIMESTAMP WHERE id=?",
                            (p_id,)
                        )
                except Exception:
                    pass
            try:
                conn.commit()
            except Exception:
                pass

            # Kalau ada status yang berubah, ambil ulang data + chunk supaya list sinkron
            if changed:
                try:
                    cur.execute(
                        "SELECT id, domain, status, created_at, ns1, ns2 FROM dewabiz_domains WHERE user_id = ? ORDER BY id ASC",
                        (user_id,)
                    )
                    domains = cur.fetchall()
                    total = len(domains)
                    count_active = sum(1 for d in domains if d[2] == 'active')
                    count_pending = total - count_active
                    # Filter harus diterapkan ulang, kalau tidak chunk jadi campur
                    # (mis. filter PENDING tapi list menampilkan domain active).
                    if active_filter == "active":
                        filtered = [d for d in domains if d[2] == 'active']
                    elif active_filter == "pending":
                        filtered = [d for d in domains if d[2] != 'active']
                    else:
                        filtered = domains
                    total_filtered = len(filtered)
                    total_pages = max(1, (total_filtered - 1) // per_page + 1)
                    page = max(0, min(page, total_pages - 1))
                    start = page * per_page
                    chunk = filtered[start:start + per_page]
                except Exception:
                    pass

    filter_label = {"all": "SEMUA", "active": "ACTIVE", "pending": "PENDING"}[active_filter]
    # Teks pesan pakai custom emoji premium (<tg-emoji>) via em(), bukan emoji biasa.
    lines = [
        f"{em(CE_FILE,'📁')} <b>Total Domain:</b> <code>{total}</code>\n"
        f"{em(CE_CHECK,'✅')} <b>Active:</b> <code>{count_active}</code>  "
        f"{em(CE_LOADING,'⏳')} <b>Pending:</b> <code>{count_pending}</code>\n"
        f"{em(CE_SETTINGS,'⚙️')} <b>Filter:</b> <code>[{filter_label}]</code>\n"
    ]
    for i, row in enumerate(chunk, start + 1):
        dom_id, dom_name, dom_stat, dom_date, dom_ns1, dom_ns2 = row
        st_icon = em(CE_CHECK, '✅') if dom_stat == 'active' else em(CE_LOADING, '⏳')
        lines.append(f"<b>{i}.</b> {st_icon} <code>{dom_name}</code>")

    body_text = "\n".join(lines) + "\n\n<i>Klik domain untuk detail & ubah Nameserver:</i>"

    keyboard = []

    # Filter buttons row
    filter_row = []
    f_all_style = "success" if active_filter == "all" else "primary"
    f_active_style = "success" if active_filter == "active" else "primary"
    f_pending_style = "success" if active_filter == "pending" else "primary"
    filter_row.append(InlineKeyboardButton(
        f"SEMUA ({total})", callback_data=f"dewabiz_flt_all_{user_id}",
        style=f_all_style, icon_custom_emoji_id=CE_FILE))
    filter_row.append(InlineKeyboardButton(
        f"ACTIVE ({count_active})", callback_data=f"dewabiz_flt_active_{user_id}",
        style=f_active_style, icon_custom_emoji_id=CE_CHECK))
    filter_row.append(InlineKeyboardButton(
        f"PENDING ({count_pending})", callback_data=f"dewabiz_flt_pending_{user_id}",
        style=f_pending_style, icon_custom_emoji_id=CE_LOADING))
    keyboard.append(filter_row)

    for row in chunk:
        dom_id, dom_name, dom_stat, dom_date, dom_ns1, dom_ns2 = row
        is_act = dom_stat == 'active'
        # Ikon tombol pakai custom emoji (icon_custom_emoji_id), bukan emoji biasa
        # di dalam label — label tombol tidak bisa render <tg-emoji>.
        keyboard.append([InlineKeyboardButton(
            dom_name, callback_data=f"dewabiz_det_{dom_id}_{user_id}",
            style="success" if is_act else "primary",
            icon_custom_emoji_id=CE_CHECK if is_act else CE_LOADING)])

    # Tombol Geser Pagination (6 per page)
    if total_filtered > per_page:
        nav_buttons = []
        if page > 0:
            nav_buttons.append(InlineKeyboardButton(
                "PREV", callback_data=f"dewabiz_list_{page-1}_{user_id}",
                style="primary", icon_custom_emoji_id=CE_BACK))
        nav_buttons.append(InlineKeyboardButton(f"{page+1}/{total_pages}", callback_data="noop", style="primary"))
        if page < total_pages - 1:
            nav_buttons.append(InlineKeyboardButton(
                "NEXT", callback_data=f"dewabiz_list_{page+1}_{user_id}",
                style="primary", icon_custom_emoji_id=CE_REPE_EKLUSIF))
        keyboard.append(nav_buttons)

    keyboard.append([InlineKeyboardButton(
        "EXPORT TXT (CEK VALID)", callback_data=f"dewabiz_export_{user_id}",
        style="success", icon_custom_emoji_id=CE_EXPORT)])
    keyboard.append([InlineKeyboardButton(
        "HAPUS SEMUA DOMAIN", callback_data=f"dewabiz_delall_{user_id}",
        style="danger", icon_custom_emoji_id=CE_HAPUS)])
    keyboard.append([InlineKeyboardButton(
        "KEMBALI MENU", callback_data=f"menu_start_{user_id}",
        style="danger", icon_custom_emoji_id=CE_BACK)])

    markup = InlineKeyboardMarkup(keyboard)
    full_screen = _screen('DAFTAR FREE DOMAIN', body_text, 'Home › ListDomain')

    # Selalu hapus pesan lama lalu kirim pesan BARU (baik saat pertama buka maupun
    # saat pindah halaman). Ini bikin daftar selalu muncul sebagai pesan terbaru di
    # chat dan menghindari error edit pada pesan Dokumen/expired.
    #
    # PENTING: pakai bot.send_message(chat_id=...), JANGAN message.reply_text().
    # reply_text() mengutip pesan asal; karena pesan itu baru saja dihapus, Telegram
    # menolak dengan BadRequest "Message to be replied not found" (kelihatan di log
    # sebagai [NETWORK WARNING] karena BadRequest turunan NetworkError).
    if update.callback_query:
        # Saat via tombol: pesan "SINKRONISASI" tadi hasil edit dari pesan callback,
        # jadi cukup hapus pesan callback lalu kirim daftar baru.
        chat_id = update.callback_query.message.chat_id
        try:
            await update.callback_query.message.delete()
        except Exception:
            pass
        await context.bot.send_message(
            chat_id=chat_id, text=full_screen,
            parse_mode=ParseMode.HTML, reply_markup=markup)
    else:
        # Saat via command teks /listdomain: hapus dulu pesan "SINKRONISASI" terpisah
        # (kalau ada) supaya tidak menggantung, baru kirim daftar.
        if _sync_msg is not None:
            try:
                await _sync_msg.delete()
            except Exception:
                pass
        await context.bot.send_message(
            chat_id=update.message.chat_id, text=full_screen,
            parse_mode=ParseMode.HTML, reply_markup=markup)


async def fixstatus_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Status proses /fix terbaru; pengiriman bukan bukti nomor sudah pulih."""
    user_id = update.effective_user.id
    try:
        cur.execute(
            """SELECT id, total, status, sent_count, reply_count, failed_count, created_at, completed_at
               FROM fix_runs WHERE user_id = ? ORDER BY id DESC LIMIT 1""",
            (user_id,),
        )
        run = cur.fetchone()
    except Exception:
        run = None

    if not run:
        await update.message.reply_text(
            _plain_screen("FIX STATUS", "<b>BELUM ADA RIWAYAT FIX</b>\n\nGunakan <code>/fix &lt;nomor&gt;</code> untuk memulai.", "Home › Fix › Status"),
            parse_mode=ParseMode.HTML,
        )
        return

    run_id, total, status, sent, replied, failed, created_at, completed_at = run
    try:
        cur.execute(
            "SELECT phone, status FROM fix_run_items WHERE run_id = ? ORDER BY id DESC LIMIT 8",
            (run_id,),
        )
        items = cur.fetchall()
    except Exception:
        items = []
    item_lines = "\n".join(f"{phone}: {item_status}" for phone, item_status in items) or "-"
    table = _plain_table([
        ('Run', '#' + str(run_id)),
        ('Status', status),
        ('Total', str(total)),
        ('Terkirim', str(sent)),
        ('Balasan', str(replied)),
        ('Gagal', str(failed)),
        ('Mulai', created_at or '-'),
        ('Selesai', completed_at or '-'),
    ])
    body = (
        "<b>STATUS FIX TERBARU</b>\n\n"
        f"<pre>{html.escape(table)}</pre>\n\n"
        f"<b>Nomor terbaru:</b>\n<blockquote><code>{html.escape(item_lines)}</code></blockquote>\n"
        "<i>Status terkirim atau balasan bukan jaminan nomor telah dipulihkan.</i>"
    )
    await update.message.reply_text(
        _plain_screen("FIX STATUS", body, "Home › Fix › Status"),
        parse_mode=ParseMode.HTML,
    )


def _create_database_backup():
    """Buat backup SQLite konsisten, ZIP, dan pertahankan 14 file terbaru."""
    backup_dir = BASE_DIR / "backups"
    backup_dir.mkdir(exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    temp_path = backup_dir / f"ivas_bot_{timestamp}.db.tmp"
    db_path = BASE_DIR / "ivas_bot.db"
    if not db_path.exists():
        raise FileNotFoundError(db_path)
    source = sqlite3.connect(db_path, timeout=30)
    target = sqlite3.connect(temp_path)
    try:
        source.backup(target)
        target.execute("PRAGMA integrity_check").fetchone()
    finally:
        target.close()
        source.close()
    archive_path = backup_dir / f"ivas_bot_{timestamp}.zip"
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.write(temp_path, arcname=f"ivas_bot_{timestamp}.db")
    with zipfile.ZipFile(archive_path, "r") as archive:
        if archive.testzip() is not None:
            raise RuntimeError("Arsip backup gagal divalidasi")
    temp_path.unlink(missing_ok=True)
    backups = sorted(backup_dir.glob("ivas_bot_*.zip"), key=lambda p: p.stat().st_mtime, reverse=True)
    for old in backups[14:]:
        old.unlink(missing_ok=True)
    return archive_path


async def database_backup_job(context: ContextTypes.DEFAULT_TYPE):
    try:
        archive = await asyncio.to_thread(_create_database_backup)
        logging.info("[BACKUP] Backup database dibuat: %s", archive.name)
    except Exception:
        logging.exception("[BACKUP] Backup database gagal")


async def _archive_legacy_log_job(context: ContextTypes.DEFAULT_TYPE):
    try:
        archived = await asyncio.to_thread(_archive_legacy_log)
        if archived:
            logging.info("[LOG] Legacy bot.log diarsipkan sebagai %s", archived.name)
    except Exception:
        logging.exception("[LOG] Gagal mengarsipkan bot.log lama")


async def web_full_sync_job(context: ContextTypes.DEFAULT_TYPE):
    """Dorong seluruh data (premium/token/ledger/invoice/trial) ke dashboard
    tiap 10 menit — jaring pengaman kalau ada push realtime yang gagal saat
    web sempat mati. Fire-and-forget: error apa pun ditelan.

    LOKAL-FIRST: bot adalah sumber data, D1 hanya mirror untuk display
    website. Push selalu dari lokal (satu arah lokal → D1), tidak pernah
    sebaliknya. Tidak perlu safety check count — lokal selalu dianggap benar.
    """
    if not WEB_SYNC_URL or WEB_SYNC_KEY == "GANTI_DENGAN_SYNC_KEY":
        return

    def _dump():
        payload = {"tables": {}}
        try:
            _premium_db.execute("SELECT user_id, expired_at, package, days, total_paid, "
                        "buy_count, updated_at, invoice_id, granted_by FROM premium_access")
            payload["tables"]["premium_access"] = [
                {"user_id": r[0], "expired_at": r[1], "package": r[2], "days": r[3] or 0,
                 "total_paid": r[4] or 0, "buy_count": r[5] or 0, "updated_at": r[6],
                 "invoice_id": r[7], "granted_by": r[8]}
                for r in _premium_db.fetchall()]

            _premium_db.execute("SELECT user_id, balance, total_bought, total_spent, "
                        "total_refund, updated_at FROM premium_tokens")
            payload["tables"]["premium_tokens"] = [
                {"user_id": r[0], "balance": r[1] or 0, "total_bought": r[2] or 0,
                 "total_spent": r[3] or 0, "total_refund": r[4] or 0, "updated_at": r[5]}
                for r in _premium_db.fetchall()]

            _premium_db.execute("SELECT id, user_id, delta, balance_after, kind, ref, note, "
                        "created_at FROM token_ledger ORDER BY id DESC LIMIT 500")
            payload["tables"]["token_ledger"] = [
                {"id": r[0], "user_id": r[1], "delta": r[2], "balance_after": r[3],
                 "kind": r[4], "ref": r[5], "note": r[6], "created_at": r[7]}
                for r in _premium_db.fetchall()]

            _premium_db.execute("SELECT invoice_id, user_id, package, kind, days, tokens, amount, "
                        "fee, total, status, paid_at, created_at FROM premium_invoices "
                        "ORDER BY created_at DESC LIMIT 800")
            payload["tables"]["premium_invoices"] = [
                {"invoice_id": r[0], "user_id": r[1], "package": r[2], "kind": r[3],
                 "days": r[4] or 0, "tokens": r[5] or 0, "amount": r[6] or 0,
                 "fee": r[7] or 0, "total": r[8] or 0, "status": r[9],
                 "paid_at": r[10], "created_at": r[11]}
                for r in _premium_db.fetchall()]

            _premium_db.execute("SELECT user_id, used, first_used_at, last_used_at "
                        "FROM resetotp_trial")
            payload["tables"]["resetotp_trial"] = [
                {"user_id": r[0], "used": r[1] or 0, "first_used_at": r[2],
                 "last_used_at": r[3]} for r in _premium_db.fetchall()]
        except Exception as e:
            logging.debug("[WEB] full-sync dump gagal: %s", e)
            return None
        return payload

    try:
        payload = await asyncio.to_thread(_dump)
        if payload:
            await asyncio.to_thread(_web_post, "/sync", payload)
    except Exception as e:
        logging.debug("[WEB] full-sync gagal: %s", e)


async def premium_invoice_poll_job(context: ContextTypes.DEFAULT_TYPE):
    """Poll invoice pending: auto-aktifkan kalau sudah dibayar, tandai expired
    kalau lewat PREMIUM_INVOICE_TTL_MIN. Jalan tiap menit.

    User tidak wajib menekan SUDAH BAYAR — job ini yang mengaktifkan akses
    dan mengirim notifikasi ke chat user.

    LOKAL-FIRST: hanya invoice di premium_bot.db yang di-poll (masing-masing
    bot memproses invoice buatannya sendiri). D1 hanya mirror display.
    """
    now = _now_utc()
    try:
        _premium_db.execute(
            "SELECT invoice_id, user_id, package, kind, days, tokens, total, created_at, expired_at "
            "FROM premium_invoices WHERE status = 'pending' "
            "ORDER BY id DESC LIMIT 5")
        rows = _premium_db.fetchall() or []
    except Exception:
        rows = []

    # LOKAL-FIRST: hanya invoice yang ada di premium_bot.db yang di-poll.
    # D1 tidak dibaca — masing-masing bot memproses invoice buatannya sendiri.

    for idx, (inv_id, uid, pk, kind, days, tokens, total, created_at, expired_at) in enumerate(rows):
        if not inv_id:
            continue
        # Gateway rate-limit 1 request / 5 detik → beri jeda antar invoice.
        if idx:
            await asyncio.sleep(6)

        # Batas hidup invoice: pakai expired_at dari gateway kalau ada,
        # fallback ke created_at + TTL. Grace 5 menit supaya pembayaran
        # yang masuk mepet deadline masih tertangkap.
        deadline = _parse_iso(expired_at)
        if not deadline:
            created = _parse_iso(created_at)
            deadline = (created + timedelta(minutes=PREMIUM_INVOICE_TTL_MIN)) if created else None
        if deadline and now > deadline + timedelta(minutes=5):
            try:
                _premium_db.execute("UPDATE premium_invoices SET status = 'expired' "
                            "WHERE invoice_id = ? AND status = 'pending'",
                            (inv_id,))
                _premium_db.commit()
                logging.info("[PREMIUM] invoice %s ditandai expired", inv_id)
            except Exception:
                pass
            continue

        # LOKAL-FIRST: cek status langsung ke gateway (buatqris).
        # D1 tidak dibaca lagi — premium_bot.db adalah sumber kebenaran.
        st = await asyncio.to_thread(_mgpay_check_status, inv_id)
        if not st:
            continue
        status = str(st.get('status') or '').lower()
        if status not in ('paid', 'success', 'settled', 'completed'):
            continue

        try:
            _premium_db.execute("UPDATE premium_invoices SET status = 'paid', paid_at = ? "
                        "WHERE invoice_id = ? AND status = 'pending'",
                        (_iso(now), inv_id))
            _premium_db.commit()
            if _premium_db.rowcount == 0:      # sudah diproses handler SUDAH BAYAR
                continue
        except Exception:
            continue
        _web_push_invoice(inv_id)

        info  = _pkg_info(pk)
        kind  = kind or 'days'
        if kind == 'token':
            tok_i   = int(tokens or 0)
            label   = info["label"] if info else f"{tok_i} Token"
            new_bal = add_tokens(uid, tok_i, kind='buy', ref=inv_id, note=f"beli {label}")
            logging.info("[PREMIUM] auto-token %s → user %s (+%s, saldo %s)",
                         inv_id, uid, tok_i, new_bal)
            try:
                await context.bot.send_message(
                    chat_id=uid,
                    text=_screen('PEMBAYARAN BERHASIL', (
                        f"{em(E1,'✅')} <b>Token berhasil ditambahkan!</b>\n\n"
                        f"  {_DOT} <b>Paket</b>  {label}\n"
                        f"  {_DOT} <b>Token masuk</b>  <b>+{tok_i}</b>\n"
                        f"  {_DOT} <b>Saldo token</b>  <b>{new_bal}</b>\n"
                        f"  {_DOT} <b>Total</b>  {_rp(total or 0)}\n\n"
                        f"<i>1x RESET OTP = {RESETOTP_TOKEN_COST} token. "
                        f"Ketik /fix untuk lanjut Reset OTP.</i>"
                    ), 'Home › Premium › Aktif'),
                    parse_mode=ParseMode.HTML)
            except Exception as e:
                logging.warning("[PREMIUM] notif auto-token ke %s gagal: %s", uid, e)
            continue

        days_i = int(days or 1)
        new_exp = grant_premium(uid, days_i, granted_by=None,
                                invoice_id=inv_id, amount=int(total or 0))
        label = info["label"] if info else PREMIUM_PACKAGES.get(pk, (f"{days_i} Hari", 0, days_i))[0]
        logging.info("[PREMIUM] auto-aktif %s → user %s (%s)", inv_id, uid, label)
        try:
            await context.bot.send_message(
                chat_id=uid,
                text=_screen('PEMBAYARAN BERHASIL', (
                    f"{em(E1,'✅')} <b>Akses RESET OTP aktif!</b>\n\n"
                    f"  {_DOT} <b>Paket</b>  {label}\n"
                    f"  {_DOT} <b>Total</b>  {_rp(total or 0)}\n"
                    f"  {_DOT} <b>Aktif s/d</b>  <b>{_fmt_wib(new_exp)}</b>\n\n"
                    f"<i>Terima kasih! Ketik /fix untuk lanjut Reset OTP.</i>"
                ), 'Home › Premium › Aktif'),
                parse_mode=ParseMode.HTML)
        except Exception as e:
            logging.warning("[PREMIUM] notif auto-aktif ke %s gagal: %s", uid, e)


async def health_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Ringkasan kesehatan internal, dibatasi untuk owner/admin."""
    user_id = update.effective_user.id
    if not (is_owner(user_id) or is_admin(user_id)):
        await update.message.reply_text(
            _plain_screen("HEALTH", "<b>AKSES DITOLAK</b>\n\nPerintah ini hanya untuk owner/admin."),
            parse_mode=ParseMode.HTML,
        )
        return
    try:
        cur.execute("SELECT 1")
        db_state = "OK"
    except Exception:
        db_state = "ERROR"
    backup_dir = BASE_DIR / "backups"
    backups = sorted(backup_dir.glob("ivas_bot_*.zip"), key=lambda p: p.stat().st_mtime, reverse=True) if backup_dir.exists() else []
    last_backup = datetime.fromtimestamp(backups[0].stat().st_mtime).strftime("%Y-%m-%d %H:%M") if backups else "-"
    log_size = LOG_PATH.stat().st_size if LOG_PATH.exists() else 0
    uptime = int(time.monotonic() - _BOT_STARTED_AT)
    table = _plain_table([
        ('Uptime', f'{uptime // 3600}h {(uptime % 3600) // 60}m'),
        ('SQLite', db_state),
        ('JobQueue', 'Aktif' if context.job_queue else 'Tidak tersedia'),
        ('Monitor user', str(len(active_notif_monitor))),
        ('SMS forwarder', str(len(sms_aktif_users))),
        ('Log aktif', f'{log_size / (1024 * 1024):.1f} MB'),
        ('Backup terakhir', last_backup),
        ('Backup tersimpan', str(len(backups))),
    ])
    body = (
        "<b>HEALTH STATUS</b>\n\n"
        f"<pre>{html.escape(table)}</pre>"
    )
    await update.message.reply_text(
        _plain_screen("HEALTH", body, "Owner › Health"),
        parse_mode=ParseMode.HTML,
    )


_BOT_STARTED_AT = time.monotonic()


