    # ── DUAL-BOT: bot kedua jalan di thread + event loop sendiri ────────────
    # Handler di-clone dari app pertama (grup 0) — semua fitur identik.
    # Premium/token shared: kedua bot baca-tulis premium_bot.db yang sama
    # (PremiumDBProxy thread-safe) dan push ke D1 yang sama.
    # Top up di bot manapun → langsung terbaca keduanya (lokal-first).
    _dual_app_ref = {}

    def _clone_handlers(src_app, dst_app):
        """Salin semua handler + error handler dari app pertama ke app kedua."""
        for group, handlers in src_app.handlers.items():
            for h in handlers:
                try:
                    dst_app.add_handler(h, group=group)
                except Exception as e:
                    print(f"[DUAL-BOT] clone handler gagal: {e}")
        dst_app.add_error_handler(telegram_error_handler)

    def _run_dual_bot():
        """Thread target: event loop sendiri + lifecycle MANUAL (tanpa signal handler).

        run_polling() tidak bisa dipakai di non-main thread — ia memasang
        signal handler (set_wakeup_fd) yang hanya legal dari main thread.
        Jadi kita jalankan lifecycle-nya sendiri: initialize → start →
        updater.start_polling → run_until_stopped.
        """
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        dual_app = None
        try:
            dual_app = (
                Application.builder()
                .token(DUAL_BOT_TOKEN)
                .job_queue(None)          # tanpa JobQueue — jobs hanya di bot 1
                .concurrent_updates(True)
                .build()
            )
            _clone_handlers(app, dual_app)
            _dual_app_ref["app"] = dual_app
            print(f"✅ [DUAL-BOT] {sum(len(v) for v in dual_app.handlers.values())} handler cloned")

            async def _runner():
                await dual_app.initialize()
                await dual_app.start()
                if dual_app.updater:
                    await dual_app.updater.start_polling(
                        drop_pending_updates=True,
                        timeout=30,
                        bootstrap_retries=-1,
                    )
                print("✅ [DUAL-BOT] Bot kedua POLLING aktif")
                # Tunggu selamanya — thread daemon. Shutdown ditangani bot 1
                # (post_shutdown) atau process exit.
                await asyncio.Event().wait()

            loop.run_until_complete(_runner())
        except KeyboardInterrupt:
            print("\n👋 [DUAL-BOT] Bot kedua dihentikan")
        except Exception as e:
            print(f"❌ [DUAL-BOT] Bot kedua mati: {e}")
        finally:
            # Shutdown bersih (best-effort).
            if dual_app is not None:
                try:
                    if dual_app.running:
                        loop.run_until_complete(dual_app.stop())
                    loop.run_until_complete(dual_app.shutdown())
                except Exception:
                    pass

    if DUAL_BOT_TOKEN:
        _dual_thread = threading.Thread(
            target=_run_dual_bot, daemon=True, name="dual-bot-2",
        )
        _dual_thread.start()
        print("🤖 [DUAL-BOT] Mode 2-bot AKTIF — premium & token shared")

